next：第八十七章 小夫子

    如果是陈平安独自一人，哪怕是负重入山，一天走上一百里山路都不难，要知道这期间必然需要越溪过涧，攀崖援壁，所以陈平安这次带着红棉袄小姑娘，走得很轻松，以至于闲来无事，就开始练习走桩，因为有李宝瓶在身边，就没有用上那种气力和精神全力以赴的拳架，而是相对自然而然，甚至为了照顾李宝瓶，还要刻意放慢走桩速度和减小步伐间距，这就让好不容易找到诀窍感觉的陈平安，像是一下子被打回了原形，又变得别扭起来。

    两人此时已经走出差不多二十里路，李宝瓶犹有余力，并不显得难受煎熬，小姑娘只是伸手擦了擦额头汗水，问道：“小师叔，你是在练拳吗？”

    陈平安停下走桩，点头道：“对啊。”

    李宝瓶又问道：“那你知道你练的这套拳法，拳法的立身之本，源头的气府在哪里吗？”

    陈平安一头雾水，“怎么说？我只知道人身上有很多窍穴，我之所以能够几百个字，主要就是为了记住那些窍穴的名称。但是它们跟练拳到底有什么关系，我还没来得及问。有一位宁姑娘看过我的拳谱，没有告诉我，只说练拳一事，捷径走不得，要靠一点一点的苦功夫熬出来，你认识的阮姐姐则说她是练剑的，她家的家传运气路径，不好外传，所以当时我跟她没有深聊。”

    事实上，那时候的草鞋少年，觉得自己这辈子注定会在小镇走完，所以有的是时间和机会来询问阮秀。

    李宝瓶瞪大眼睛，一脸匪夷所思，加重语气道：“小师叔！你连这个都不知道，也敢练拳？你知不知道，胡乱练拳，尤其是外家拳，很容易伤及根本元气的。练武，其实就跟堪舆地师的寻龙找穴差不多，只不过地师们是找山川窍穴，武人是寻找、挖掘自己身体的宝藏，找到之后，你还要方式得当，才算在武道一途真正登堂入室了。不行不行，小师叔，我必须把这个跟你捋一捋，捋清楚了你才好学拳！”

    看她神色坚决，陈平安想了想，本就不是什么坏事，刚好前边有一处歪脖子老柳树，大半倾斜向溪水水面，好像一座未完成的拱桥，就拉着李宝瓶靠着树干休息，小姑娘性子跳脱，非要坐着，陈平安只好把她抱到树干上，自己站在一旁免得她跌落。

    她大大咧咧坐在树上后，像是一位初次在学塾授课的小夫子，神采奕奕，咳嗽一声，打算跟这位小师叔好好说道说道，以免误入歧途，万一真练坏了身体，那她不得悔青肠子心疼死啊？

    李宝瓶一本正色道：“我之所以清楚一些练武的大概，因为我家有个叫朱鹿的丫鬟姐姐，她从小就被老祖宗看出有习武天赋，我又跟她很亲近，朱鹿姐姐又是闷葫芦的人，只喜欢跟我说些心里话，所以我可知道练武是怎么回事。只可惜我六岁的时候，偷偷摸摸跟在朱鹿姐姐身后，走那个叫地牛桩的东西，好玩得很，最高的木桩子，都快有屋顶那么高了，但是有一次我脚底打滑，不小心摔了下去，其实我真没啥事，朱鹿姐姐还是被我连累，给老祖宗狠狠一顿罚，在那之后，朱鹿姐姐每次早晚习武练功，还有躲在屋子里泡药水桶子里的时候，就再也不带我玩儿啦。”

    陈平安有些心虚，小姑娘嘴里所谓的朱鹿姐姐，说不定就那天胸口和脑袋挨了自己两块瓦的矫健少女，当时他偷偷闯入李家大宅，用弹弓打碎了两只鸟食瓷罐，那个护在正阳山小女孩身边的婢女，率先发现了他的踪迹，很快就翻墙上了屋顶，最后朝他所在的屋顶这边飞身一跃，让陈平安每次事后想起，仍然觉得她很厉害。

    李宝瓶对于这位始终不愿意承认自己是小师叔的家伙，恨不得知无不言言无不尽，“打了个比方，胆小鬼石春嘉他们家，有间铺子，做生意做得好，就能够钱生钱，财源广进，所以石春嘉家的铺子，才能是我们小镇最老的几家老字号之一，但如果只出不进，不懂得招徕客人，那么很快就会捉襟见肘，店铺肯定就得关门，是吧？”

    一听到做生意啊赚钱啊，财迷陈平安立即就“开窍”了，恍然道：“每个人都有些家底，练拳练得好，就能够钱生钱，练不好，就是赔本买卖，如果根本就不去练武的话，倒是本本分分守着祖业？”

    李宝瓶想了想，点头道：“差不多是这个意思。小师叔，你听说过一个说法吗？叫练拳招邪，尤其是那些号称三年一出师、出门打死人的外家拳，拳势凶猛，大劈大挂，看着威风八面，打人的时候嚷着哼哼哈哈的，其实最伤身子骨了，因为他们根本就没有找到脉门，属于不得其法而入，很多人才到中年，就会落下一身的病，有没有晚年都不好说，就算有，也会很凄凉。因为他们练拳的第一天起，就不是在养气养身，而是在当败家子，挥霍祖业。”

    用李家老祖宗的话说，李宝瓶这丫头就是天生没屁股的，红棉袄小姑娘说到兴起，刚想要从老柳树干上站起来，就被她的小师叔一个眼神将念头按回去，悻悻然继续说道：“所以小师叔你一定要引以为戒啊，一定要找到练拳的真正法门，世间拳法千万种，之所以成就有高有低，前程有大有小，就看每一门拳法的最少两座本命窍穴，你找不找得到，找到之后，接下来就看能不能找出一条最佳路线，滋润最多的沿途窍穴，如春风化雨，滋润万物。哪怕拳谱品秩不高，但只要是正途，一样能够强身健体，延年益寿，可如果走了岔路，拳谱越好，越容易坏事。”

    陈平安陷入沉思，自己能够感受到那股气的存在，身体内就像有一条无家可归的小火龙，胡乱游走于一座大火炉，之前这条火龙有点类似无头苍蝇，随处乱撞，碰壁之后就转头，如今它的活动范围越来越大，但是最终都会返回腹部的那些气府附近，徘徊不定，像是出门玩耍的稚童，疲惫之后就想要回家，只是暂时尚未找到真正的家门口。

    这股玄之又玄的气流，一直没有给陈平安带来什么不适或是疼痛，反而让少年有一种大冬天晒太阳的暖洋洋感觉，陈平安对于身体五脏六腑的感知，很小就极其敏锐，所以对于自己哪里出了问题，很快就能察觉到，云霞山蔡金简当初在泥瓶巷说他活的不长久了，她可能觉得陋巷少年只当她是开玩笑，其实陈平安当场就确定了她的说法无误。

    既然察觉不到任何不妥，陈平安就对那股气流听之任之，内心深处还有一丝好奇，想要看一看它到底会选择哪座窍穴作为它的宅邸。

    李宝瓶晃荡着那双小腿，双臂环胸，“据说习武的根本是散气二字，霸道得很，跟练气士的养气炼气完全不同，后者是多多益善，锱铢必较，习武不一样，当你找到最初的那股气后，就像是要一座座关隘打杀过去，将原本栖居在窍穴气府内的气息，全部消除殆尽，转化换成最早的那一口气，最后全身上下，心意一动，一气呵成，转瞬之间，气流运转百里数百里，第九境甚至可以长达千里之远，一下子就调动起全身潜力，一员大将如臂指使千军万马，威势之大，可想而知，丝毫不比练气士御气凌空而行来得差。”

    李宝瓶突然神秘兮兮说道：“朱鹿姐姐就说那武道宗师，什么飞檐走壁根本不算什么，还能够跟练气士一样，御风远游，再往后，一旦跻身止境大宗师，宰杀那帮眼高于顶的练气士，就跟手拧鸡脖子似的，弹指杀人，信手拈来。”

    陈平安笑问道：“如果练武真的这么厉害，当然是好事，可为什么厉害不厉害，要用杀人容易不容易来衡量？”

    李宝瓶愣了愣，老老实实摇头道：“那我可没想过，是朱鹿姐姐这么说的，说这些话的时候，朱鹿姐姐向往得很，就像我每天做梦都想能够抓到一条鱼差不多吧。”

    小姑娘略作思量后，说道：“不过仔细想想，依照朱鹿姐姐的说法，好像习武之人和修行之人，天生就不对付，后者喜欢低看前者，觉得习武就是一门贱业，是资质不行、无法修行的可怜虫，所以视为下等人，把武人骂成是世俗王朝的看门狗。前者则就觉得那些修行之人，一个个眼高于顶，鼻孔朝天，不是什么好东西，凭什么武人在江湖摸爬滚打，就是侠以武乱禁，那些练气士分明只是一小撮人，却占据着无数的名山大川和洞天福地，还洋洋得意，自称山上仙人以术法神通修长生，受到山下凡人和武人的敬仰和供养，本就是天经地义的事情。”

    李宝瓶突然笑了起来，“不过这些争执，小师叔你不用管，没意思得很。”

    李宝瓶突然欲言又止，似乎想起了一件事，可又有些难以启齿，有点做贼心虚，最后决定还是坦诚相见，实在是不愿意欺骗她的小师叔，小姑娘哭丧着脸道歉道：“朱鹿姐姐和她爹朱河叔叔，本来是要跟我们一起去往大隋南方边境的，可是我怕小师叔你不喜欢他们，就骗他们去小镇东门那边等我们。如果朱河叔叔也在的话，他就能教小师叔练拳了，因为朱鹿姐姐从小就跟着她爹一起习武，老祖宗私下对我说过，虽然朱河练武天赋有限，但是教人习武是一把好手，称得上‘明师’这个说法，哪怕丢在大骊京城那些个‘府字头’的豪门大宅里，也可以成为座上宾。现在朱河叔叔不见了，朱鹿姐姐也不见了……”

    陈平安赶紧安慰道：“没事没事，我练拳虽然没有什么师父，只有一部拳谱。如今连拳谱上的字也没有认全，更不敢瞎练了。只练习一个走桩一个站桩，不过已经确定能够滋养体魄，不会伤身。要怎么练出名堂来，估计得等我自己读得懂那部拳谱再说。这个不急，我本来练拳，就不是为了什么境界，只是用来活命的，没想那么多。”

    可是李宝瓶显然已经在自己的想法上钻了牛角尖，而且思绪一去千万里，于是小姑娘越说越愧疚，嘴角往下，有哭的迹象了，“武人习武，师父领进门修行在个人，但是师父很重要的，领进门的这个门，门槛就有高有低，而且师父领进了第一扇大门后，是因为本事有限，不得不撒手不管了，还是能够一口气带到了后院门，情形是完全不一样的。所以师父一定要是明师，不能光找名气大的名师。”

    小姑娘抽着鼻子，泪水马上就要流出眼眶，“小师叔，你是百年一遇千年难逢的习武天才，如果因为我耽误了你成为高手，我该怎么办啊？”

    陈平安已经顾不上她怎么得出自己是天才的荒谬结论了，当务之急是别让她哭出来，小姑娘伤心起来，给人的感觉那是真伤透了心，全然不是一般孩子撒娇打闹的那种，陈平安灵机一动，突然抬起手，手掌放在小姑娘身前，轻轻握拳后，大声说了一个字，“收！”

    李宝瓶是脑子转动极快的聪明孩子，一下子就愣住了，止住了泪水决堤的趋势，“小师叔，你在做什么啊？”

    陈平安晃了晃拳头，哈哈笑道：“怎么样，小师叔厉害吧，让你一下子就不哭了。”

    为了安慰小姑娘，陈平安也算豁出去了，第一次正式承认自己是她的小师叔。

    小姑娘立即破涕为笑。

    她觉得不是自己不伤心了，而是开心多过了伤心。

    陈平安如释重负，双手撑在老柳树干上，然后身子一斜就坐在了小姑娘身边。

    两人脚底下，放着一大一小两只背篓。

    李宝瓶轻声道：“朱河叔叔经常告诉朱鹿姐姐，练拳不练真，三年鬼上身。练拳找着真，一拳打死神。习武之人，一旦生病，比起医治寻常人要棘手很多。朱鹿姐姐曾经有两次差点熬不过去，第一次过后，她整个人得有小半年没缓过来，那段时间像是个病秧子，平时连水桶也提不起来，第二次更惨，我听到动静后，就搬了一根小板凳过去，偷偷捅破窗户纸，结果看到朱鹿姐姐在床上痛得打滚，旁人按都按不住，最后她指甲盖都翻开了，鲜血淋漓，很可怜的，最后是家里请了杨家铺子的掌柜送药来，好像才不痛了，逐渐安稳下来。但是老祖宗当时站在院子门口，没有走进院子，摇摇头就转身走了，似乎有些惋惜和失望。我事后问起，老祖宗只说小命是靠药材保住了，第八境的希望却丢了，以后就不用太过栽培朱鹿姐姐了，否则反而是害她，如果运气好到洪福齐天的地步，就可以进入第七境，运气不好，第六境都悬。”

    李宝瓶转过头，忧心忡忡道：“小师叔，你可千万别这么生病啊，我什么都不懂，肯定会傻眼的！”

    陈平安笑道：“不会的，而且就算有，我当然是说万一啊，那你也别怕，我很能吃得住痛的，这可不是跟你吹牛。”

    李宝瓶将信将疑，伸出手在他胳膊上轻轻拧了一下，“小师叔，痛不痛？”

    陈平安拍了拍她的小脑袋，然后望向两人来时的小路，“知道小师叔觉得最难受的一次，是什么时候吗？”

    小姑娘拨浪鼓似的使劲摇头。

    陈平安双手撑在树干上，小腿交错，跟小姑娘一样优哉游哉轻轻摇晃着，少年眯眼，轻声笑道：“是我第二次一个人进山去采药，那时候我才四岁多，不到五岁，出门的时候，想着要采最多最多的药材回家，所以故意挑了一个最大的大箩筐，然后没等到走出小镇，就累死了，走出小镇能够看到山的时候，当时还是一个大太阳的日子，肩膀上被箩筐绳子扯得火辣辣疼，后背更是。其实那会儿疼还好说，不是特别怕，让我觉得绝望的事情是，那座山看着好远好远，就像这辈子都走不到那里。加上当时离着第一次进山出山没多久，所以脚底的水泡很快就造反了，然后小师叔我啊，就咬着牙一边走一边哭，还一边不断偷偷问自己，这还没有走到山脚，要不然就回家吧，反正年纪小，箩筐这么大，山路那么远，回家不丢人，娘亲肯定不怨你的。”

    李宝瓶听得入神，小声问道：“小师叔，那你最后放弃了没有？”

    草鞋少年笑着摇头道：“没呢，当时我就突然想到，不管怎么样，走到山脚就好，到那里再回头。然后我就真的走到了山脚，坐在地上哭的时候，又想了，要不然上了山，采到一棵草药再回家？然后就又开始爬山，爬着爬着，看到那些草药后，整个人好像一下子就有了力气，很奇怪的事情。”

    李宝瓶哇了一声，赞叹道：“小师叔，你一定摘了满满一箩筐草药才下山回家，对不对？！”

    小姑娘说到这里，满脸的与有荣焉。

    陈平安摇头道：“没呢，一直到太阳要下山了，草药还没盖住箩筐底，就下山了。一来是草药没那么好找，很难的，个子那么小，背着个大箩筐走山路，其实比采药更难，二来是真的很累了，再就是想着再不走，天黑后就要一个人留在山上，我那会儿当然很怕。只不过我最怕的……”

    李宝瓶等了半天，也没有等到下文，好奇问道：“小师叔最怕什么？”

    “没什么。”

    草鞋少年摇了摇头，柔声道：“后来就不怕了。”

    小姑娘善解人意地没有追问下去。

    陈平安回过神，转头对她笑道：“跟你说这些，可不是为了告诉你小师叔多厉害，其实小镇的苦孩子都是这么过来的，一点也不稀奇。我说这些，是觉得你今天跟我说那些习武之事的门道，说得很好，很像小师叔小时候偷偷跑去学塾后，看到齐先生授课时的样子。你不是说没有女先生女夫子吗，我觉得以后到了山崖书院，等你读够多的书后，说不定就能成为第一个在书院教书的先生夫子呢。”

    红棉袄小姑娘听到小师叔这么说之后，骤然焕发出昂扬的斗志，双拳扬起，“李宝瓶，你可以的！一定可以！”

    陈平安默默看在眼里，觉得如果齐先生还在世的话，一定也会很开心。

    只是接下来小姑娘说了句让少年头大的言语，“因为李宝瓶有一个天底下最了不得的小师叔啊！”

    少年只好假装什么都没有听到。

    草长莺飞的美好时节，少年和小姑娘并肩而坐，各自怀揣着美好的愿望。

    溪水对岸一处隐蔽地方，一个男人和一位少女盘腿而坐，吃着干粮。

    眼神充满锐气的少女没好气道：“爹，小姐跟着这么个憨憨傻傻的家伙，真能顺顺利利走到我们大骊边境？听说那边可是经常打仗呢，还有许多落草为寇的兵匪，很不安生。”

    男人调侃道：“难道忘了是谁把你教训了一顿？习武之后生平第一战，输了不说，还输得这么憋屈。”

    少女气呼呼道：“那是因为爹你不允许我擅自运转气机，怕我承受不住那股压力，现在我一只手就能撂翻那个泥瓶巷的家伙。”

    男人笑问道：“你这位武道二境高手，真的确定？”

    少女大声提醒道：“爹，是二境巅峰！”

    男人提起水壶喝了一口，摇头道：“你打不过他的，除非是点到即止的切磋武艺，你才有胜算。”

    少女显然不信，那少年撑死了才刚刚步入武道大门，之前在李家大宅屋顶上两人对峙，他只不过占着地利才侥幸得手。

    男人打趣道：“你就是个没良心的，人家在宅子里跟你对上，打得你跌向地面的时候，还不忘拉了你一把，要换上是爹，与人对敌，不给你脑袋上加一瓦片，就算很厚道了。”

    “所以说他傻啊。”

    少女冷笑道：““习武之人，妇人之仁，这种人，活不长久！”

    男人一脸讶异道：“你一个丫头片子，武艺不精，武道不高，大道理倒是一套一套的，谁教你的？反正我可没跟你说过这些话。”

    少女扬起下巴，“咱们二公子说的！二公子虽然是满腹韬略的读书人，可他从不满嘴仁义道德，只说慈不掌兵，必须杀伐果断。”

    男人皱了皱眉头，正要跟这个缺心眼的闺女好好说些正经道理，突然站起身，沉声道：“过河！”

    少女跟着起身，“爹，怎么回事，不是说悄悄跟着小姐就好吗？”

    男人语气并不轻松，“有人来了。等下小心！”

    父女二人，一掠过河，飞奔而去。

    陈平安和李宝瓶刚刚离开老柳树，重新动身赶路，就发现遇到了一个人出现在视野尽头。

    陈平安先是放下背篓，然后让李宝瓶站在自己身后。

    若说在小镇东边，遇到什么人，哪怕是神仙妖魔鬼怪，陈平安都不奇怪。

    但是在这条即将连道路也会消失的南下线路上，不管遇到谁，陈平安都不敢掉以轻心。

    远处。

    一个身材不高大也算不上壮实的汉子，向陈平安和李宝瓶迎面而来，只见他牵着一头白色驴子，头戴斗笠，斜挎着一条布囊，腿上裹了行缠，手持一根竹杖，腰间则悬挂着一把绿色……竹鞘长刀？

    男人在五六步外停下脚步，没有继续走近，他摘下斗笠，露出一张并不出奇的脸庞，微笑道：“你是陈平安吧？你好，我叫阿良，善良的良。”

    最后男人补充了一句，“我是一名剑客。”
------------

next：第八十八章 粉墨登场

    陈平安瞥了眼这名不速之客的腰间绿竹刀鞘，故作疑惑不解，问道：“剑客？”

    汉子一手持斗笠，一手轻拍刀柄，微笑道：“暂时找不到配不上我的剑，所以只好以此代替，用来羞辱天下用刀之人。”

    听到这种有些熟悉的语气，陈平安反而松了口气，觉得刘灞桥应该能够跟这个男人做好朋友。

    在陈平安和李宝瓶身后，那对父女并肩缓缓而行，少女朱鹿有些不以为然，讥笑道：“龙王打哈欠，能吸进一条江，真是好大的口气，爹，这家伙是不是脑子有问题？”

    朱河看到那汉子腰另一侧还挂着个银白色酒葫芦，巴掌大小，摩挲得油滑光亮，一看就是有些年头的老物件，对自己闺女小声道：“虽然察觉不到他的气机有什么异样，只是比寻常人绵长些许，但还是要小心。爹虽然这辈子没出过远门，可听老祖宗说过不少江湖轶事，说是行走江湖，要小心道姑老僧小孩和酒鬼，除此之外，越是看着不像是宗师高手的角色，越不能掉以轻心。”

    少女哦了一声，既紧张又兴奋，恨不得那貌不惊人的汉子就是刺客杀手，正好作为她初出茅庐的磨刀石。

    陈平安问道：“你找我？”

    汉子咧嘴笑道：“我送你到大隋边境，在那之前，我们结伴而行，好有个照应。”

    陈平安试探性问道：“你认识打铁的阮师傅？”

    汉子点头道：“当然认识。”

    陈平安又松了口气。

    离开小镇之前，作为交易之一，阮师傅答应过自己，在到达大骊边境兵家重地野夫关之前，会保证自己的安危。

    陈平安相信阮师傅不会食言，尤其是此人出现得这么早，几乎是在阮师傅的眼皮子底下冒头，所以应该不是正阳山、云霞山和老龙城三方势力之一。而且身后朱河朱鹿这对父女的及时出现，也带给陈平安很大底气。

    但是，陈平安怕万一。

    所以他问道：“那你陪我去小镇那边见一见阮师傅，我们再动身南下？刚好我才知道其实小镇东门出去，虽然绕路，但有驿路可行，牛车马车都可以走，反而比我们翻山过水更快。”

    汉子笑容玩味道：“这么谨慎？一点都没有江湖儿女的豪爽嘛。”

    陈平安没有转头，眼睛始终死死盯住那名汉子，不过沉声道：“朱河，你能不能让朱鹿带着宝瓶先回小镇。我们不急。”

    朱河一下子就想通其中关节，点头道：“这样最好。”

    然后朱河对女儿说道：“鹿儿，你带着小姐先回去。我和陈平安陪一陪这位阿良兄弟，喝酒也好，切磋也罢，相逢是缘，都不过分。”

    被朱鹿牵在手里的红棉袄小姑娘，没有任何犹豫，没有哭着喊着要和她的小师叔在一起，只是扯了扯陈平安的袖子，轻轻说了小心两个字，然后就果断跟着朱鹿快步离去，李宝瓶毫不拖泥带水，反而是初生牛犊不怕虎的婢女满怀失望，很希望自己跟她爹换一个位置。

    那汉子看到这一幕生离死别后，翻了个白眼，摘下酒葫芦，斜靠那头白色毛驴，喝了一口酒，嗤笑道：“让那小妹儿带着那小丫头先走便是，一炷香后，咱们三个大老爷们再去小镇。”

    然后汉子扬起手中银白色的酒葫芦，伸手拍了拍毛驴的背脊，望向朱河，笑问道：“你也算一方好手了，难道不认得这玩意儿？”

    他拍了拍自己脑袋，“忘了你们骊珠洞天才刚刚打开，你知道才是怪事。没关系没关系，我们可以慢慢聊，大把大把的时间。”

    这汉子指了指那棵横向溪面的老柳树，“我们去那边坐着聊？”

    陈平安和朱河相视一眼，觉得如此最好，大可以静观其变。

    汉子牵着那头白色毛驴，跟在陈平安和朱河身后，到了老柳树旁边，松开缰绳，任由驴子随意啃食青草，他走上柳树，沿着主干一直走出溪岸，最后坐在下，重新戴起那顶斗笠后，提起银白酒葫芦，正要仰头灌酒，突然转过头，递出酒壶，笑问道：“谁想要来一口？独乐乐不如众乐乐，二两银子一两的魁罡仙人酿，是大隋所有富家翁的心头好，我一路北上，喝来喝去，尝过不下百余种酒，还是这仙人酿最地道。”

    陈平安摇摇头，“我不喝酒。”

    朱河也摇头，“习武尚未大成，不敢饮酒。”

    汉子跟着摇摇头，看着他们，满脸遗憾道：“原来都不是性情中人啊，我前不久认识一位少侠，那真是风流倜傥……”

    这位汉子突然发现陈平安和朱河脸色古怪，他有些疑惑，可又不好失了高手风范，只好喝了口酒，掩饰自己的茫然。

    陈平安轻轻咳嗽一声，汉子问道：“何事？”

    陈平安伸出手指，指了指这棵歪脖子老柳树最外边的地方。

    汉子皱了皱眉头，转头望去，结果看到两条腿挡住了视线，汉子瞬间脸色僵硬，猛然抬头，看到一个面无表情的中年男人，最少有一百五六十斤重的家伙，竟然就轻飘飘站在粗细不过的柳树梢头上，此人的神出鬼没，吓得斗笠汉子一个坐不稳，摔入溪水，狼狈至极。

    来者正是兵家圣人阮邛，如杨老头所说，他对千里山河之内的动静，并无兴趣，除非是崔瀺这种坏了规矩的挑衅，一心铸剑的阮邛才会出手。阮邛并不觉得有人胆敢在方圆百里之内，就对陈平安出手，那简直就是在打他阮邛的脸，但是一位兵家剑修十一楼的脸面，比起一座王朝的脸面，只重不轻。所以阮邛根本就懒得留神这边的光景，一个草鞋少年和一个天真烂漫小姑娘的结伴远行而已，怎么可能值得他亲自盯着？

    但是阮邛被一件东西牵扯到了心神。

    有人一晃那物件，阮邛立即就感受到了物件之内，蕴藏着的磅礴剑气，精纯且浩瀚，尤其是感觉极其熟悉，透着一股亲昵和哀伤，关于此事，阮邛在宗门内修行多年，虽然从未亲眼看到，但早有耳闻，所以立即从铁匠铺子赶来。

    此时看到那人比凡俗夫子还不如的作态，阮邛对此非但没有讥讽之意，反而多出一丝凝重，问道：“可是神仙台魏晋？”

    跌落小溪的汉子一阵扑打，好不容易才站直身体，从溪水里捡起那只酒壶后，摘下头顶斗笠甩了甩，抬头看着那个罪魁祸首，没好气道：“我叫阿良。”

    阮邛居高临下盯着他，充满审视意味，问道：“能不能借我喝两口酒？”

    汉子一把丢出酒葫芦，高高抛向阮邛，“有何不可？不过记得还我。”

    阮邛接过酒壶，喝了口酒，笑问道：“竟然不是五黄酒？”

    汉子一听到这个就火大，白眼道：“涨价了。”

    阮邛哈哈大笑，丢回酒葫芦，问道：“你怎么来得这么快？我还以为最快也得一旬左右。”

    自称阿良的汉子湿漉漉走上岸，一边骂骂咧咧道：“你管得着？圣人了不起啊。”

    阮邛问道：“要不要去我铺子坐坐？我女儿对你仰慕得很。”

    阿良指了指自己，笑呵呵道：“对我？那你女儿眼光真好。”

    阮邛似乎早就晓得此人的荒诞不经，问道：“莫非这次是你负责龙脊山一事？”

    阿良摆摆手，“不是我，另外有人。”

    阮邛看着兴致不高的斗笠汉子，突然笑了起来，“难不成北上途中，你遇上了那位小道姑？”

    阿良脸色如常，“你说什么，我听不懂。”

    阮邛心中叹息，不再试探，也不再多说。

    阮邛出身的风雪庙，有一位大名鼎鼎的剑修，年轻且天才，极少待在宗门，哪怕是风雪庙内，也有人不知道此人姓名。他年少时被一位下山游历的风雪庙老祖相中，收为闭关弟子，所以辈分极高，使得他第一次上山的时候，不过及冠之龄，好些百岁高龄的修士都得乖乖喊他一声师祖，后来那位风雪庙的中兴老祖，破关失败，加上这一脉人才凋零，年轻剑修就与风雪庙关系更加疏远了。

    此人动辄行走江湖七八年，除了师父忌日的时候才会偶尔出现在宗门，仍是独来独往，哪怕回到风雪庙，也从不与人打招呼。听说他很早就得到一只价值连城的养剑葫，可他竟然不用来温养飞剑，反而暴殄天物，用来装醇酒千百斤，一年最少有半年喝得大醉酩酊，因此被誉为醉酒剑仙人，一喝醉就由着一头雪白毛驴驮着，毛驴走哪里是哪里。

    阮邛在脱离风雪庙之前，听说此人不知为何，对一位被誉为“福缘冠绝一洲”的年轻道姑，一见钟情，从此深陷其中不可自拔，没奈何郎有情妾无意，貌美道姑根本无心寻找道侣，此事就成了一桩轰动宝瓶洲的山上趣闻。

    阮邛想了想，“既然如此，那就有劳你送他们去大骊野夫关了。”

    那汉子点了点头。

    阮邛抱拳告辞，身形一闪而逝。

    唯有柳树枝头轻轻摇晃。

    朱河小心翼翼问道：“阿良……前辈是风雪庙的仙人？”

    汉子牵着毛驴，懒洋洋道：“我跟风雪庙不熟。”

    朱河笑着，一点也不尴尬。

    世间武人，对于练气士可能观感都不好，但是对于风雪庙和真武山的修士，那还是要伸一下大拇指的。

    之前朱河可能会觉得此人口气比天大，姿态矫揉做作，可在圣人阮邛这趟来去之后，朱河现在回头再看，眼前这位相貌平平的斗笠汉子，就真是真人不露相，神仙大隐隐于市。估摸着那柄绿色竹鞘长刀，肯定是一把只要拔刀出鞘，就会是惊世骇俗的神兵利器。

    阿良喝了一大口酒暖身，对陈平安说道：“那个小姑娘回来了。”

    陈平安转头望去，不但李宝瓶和朱鹿原路返回，还有两张熟悉面孔，和一头两侧悬挂沉重行囊的骡子。

    李槐和林守一。

    陈平安小跑过去，李宝瓶一脸闷闷不乐，朱鹿嗓音清脆开口道：“这两个孩子是我们半路遇上的，说是要跟小姐一起去山崖书院求学。咱们老祖宗刚才现身打过招呼了，让我回头找你们。”

    陈平安不去问朱鹿所谓的老祖宗是谁，望向鬼头鬼脑的李槐和落魄贵公子似的林守一。

    李槐硬着脖子，理直气壮道：“我不跟着你们混饭吃，难道在小镇当乞丐要饭啊。”

    林守一依旧是冷冷的样子，道：“富贵险中求。”

    李宝瓶冷哼道：“你们可以从东门出发，自己去书院啊。凭什么小师叔和我要带上你们两个拖油瓶？”

    李槐怒道：“李宝瓶！我们好歹是同生共死过的患难之交！”

    林守一没有李槐这么无赖，坦诚道：“我和李槐别说山崖书院，就是大骊边境都走不到。”

    陈平安点了点头，用手轻轻按在李宝瓶头上，阻止她说话，然后问道：“那石春嘉和董水井两个，是不是确定不来了？”

    林守一解释道：“压岁铺子那边，有人会带石春嘉去京城，董水井听说以后小镇乡塾会再开起来，就在铁匠铺子顶替你的短工。”

    陈平安看着李宝瓶、李槐和林守一三个学塾蒙童，笑道：“那就一起动身赶路。”

    阿良把那头白色毛驴从溪畔牵回来，看到李槐林守一后，一脸不情愿道：“多带一个可爱的小姑娘就算了，可是你们两个兔崽子算怎么回事？”

    李槐破口大骂道：“你哪根葱？！”

    阿良面不改色回答道：“我是你失散多年的爹，亲爹。”

    李槐如遭雷击，死死盯住这个陌生男人。

    那汉子反而被瞧得心里发毛，难道这小王八蛋他爹娘真有一段不可告人的故事？

    李槐迅速改变原先的呆滞神色，扯了扯嘴角，斜眼看那斗笠汉子，一脸嫌弃，嘀咕道：“跟我斗？”

    汉子吃瘪，啧啧道：“呦呵，水浅小王八多啊。”

    李槐双手抱住后脑勺，念叨道：“不听不听王八念经。”

    陈平安没来由问了一句，“阿良，你为什么会说我们的小镇方言？”

    汉子笑眯眯道：“你去问阮邛。”

    陈平安看着他，突然笑了，“算了。”

    汉子伸手指了指陈平安，教训道：“小小年纪，心思这么重可不好。”

    自称剑客却佩刀的阿良，和他的那头白色毛驴。

    各自背着背篓的陈平安和李宝瓶，两手空空的李槐和林守一，还有走在最后面的朱河朱鹿父女。

    身份悬殊的七个人，共同南下。

    因为这个跟阮师傅来自同一个地方的阿良，说来时的路走得并不难，而且顺着铁符河一直往南，很快就可以看到正在日夜建造的大骊驿路。

    不过接下来的停停歇歇，阿良仍然愿意听从陈平安的意见。

    李槐在休息间隙，跑到问那斗笠汉子，一点也不怕生，叉腰问道：“喂！阿良，你这毛驴是公的母的？”

    汉子倒是不讨厌这个孩子，就是有点烦，“关你屁事。”

    “给我骑骑呗？”

    “我自己都不舍得骑，你凭什么？真当自己是我亲儿子啊。”

    “你要是把驴子送我，我回头让我娘改嫁，咋样？当然，要是我娘不答应的话，可怪不得我，这驴子还是得归我。”

    “滚你和你娘的！”

    “阿良啊，不是我说你，今后你这脾气得改改。”

    李槐双手负后，摇头晃脑地叹息离去。

    留下一个大开眼界的斗笠汉子。

    溪畔，两人走向铁匠铺子，一位是阮邛，一位是白发苍苍却满脸红光的老人，后者便是婢女朱鹿嘴里的老祖宗，小镇四大姓之一李氏的真正主心骨。

    李宝瓶这么个心肝宝贝，对其寄予厚望的李氏家族，当然不会只让那对父女贴身扈从，如果不是阮师今天露面，练气有成的李家老祖会一路护送到那座野夫关。

    老人苦笑道：“阮师，此人便是你从风雪庙请来的帮手？看着实在是……”

    阮邛直截了当道：“根本不像是高手，反倒像是个市井混子，对吧？”

    阮邛缓缓道：“我接过酒葫芦喝酒的时候，仔细查探过，那只养剑葫内的本命剑气，生机犹在，确是风雪庙真传无疑，而且风雪庙神仙台这一脉，本就人少，魏晋更是不喜与人结交的冷淡性子，反而喜欢浪荡江湖，性子奇怪一些，很好解释。虽然世间也有杀人之后，成功夺取本命物的阴毒手段，可是魏晋修为绝对不低，想要在他身上顺利夺走养剑葫和那缕剑气……”

    阮邛笑了起来，“那么今天就算我阮邛出手，也拦不住那人想要做的事情了。”

    老人叹了口气，“话不能这么说，如果三教一家没有取走压胜之物，阵法还在，许多事情阮师就不用如此束手束脚了。”

    阮邛想了想，“稍后我还是要去跟风雪庙大鲵沟一脉的人，碰个头，了解一下情况，他们距离这里也不远了。刚好关于龙脊山瓜分斩龙台一事，当着真武山的人，不好直说。在此期间，如果小镇有任何意外，麻烦李老找到秀秀，让她飞剑传书便是。”

    风雪庙，真武山，是东宝瓶洲两大兵家祖庭，一南一北，双方关系一直不好不坏，大体上属于井水不犯河水，当然在涉及大是大非的关键时刻，肯定会放弃门户之见，选择联手对敌。

    其中真武山更注重山下世俗王朝的发展，大骊王朝就有许多真武山的修士，已经覆灭的卢氏王朝，大隋高氏麾下，都有真武山修士的影子，多是沙场大将的贴身扈从，或是掌握实权的中层武将。

    风雪庙则倾向于独善其身，来往于各大古战场遗址，有点类似江湖上的游侠，身负绝顶武艺，万事由心，高兴了，就斩妖除魔行侠仗义，不高兴了，就寻人切磋道法剑术，多是硬闯山门不请自去，主人答应不答应，都得陪着他们打过一架再说其他。不过风雪庙这些脾气古怪的家伙，打架不为扬名，更不会杀人，所以哪怕被风雪庙的修士揍得灰头土脸，但不用担心家丑外扬。

    关于飞剑一事，老人疑惑道：“阮师，我家宅子那边也有数柄品质不错的传信飞剑……”

    阮师笑着摆摆手，“不一样的，相差不小。”

    老人立即了然，赧颜道：“在阮师跟前谈飞剑，贻笑大方，贻笑大方了。”

    阮邛突然轻声感慨道：“树欲静而风不止啊。”

    一位身材小巧玲珑却丰腴的宫装妇人，行走在泥瓶巷。

    身后远远跟着三人，一位中年男子身材魁梧，神色刚毅。

    一老人面白无须，似乎视力孱弱，始终眯着眼。

    一年轻女子怀揣着一把长剑，那串金色剑穗，刚好蜷缩在她丰满的胸脯上。

    那妇人最终在宋集薪家的院门口停下，笑道：“偷春联这种事情，只有崔瀺做得出来。”
------------

next：第八十九章 两颗人头

    个子矮小却体态妖娆的丰韵妇人，掏出一串做工精致的崭新钥匙，打开院门，推门而入的时候笑道：“总算有用武之地了。”

    妇人瞥了眼墙脚根的鸡笼，那边传来一阵阵扑簌扑簌的家禽振翅声，她愣了愣，“还没饿死？”

    “还是得谢我啊，帮你找了这么个好邻居，邻里和睦，天下同春嘛。”她很快想明白了其中缘由，转头望向隔壁，发现自己个子不高的缘故，看不到那边的光景，只好走到那堵黄泥墙边，踮起脚跟，发现隔壁只有空落落的院子，觉得无趣乏味，很快收回视线，走向正屋大门，又掏出钥匙开门，跨过门槛后，伸出手指在桌子上一抹，纤尘不染，妇人有些不太高兴，像是有外人擅自主张在自家闺女脸上涂抹胭脂，好看归好看，可当爹做妈的当然不乐意。

    跟随妇人来到泥瓶巷的三名扈从，魁梧男子留在院外泥瓶巷当中，闭目养神。

    面白无须的眯眼老人走到院中。

    唯独那名捧剑女子跟随妇人走入正屋。

    妇人独自走入宋集薪的住处，环顾四周，床榻书桌皆有，书桌上还留下一些价格不菲的清供雅玩，应该是主人不愿随身携带，便干脆弃之不用了。妇人走到书桌旁，发现正中央还叠放着三本书籍，随手一翻，并无出奇，只是寻常学塾蒙童的入门书籍，小学，礼乐，观止，是大骊王朝豪阀市井贵贱通用的蒙学经典，妇人发现三本书旧归旧，却没有半点泥垢污渍，脑海中一下子浮现出某个人的形象，妇人摇摇头，随口问道：“杨花，小学这本书在大骊京城市价多少？”

    背对房门的捧剑女子嗓音天生清冷，恭谨回答道：“奴婢回娘娘的话，多则六十文，少则四十文。”

    妇人哦了一声，啧啧道：“看来是儒家圣贤们的道理越大，越不值钱啊。”

    妇人重新将三本蒙学经典叠放于原位，轻轻拍了拍摆在最上边的观止，她流露出一丝讥讽，冷笑道：“要不是有小说家帮着推波助澜，千百年来不遗余力地行走于大城雄镇、市井巷弄，为其美言，自己则心甘情愿做那不入流的稗官野史，儒教也坐不了这座天下，肯定坐不稳。”

    院内老人轻轻咳嗽一声，低声道：“娘娘还需慎言，此地不宜畅所欲言。”

    妇人笑道：“放心便是，齐静春死后跟上边达成协议，所以这里不会有人再盯着了，你以为没了齐静春，死水一潭的骊珠洞天，一个几千年都没有出过大纰漏的地方，当得起那些大人物的重视？”

    老人仍是坚持己见，“娘娘还是小心为妙。”

    妇人嫣然一笑，柔声道：“行了行了，我不牢骚这些便是。徐浑然，这点你真得学学梁崧，人家就比你懂得察言观色。所以要我看啊，大骊朝野说梁崧虽然是你的弟子，却青出于蓝而胜于蓝，一点也没冤枉你。至于我家叔叔故意用话刺你，说什么弟子不必不如师，徐浑然你倒是不用在意，他就是那么一个人，稍稍听说几句读书人的话，就喜欢乱掉书柜。”

    名叫徐浑然的老人哭笑不得，唯有一声叹息，心想没有娘娘你这么安慰人的。

    只是一想到南下途中与那位藩王的擦肩而过，老人心情陡然凝重起来。当时宋长镜虽然看着疲态，像是一场生死大战之后重伤未愈，可他既然敢当着自己的面，主动掀起车窗帘子，那么就意味着宋长镜极有可能在武道一途，百尺竿头更进一步，虽然跻身第十境的可能性极小，但是到了第九境巅峰后，宋长镜每一次向前走出，哪怕只有半步，那么对于七八境武道宗师而言，小小半步的差别，可能就是相当于他们的一境之差。

    这位面白无须的老人，享誉大骊朝野，被誉为大骊第一剑师，师字这个后缀，如诸子百家中，某人姓氏之后的“大家”二字，分量很重。那名死于宋长镜之手的天才剑修梁崧，正是徐浑然最得意的弟子，老人将其视为己出，此仇不可谓不大。

    徐浑然喜好在袖中养剑，剑名为白雀。寸余长短，却杀力极大，传言瞬间可以来回飞掠百余里，剑已回袖，人尚未死绝，手段凌厉，鬼神莫测。

    妇人在那张床上坐下，抬手拍了拍床板，“算不上富贵人家的日子，不过还挺自在。”

    怀抱长剑的年轻女子轻声道：“娘娘对殿下用心良苦，苦其心志，劳其筋骨。”

    妇人站起身，笑道：“这话就虚伪了，真正受苦的孩子，是隔壁那个孤儿，我家睦儿可称不上吃苦。”

    她走到墙壁前，想了想，喃喃道：“福禄街卢氏送给咱们的几页古书，上边记载的法术神通，历史久远，已经不可考据，跟当今道教几大符箓派差异很大，我记得其中一页，记载了一门有趣的小法术，咒语是什么来着？哦，记起来了，试试看。”

    妇人背对着门口的年轻女子，笑道：“你直接去隔壁院子等我开门。”

    “天地相通，山壁相连，软如杏花，薄如纸页，吾指一剑，急速开门，奉三山九侯先生律令！”

    妇人手中并无最重要的那张符纸，只是口诵咒语，伸出手指向前一点，然后便闲庭信步，穿墙而过，身后带起一阵轻微涟漪。

    妇人走到一座家徒四壁的破败屋子，感慨道：“有些人命好，随便怎么折腾都是享福。有些人命不好，生来就是吃苦的。投错了胎，你能跟谁说理去？就算找到了正主，可你敢开口吗？小家伙，以后知道真相，在找我报仇之前，你最少要跟云霞山、正阳山和书简湖这三方打交道，等你找到我，牛年马月了，这还是你先要活着走出大骊版图才行。”

    她转头看了眼墙壁，“三山九侯先生，又是什么身份？我们东宝瓶洲可没有这么一号人物，难道是失去香火和金身的上古神人？若是如此，为何这个小法术依旧管用？”

    她暂时琢磨不出答案，想着回到大骊京城再去查一查，或者找崔瀺问一问也不是不可以，反正近水楼台，不问白不问。她走去开门，拔出门闩后没能拉开，才记起门外肯定上锁了，只得稍稍用力，强行扯断了那把铜锁，拉开门后，看到院门大开，她看着捧剑侍女和剑师徐浑然，问道：“你们就这么破门而入？还讲不讲道理了？回头自己找人修好，别忘记。”

    她走向院门，补上一句，“屋门的锁也换上一模一样的。”

    老剑师和捧剑女子显然对此习以为常。

    站在泥瓶巷中的魁梧男子皱了皱眉头。

    妇人走出院子后，突然停下脚步，“杨花，你按照我家睦儿七岁时的步子大小，往右手边走上六十三步。”

    捧剑女子领命前行，六十三步后停下身形。

    她身后的妇人侧过身，面对高墙，“应该就是这里了。”

    妇人看着并无半点奇怪的泥土墙壁，恨恨道：“宋煜章该死。”

    她很快恢复雍容恬淡的平常神色，笑问道：“这桩秘事，当年你是听我说过的，你觉得症结在何处，我能为睦儿做点什么？”

    年轻女子摇头道：“奴婢不知，也不敢妄自揣测。”

    妇人叹了口气，有些伤感，“我家睦儿的心结有两个，第一个，当然是那场大雨中，被一个贫贱泥腿子从巷外一路追杀到这里，掐住脖子，按在墙壁上动弹不得，以他的性子，肯定气愤难平。那会儿睦儿年纪尚小，除了丢尽了颜面，睦儿肯定也被杀气腾腾的同龄人吓得不轻。”

    妇人眼神骤然凌厉起来，伸出手掌，手心轻轻贴靠在粗糙不平的泥墙上，“第二个心结呢，就很有意思了。以至于有意思到了事后让我家睦儿，可能是人生第一次知道愧疚的滋味。所以他跟老龙城的苻南华见面后，那笔交易的添头，始终下不了决心，将要杀之人，从刘羡阳换成那个少年。”

    年轻女子终于有些好奇，不过侍奉这位夫人，无异于伴君如伴虎，自然不会傻到开口询问。

    妇人收起手掌，在捧剑女子手臂的袖子上擦了擦，开始转身走向巷口，一下子流露出些许娇憨神态，虽说已为人妇已为人母，竟是别有一番风韵，她气呼呼道：“睦儿不过是说你陈平安生于五月初五，克死了爹娘后，因为居住在祖宅，就连累爹娘无法投胎转世，所以最好别住在家里，要赶紧搬出去。”

    妇人越说越气恼，“说几句玩笑话，算得了什么？你陈平安信以为真，因为自己愚蠢而坏了不可去龙窑烧瓷的破烂誓言，怎么就能够怪到我家睦儿头上呢？更何况你一个小贱种的誓言，值得了几个钱？我家睦儿何等金贵，白璧微瑕，这是俗世俗人的说法。修行之人，若是相信这个，简直就是自寻死路。哪怕是能够与国同寿的上五境练气士，谁不在苦苦追求真正的不朽金身、无垢之躯？你一个市井少年，怎么赔？你赔得起吗？！”

    妇人咬牙切齿道：“小贱种，真是造孽！”

    一缕金色剑穗轻轻躺在胸脯上的捧剑女子，脸色平静。

    剑师徐浑然对此更是置若罔闻，毫不上心。

    唯有那名走在最后边的魁梧男子，再一次皱眉。

    妇人在即将走出泥瓶巷的时候，猛然转身。

    几乎同时，年轻女子和老剑师就分别向左右两侧挪步，为妇人让出视野。

    妇人此时已经满脸笑容，既妩媚，又纯真，有种矛盾的诱人，她柔声问道：“怎么，王毅甫，你觉得不对？”

    男人沉声道：“虽然不知更多的内幕，但是我确实觉得这样不对。”

    妇人没有丝毫意外，反而大笑道：“不愧是卢氏王朝头号猛将王毅甫！”

    习惯性眯眼看人看物的老剑师，几乎已经看不到眼睛，一身剑气充斥于狭窄小巷。

    不断有泥墙碎屑摔落地面。

    捧剑女子悄然后退一步，像是要给剑道宗师徐浑然让出更多的战场空间。

    她望着不远处的魁梧男人，嘴角勾起一抹讥讽笑意。

    一条断了脊梁的丧家之犬，也敢乱吠？

    这个名为王毅甫的男人，曾是卢氏王朝大将之一，出身头等将种门庭，祖辈皆是沙场大将，王毅甫归降之前，身份相当于大骊王朝的上柱国。大骊军神宋长镜很久之前，就点名要跟王毅甫痛痛快快打一场，此人领军打仗本事，算不得出类拔萃，但是个人武力极高。虽然是练气士，却拥有第八境武人的雄厚体魄，精通刀法，能够驾驭那尊著名玉石的强大阴神随同作战，可谓卢氏王朝屈指可数的真正高手。

    妇人伸出羊脂美玉一般的小巧手掌，晃了晃，“徐浑然，不用紧张，王将军是讲道理的人，就是为人过于正直了一些，如今身处一个阵营，别一言不合就要打打杀杀的。我很不喜欢。”

    徐浑然默默收起了一只袖管内浩浩荡荡的剑气。

    只是妇人在下一刻又说道：“我只会将王毅甫舍了性命和尊严也要护住的人，不送往之前说好的地方，而是送入皇宫，或是教坊司？”

    与她对视的王毅甫双拳紧握，青筋暴起，眼珠子泛出血丝。

    妇人云淡风轻道：“之前只说保住性命即可，所以你王毅甫可别把我的菩萨心肠，当做天经地义的事情。”

    王毅甫突然笑道：“娘娘说得对，是属下错了。”

    妇人笑道：“知错就好，那你等下出了这条泥瓶巷，就不用跟着我们了，去把上上任督造官大人的脑袋，摘下来，然后随便找个木盒子装好，以后我可能用得着。”

    王毅甫错愕道：“宋煜章是皇帝点名要求来这里的官员，娘娘你之前也说过，此人在礼部和钦天监都有靠山，为何要杀他？”

    妇人笑着反问道：“杀人还需要理由？那我当这个娘娘做什么？”

    王毅甫叹了口气，抱拳低头道：“属下领命。”

    四人先后走出泥瓶巷后，王毅甫与其余三人分道扬镳。

    等到那个归降大骊效忠娘娘的魁梧男人，身影彻底不见，徐浑然忍不住出声讥讽道：“好一个铁骨铮铮王毅甫，哈哈，如今连骨头和骨气一并没了。”

    妇人并未往人多处的大街走去，而是拣选了一条僻静巷弄，自嘲道：“真以为我做了某件事情，分不清好坏？”

    老剑师一时间不知如何答复，干脆就闭嘴不言。

    妇人抬头望着蔚蓝天空，没来由感慨道：“只有身临其境，才发现齐静春这个读书人，真的很厉害啊。”

    “是我们大骊对不住他。”

    “如此千古奇男子，只恨不能为我大骊所用，难怪陛下这些日子心情郁郁，经常叹息。”

    “只可惜齐静春再厉害，终究还是死了。”

    妇人一路唏嘘，竟然全是肺腑之言。

    当妇人沉默许久，不再说话。徐浑然记起一事，先是挥袖，剑气遍布四周，然后低声问道：“娘娘，杀一个骤然富贵的陋巷少年而已，我们是不是有些大题小做了？”

    妇人好像根本懒得回答这种问题，随口道：“杨花，你来说。”

    捧剑女子冷声道：“狮子搏兔，一击致命。”

    老剑师哑然。

    妇人扯了扯嘴角，“我家叔叔虽然是个武人，但是有一句话说得极妙，对付任何敌人，千万千万别送人头给他。”

    不同于下榻桃叶巷的礼部同僚，宋煜章独自住在骑龙巷，是一栋主人刚刚搬走的宅院。

    宋煜章开着屋门，坐在桌旁，有一只酒壶，旁边是一碟盐水花生米，和一大碗白酒，这位昔年的督造官大人，在小镇这边扎根整整十五年，吃什么喝什么，入嘴都是再熟悉不过的滋味。

    当他看到院中凭空出现一位魁梧男子，刚刚端起酒碗的宋大人笑了笑，“总算来了。”

    他高高抬起白碗，问道：“能不能等我喝完这碗酒。”

    那位不速之客稍作犹豫，点点头。

    宋煜章似乎是怕客人等急了，一口就喝光了小半碗烧酒，脸色红润，问道：“能不能帮我捎一句话给那个叫宋集薪的少年，嗯，以后他应该会被称为宋睦了。”

    这个中年男人眼神中带着一丝祈求，“能不能告诉他，那个叫宋煜章的家伙，这么多年下来，一直很想跟他要一副春联？”

    魁梧男人这一次果断摇头道：“不能！”

    宋煜章深呼吸一口气，缓缓闭上眼睛后，满脸释然，轻声道：“年少时喜读游记，看到东宝瓶洲最南端的老龙城，常年有大潮拍岸，天下壮观。那就当这一碗大骊酒，是那南海大潮之水。”

    王毅甫大步上前，一手拧断这名大骊礼部官员的脖子。

    杀人之后，王毅甫心中毫无快意，轻轻让其趴在桌上如酩酊大醉状。

    身为亡国之人，败军之将，王毅甫给自己倒了一碗酒，默默喝着，最后跟桌那边的那个死人说了句话：“原来读书人，也有大好头颅。”
------------

next：第九十章 大雨滂沱

    哪怕陈平安仍然怀疑阿良，但不可否认，阿良是一个很有意思的人。

    他有一头从来不骑乘的毛驴，他跟小屁孩李槐斗嘴不亦乐乎，他一门心想着拐骗林守一喝酒，说天底下的好东西，不过醇酒美妇二物，他会在陈平安走桩的时候绕着少年打转，说这套拳法一旦大成，肯定老霸道了，对着人就是一顿乱捶，只可惜行走江湖，讲究打人不打脸，所以伤和气败人品，最好要像他这样以德服人，以貌胜敌。

    他还会跟朱河吹嘘自己的剑术无双，说他一旦握剑，那可了不得，连他自己都感到害怕，就更别说对手了。朱河在旁笑呵呵点头称是，可少女朱鹿偏偏不信这个邪，非要阿良用那把竹刀演示演示，也不用他施展出排山倒海的剑法，能砍断一颗碗口大小的树木就算她输。阿良就说今日不宜施展剑术，他虽然早就达到了万物皆可做剑的地仙境界，可出剑一定要看心情啊，高手没有一点怪癖还是高手吗，所以只有那些大风大雪大雨之类的日子，才有兴致，比如那滂沱大雨当中，自己出剑之后，能够快到滴水不沾身。

    朱鹿朝地上我呸了一句就转身跑开，阿良也不恼，只是笑眯眯跟朱河说，小朱啊，你这闺女这脾气不太好哇，当然她要是以后真嫁不出去，不用担心，我阿良可以让你占个天大便宜，喊你一声岳父大人。

    朱河打那之后，就不再凑到阿良跟前嘘寒问暖套近乎了。只好自己一个人喝闷酒的阿良有些失落。

    不凑巧，过了几天，在他们临近铁符河的时候，下起了一场蒙蒙细雨，虽然不大，可好歹是下雨了。

    朱鹿立即拦住牵着毛驴埋头赶路的阿良，后者一脸茫然，问少女，姑娘你干啥咧，哦哦，你是说下雨就练剑给你看的事情啊，哈哈，我记得记得，小姑娘，你别用那种看骗子的眼神看我好，行不行？你啊就是太年轻，不晓得世外高人的规矩茫茫多啊，知不知道，雨太小了，哪怕我只是以一株野草做剑，也会觉得对不起那株草，哦不对，是对不起我的上乘剑术。所以等哪天雨下大了，我再出手，保管将那条铁符河都给拦腰斩断了，到时候你哪怕哭着喊着要我收你为徒，我都未必点头。

    朱河二话不说把自己闺女拽走了。

    小雨朦胧，不耽误赶路，阿良伸手扶了扶斗笠，摇头叹了口气，牵着白色毛驴走在最前方的他，那一刻背影有些寂寞。

    更不凑巧的是，又过了两天，老天爷开眼似的，下了好大一场暴雨。

    结果阿良怒喝一句，看啥看，老子脸上有花啊？还不去躲雨？我家宝瓶淋坏了身子骨咋办？看我出剑什么时候不能看，你们有没有一点慈悲心怜悯心？！没有看到咱们宝瓶快冻死了吗？

    最后众人一起蹲在参天大树下躲雨的时候，所有人都死死盯着阿良。

    李槐皮笑肉不笑，模仿自己娘亲的语气，语重心长说道，阿良啊，也亏得今天只下雨没打雷，要不然第一个劈在剑仙你身上。

    朱鹿只是冷笑连连。

    就连性情冷淡的林守一都忍不住翻了个白眼。

    朱河如今已经彻底不愿意搭理这个狗屁风雪庙大佬了，自顾自嚼着干粮，一路行来，多次隐蔽微妙的试探之后，朱河觉得这个浑身古怪的阿良，哪怕的确是兵家祖庭的修士，但绝对不会是什么用剑的地仙高手，如果是真的，别说让他阿良喊自己老丈人，就是自己喊他老丈人都没问题。

    一路行来，李宝瓶比起刚刚离开铁匠铺子那会儿，话少了许多，只是默默跟随在小师叔陈平安身旁，小背篓也不愿意让朱河朱鹿帮忙背着。

    陈平安则在练习剑炉这个拳桩，其他人早已见怪不怪。

    阿良被李槐他们看得有些不自在，转过身屁股对着他们，摘下腰间的银色酒葫芦，一口一口喝着酒。

    大雨渐歇，阿良突然站起身，说要出去找根趁手的树枝，非要让他们见识见识上乘剑术，不过在众人面面相觑的时候，阿良又说如果找不着，那就没办法了，剑仙找趁手之物，就跟凡夫俗子找媳妇一样，是一件不容易的事情。

    所有人看着斗笠有些歪斜的阿良，根本没人愿意开口说话。

    阿良一个人往山坡上行去，下雨地滑，差点一个踉跄摔倒，赶紧装模作样地摆了几个拳把式，好似在为出剑热手。

    结果阿良的身影刚刚消失在视野，这场雨就猛然间下大了，毫无征兆，让人措手不及。

    陈平安睁开眼，看到树底下不远处的毛驴，想了想，起身说道：“我去找阿良。”

    朱河也跟着起身，“我陪你一起吧，这天气很容易出事情。”

    陈平安摇头道：“不用，我在山里烧炭采药的时候，遇到过很多次这种天气，不用担心，再说这里也需要朱伯伯你照看着，我才能放心。”

    朱河思考片刻，点点头，“陈平安，那你自己小心。”

    陈平安揉了揉李宝瓶的脑袋，柔声道：“我去去就回。”

    不但要亲自盯着小镇东边的衙署建造，还有为了商定文昌阁武圣庙的选址一事，父母官吴鸢一天到晚忙得脚不着地，四姓十族除去已经举族迁出小镇的六个，还剩下八个，礼部右侍郎董湖靠着牌坊楼拓碑一事，过江龙压过了地头蛇吴鸢的风头，如今那些个土生土长的老油子，全在福禄街和桃叶巷看他吴鸢的笑话，可他还是得一家一户登门拜访过去，忙得吴鸢最后嘴唇干裂，嗓子眼都快冒烟了，一回到督造官衙署，瘫软在椅子上，扯了扯领口，直愣愣盯着房梁雕花，脸色阴沉不定。

    身边站着那位豪阀出身的文秘书郎，今天是他陪同吴鸢拜访了各大家主，吃闭门羹不至于，但是软钉子碰了一大堆，相互推诿，这个说老瓷山能不能搭建文昌阁，得去问刘家老爷，那个说神仙坟是魏家占地最多，只有魏家老爷子点头才能坐下来谈，然后刘家魏家又说这种涉及祖宗基业的天大事情，一定要大伙儿聚起来慎重商议，否则是要被街坊邻居们戳脊梁骨的。

    这位秘书郎同样憋了一肚子火气，不过自幼耳濡目染，对于官场规矩再熟悉不过，知道为官不易，主政一方的父母官更是大不易，所以并未气急败坏，他对周围几位闻讯赶来的同僚轻轻摇头，示意他们暂时不要火上浇油，留给吴大人一个清净清净。

    吴鸢突然笑着说道：“放心，我没事，这会儿就是有点馋咱们京城的酒水了。”

    那位世家子这才落座，遗憾道：“可惜李家已经搬去京城，要不然可以让他们家主李虹帮着牵线搭桥，有些事情能够私下说，就会好办许多。我们家跟京城李家关系还不错，那边发话，这里的小镇李氏肯定要卖这个面子。”

    吴鸢瞪眼训斥道：“你傻啊，你家族积攒下来的人脉，不等于你的人脉，你每用上一次，就会让自己在家族地位下降一大截。这种事情，不是之前你跟人求匾额榜书那么简单的，所以你别瞎搀和。”

    世家子笑道：“我这不是担心吴大人钻牛角尖嘛。”

    吴鸢嗤笑道：“我如果是钻牛角尖的人，早把那位上柱国老丈人的腿打断了，然后带着他的宝贝闺女一起私奔。”

    满堂寂静。

    世家子忍住笑，低声道：“这种大话，吴大人在咱们这儿吹吹牛就可以了。”

    吴鸢舒舒服服瘫靠在椅背上，一点也没有被揭穿真相的窘态，反而笑呵呵道：“那当然，老丈人要真大驾光临，我这会儿早跑去低头哈腰端茶送水了，还得问上柱国大人你老累不累啊，要不然揉揉肩膀啊。”

    衙署大堂内笑声四起。

    就连门口那两位腰悬绣金刀的武秘书郎，也相视一笑。

    吴鸢坐直身体的那一刻，大堂内所有人都下意识屏气凝神，吴鸢不急不缓道：“李氏已经迁出去，卢家铁了心要当缩头乌龟，万事不管。赵氏推说老祖宗身体有恙，一切都要她身体好转才能定夺，小镇宋氏水最深，这福禄街四大姓，加在一起拥有十座大型龙窑，李氏名下的两座，已经转让给桃叶巷魏、刘两家。”

    “你们今天就将衙署所有零散文档归拢在一起，汇集成一份四姓十族的关系脉络图，我倒要看看这座小池塘，是怎么个鱼龙混杂。退一步说，哪怕拿前几个大家族没辙，那我们就去找次一等的家族，除了十族垫底的几个，还有那个很有钱的马家，始终恪守祖训不肯搬去福禄街桃叶巷，他们就拥有两座窑口，既然我现在还兼着窑务督造官，那么这些龙窑的规模大小，还不是我说了算？将这些家族拉拢扶植起来，与此同时，我会砸钱下去，衙署的积蓄全部掏空，我也不心疼。我就不信老瓷山你们守得住，可神仙坟那么大一块地方，一旦分赃不均，你们能够护得住多久？”

    “水浅王八多，庙小妖风大。等到池塘见底，小庙倒塌，我看到时候这帮老狐狸怎么跟我认错赔礼。”

    县令大人说到最后，本该意气奋发才对，不曾想哀叹一声，又瘫软回去，“这日子没法过了。何时是个头啊？！先生，说好的醉卧美人膝呢？衙署上下，不是老妪便是稚童，就没一个妙龄女子啊。说好的这里人杰地灵女子秀美呢？”

    就在这个时候，眉心有痣的清秀少年被两名扈从伸手拦在门外，少年微笑道：“吴大人，不然我写信帮你问问京城的袁柱国？帮你要两个眉眼可爱的小丫鬟过来？”

    吴鸢立即站起身，脸色尴尬，又不好说破自家先生的国师身份，也没那脸皮和胆识，为了掩人耳目就对先生大加呵斥。

    吴鸢心底满是疑惑，不知先生为何要登门衙署，而且看样子一点不介意泄露身份。

    崔瀺懒得跟那些文武秘书郎计较，转身撂下一句，“随我来。”

    吴鸢对屋内所有人伸手虚压了两次，示意他们不要声张，独自快步走出门槛，当两名沙场出身的武秘书郎想要贴身跟随，吴鸢仍是摆手拒绝。

    走在僻静无人的石子小径上，崔瀺问道：“卢氏刑徒都已经进山了？”

    吴鸢摇头道：“还剩下六百刑徒，尚未到达最北边君神山的山口，这拨人身份也最为尊贵，多是卢氏王朝的功勋豪阀之后，年纪也不大，十四五岁到二十岁之间。”

    吴鸢疑惑道：“这不是先生你之前就安排好的吗？”

    崔瀺没好气道：“天有不测风云，你家先生我现在算是龙游浅滩了，所以得再跟你确定一下。你现在什么事情都别管，快马加鞭赶往神君山的入山口子，找到一个叫夏余禄的刑徒少年，安排他去京城。”

    吴鸢小心问道：“这次是宋长镜的嫡系心腹护送他们赶来龙泉县，我就这么上门要人，那帮六亲不认的兵痞，肯乖乖放人？”

    崔瀺挥挥手，不耐烦道：“我那边自有后手，你只要露面就行。”

    吴鸢担忧道：“先生，你这边？”

    崔瀺冷哼道：“死不了！”

    吴鸢不再犹豫，立即喊上那两名武秘书郎，一同骑马出门。

    先生动动嘴，学生跑断腿。

    崔瀺等到吴鸢离去之后，独自行走在衙署小路，脸色阴沉，“一着不慎满盘皆……还没完全输，满盘皆溃倒是事实，不过没事，只要还有一丝胜算就行，熬着，就当修心养性了。大不了换了棋盘再来。”

    “我不就是先熬死了先生，又熬死了你齐静春？”

    “咦？怎么说着说着，感觉自己像只乌龟了？”

    崔瀺最后叹了口气，“她的运气真是一向很好啊，早不来晚不来，偏偏在这个时候一头撞进来，我只能尽力从这盘残局里搂回几颗棋子是几颗了，省得被她全盘收走，真是气死我了！”

    之后有衙署杂役远远走过，就听到一个相貌清秀的少年在那里大声念叨，“我不生气，犯不着……我不生气，犯不着……他娘的，犯不着个屁！气死老子了！”

    铁匠铺子，三张崭新竹椅摆在屋檐下，翠绿欲滴，颜色可亲。

    青衣少女已经起身愤懑离去，只留下一个脸色如常的阮师，和一个笑容不变的尤物妇人。

    远处溪畔，站着捧剑女子，大袖老人和魁梧男人。

    坐在小竹椅的妇人，从马尾辫少女的背影收回视线，她方才使用了一个小法子，故意激怒少女，让其离场，妇人这才开门见山问道：“阮师与齐先生有所约定？所以那陈平安身边，才有李家的武人跟随？”

    阮邛直截了当道：“没有。”

    妇人又问：“那就是阮师因为那三座山的缘故，答应庇护陈平安？”

    阮邛点头，“对，我答应过他，保证他们离开大骊之前，都没有大的意外。”

    妇人抬头看着即将大雨的阴沉天色，说道：“阮师，我让人再买下神秀山周边的四座山头，赠送给你，就当是大骊的见面礼，如何？”

    阮邛冷笑道：“你还需要花钱买？那一袋袋金精铜钱，不过是大骊皇帝左手出右手进的事情，何必多此一举？”

    妇人摇头笑道：“规矩就是规矩，并非我是一个喜欢守规矩的人，而是眼前阮师的规矩，或是京城皇帝陛下的规矩，都要比我的身份大，所以不得不遵守。我虽然算不得什么好人，但从来量力而行。”

    阮邛对此不置可否，问道：“你为何要执意杀那个少年？而且是不惜花费这么大的代价，一定要这么急着杀他？以至于等到他离开大骊边境再下手，也不行？”

    妇人语气不重，眼神却尤为坚定：“他必须死。他死了，就算真有那秃驴所谓的佛家因果，当初杀他爹那件事，以及靠他帮助我家睦儿争取更多机缘一事，全部会止步于我……”

    阮邛淡然道：“是因为你有某些见不得光的旁门神通，能够斩断因果吧？”

    妇人微笑，不否认，不承认。

    阮邛摇头道：“可这不是你这么急匆匆杀人的理由。”

    “我家睦儿马上就要进入大骊京城，到时候会有一场大机缘降临，为了避免横生枝节，我必须尽早斩草除根。”

    妇人见对面男人一脸不为所动的冷漠，只好泄露天机，选择与这位兵家圣人坦诚相见，详细解释道：“睦儿的心结，若是放在一般修士身上，倒也无妨，大道漫长，哪怕他在破开中五境之前，无法自己将其摒除，大骊一样有的是手段，以外力强行祛除，大不了就是留下一个大小不可预测的天魔心窝，跻身上五境的时候，会变得极为凶险。可是如今京城那份机缘不等人，就容不得丝毫马虎了。加上崔瀺那个废物，号称算无遗策的崔大国师，竟然输了，显然到最后，也不曾成功坏了那少年的澄澈心境，没办法，我只好退而求其次，用陈平安的那颗头颅，强行拧转睦儿的心境。”

    妇人说到这里的时候，无奈道：“不是没想过蒙骗睦儿，说那陈平安在崔瀺的大考当中，成了俗不可耐的市井小民，甚至我可以将所有细节编排得天衣无缝，一一呈现给他。但是我担不起这份风险，一旦将来睦儿知晓真相，他如今天资太好，一旦获得那份机缘，反而成了莫大隐患，极有可能一瞬间就会道心崩碎。”

    此时，天将大雨。

    雨幕如铁。

    阮邛不理会外边的大雨滂沱，问道：“什么心结，如此麻烦？”

    “那个姓姚的老不死，阴了我一把，告诉了那少年真相，他的爹娘根本不可能因为他是五月初五出生，就会被阳气所伤，所以无法投胎做人。于是那个违背他娘誓言的少年傻眼了，发疯一般从龙窑狂奔回小镇，之后那个悲愤欲绝想杀人的少年，阮师，你知道他做了什么吗？他既没有去找睦儿，也没有回家，竟然在泥瓶巷外一直等着，等到一个睦儿单独出门游荡的机会，才堵住他，追上他，最后在泥瓶巷将我家睦儿按在墙壁上，差点掐死他，当然，他最后没有杀人，而且就算他真想杀，死的也只会是他，可恨那些藏在暗处的死士谍子，死守着陛下的规矩，只要睦儿不死，就绝对不可以插手，废物，全是罪该万死的废物。”

    妇人尽量用云淡风轻的语气说出这个秘密后，破天荒有些疲惫和无奈，“世间竟有这种心思古怪的贱种？他的这个举动，反而成了我家睦儿最大的心结，近乎死结。他这么多年甚至很多次从梦中惊醒，因为睦儿一直想不明白，‘你陈平安，为什么不杀了我，为什么还要挑一个稚圭不在场的时候？换成是我宋集薪，我会把你陈平安大卸八块还不解恨，当着你至亲至近的人面，才最好。’归根到底，也算是我作茧自缚了。”

    大雨如黄豆一般砸在大地，如当年两个同龄孩子的泪水。

    一个瘫软坐在地上，双手捂住脖子，吓得大哭。

    一个脚穿草鞋的贫苦孩子，走向泥瓶巷巷口，用手臂挡住脸颊。

    就像一面镜子，越是光明无瑕，越可以映照出照镜之人的瑕疵。

    长久的沉默之后，妇人收回思绪，犹豫了一下，问道：“那座廊桥的手笔，阮师应该有所猜测吧？”

    阮邛满脸厌恶，“早知如此，我不会来这里。”

    妇人挑了一下眉头，沉声道：“所以最后睦儿离开小镇之前，必须要去那边上香，因为他能够有今天的一切，都是因为大骊皇室死了一个又一个的金枝玉叶和皇亲国戚！那块廊桥匾额上的风生水起这四个字，有多少笔画，就死了多少人，是这些人用命换来他的成就！”

    阮师脸色阴沉，似乎没有想要说话的念头了。

    妇人缓缓站起身，意气风发，低头凝视着阮邛，嗓音低沉，蛊惑人心，缓缓道：“阮师，要是觉得四座山头，仍然配不上你给那少年的一句承诺，无妨，阮师只管开价，只要你肯开口，都好商量。比如说大骊这边，我回去京城后，可以说服皇帝陛下，为你女儿将来证道之际，大开方便之门。虽然不晓得是什么，但我可以替陛下答应阮师，大骊朝廷届时一定倾力相助！我本人之外，国师崔瀺，甚至是宋长镜，都可以为你家阮秀的证道契机，助一臂之力！”

    阮邛答非所问，“我只要答应下来，就会与你们大骊宋氏挂钩，这也是你的谋划之一吧？”

    妇人似乎根本不屑说谎，或者说也不敢把一位圣人当傻瓜，“当然，要不然咱们那位勤俭持家的皇帝陛下，岂会由得我胡来？他虽不反感妇人干政，甚至直截了当告诉我，管不住身边一个女子，如何管得了一座江山，我真要祸国殃民了，也是他无能。”

    “可有些事情，他一开始就说得很清楚，不许我擅作主张，为此我是付出过很大代价的。”

    “我这个人，有个最大的优点，就是记打。”

    阮邛终于不再掩饰自己的鄙夷，斜眼妇人，语气淡然道：“以后你不要进入龙泉县方圆千里以内，只要被发现，就不要怪我出手打女人。”

    妇人盯着阮邛的脸庞，叹息一声，“罢了罢了。大不了就等到大骊边境再说。今日叨扰，阮师勿怪，就算阮师看不惯我这种妇人，也别因此对我们陛下印象不佳。”

    阮邛在她走下台阶的时候，说道：“那条竹椅是陈平安亲手做的。”

    妇人愣了愣，故意曲解阮邛真正想说的言下之意，妩媚笑道：“怎么，阮师是想说那个叫陈平安的少年，间接摸过了我的屁股？”

    妇人大笑离去，径直走入雨幕之中，任由大雨淋湿全身。

    体态婀娜，曲线毕露。

    阮邛并不看她，面无表情。

    又是一场大雨。

    已是少年的陈平安走到山顶，看到背面山坡，站着一个缓缓将竹刀归鞘的斗笠男人，转头灿烂笑道：“来这里之前，遇到过一位比你有趣太多的少侠，经常听他念叨一句诗，真是好，你不妨也听听看，野夫怒见不平事，磨损胸中万古刀。”

    自称是剑客的阿良，缓缓走向少年，伸手指了指少年头顶，“不过我可不是什么侠客，只是单纯觉得这句诗，很适合这种天气杀人后，拿出来念一念。我来这里找你的真正理由，一是顺路收集养剑葫，二是你头上的那根簪子。后者比前者重要一百倍吧。”

    竹刀已经归鞘的男人身后山坡上，躺着两具神态安详的尸体。

    皆是大骊第一等修为的武夫和修士。

    陈平安问道：“你到底是谁？”

    男人缓缓而行，手心抵住刀柄，在陈平安身前停下脚步，抬了抬斗笠，微笑道：“我叫阿良，善良的良。”
------------

next：第九十一章 玉簪

    大雨砸在两人的竹篾斗笠上，啪啪作响。

    陈平安沉声道：“这根簪子很普通，只是普通的玉材。”

    阿良盯着一本正经的少年，好像听到一个天底下最大的笑话，龇牙咧嘴，好不容易才忍住不笑出声，“你说了不算。”

    陈平安额头渗出汗水，但是很快就被溅在脸上的雨水冲刷掉，看着那个男人，问道：“那你到底想要什么？”

    阿良笑问道：“你是不是觉得自己要死了？”

    陈平安在这一刻，突然感到很绝望。

    因为阮师傅来过，又走了。

    而眼前这个男人还站在自己眼前。

    阿良还是那个笑眯眯的阿良，斜挎着那把绿色竹刀。

    这个男人笑望着少年，不高的个子，单薄的衣衫，结实的草鞋，当然还有那根画龙点睛的碧玉簪子。

    如果他没有记错，簪子上篆刻有漂漂亮亮的八个小字。

    陈平安嘴唇铁青，颤声问道：“你能不能放过他们？”

    阿良不说话。

    陈平安在临行前一夜点灯熬夜，就尽可能想象所有困境，他不是没有想过，此次前往山崖书院求学，路上会遇到大大小小的坎，因为光是他的仇家，明面上就有云霞山、老龙城和正阳山三方，无一例外都是山上的神仙中人，却都跟他有生死大仇，所以陈平安很担心因为自己的缘故，连累到红棉袄小姑娘的求学之路。

    那天跟李宝瓶说起自己小时候进山的坎坷难熬，并非少年想要诉苦，想要摆小师叔的威风架子，而是陈平安想告诉小姑娘一件事情，就是他们去那座已经搬去大隋的书院，路程肯定比他当年进山采药更远。如果有一天他不在了，没办法陪在她身边，而李宝瓶又希望去那里读书，只是因为她对自己没信心，那么陈平安希望她能够像当年那次进山，多走几步，走着走着，说不定就走到了。

    只不过当时这些话跑到嘴边，陈平安突然觉得两个人才起步远游，说这种话实在太晦气，不吉利，所以只说了一半，就把另一半咽回肚子，改成希望她能够成为第一个小夫子，女先生。既是讨吉利，也确实陈平安对小姑娘的期望。

    阿良笑道：“退一万步说，那根簪子是寻常的文人饰物，也不属于你。退一百步说，我不相信齐静春郑重其事保存这么多年的簪子，会没有暗藏玄机，例如它其实是一座不为人知的小洞天，或是一块拥有成为福地资质的风水宝地。如果只退一步说，那就更厉害了，它有可能是一支文脉薪火相传的信物，就像道教三大主脉的掌教信物，一块桃符、一件羽衣和一顶道冠。如果属实，簪子真是齐静春的先生信物，陈平安，你觉得戴在你头顶，合适吗？”

    陈平安答非所问道：“阿良，你能不能放过李宝瓶李槐他们？”

    阿良笑问道：“你怎么确定我答应了你，事后不会反悔？”

    陈平安的脚尖微动。

    阿良双手环胸，笑道：“少侠别冲动啊，咱们这不是正在讲道理嘛，等到道理讲不通了，再动手不迟。”

    陈平安默不作声，脸色苍白。

    阿良上下打量了一番少年，“还真有点像。”

    阿良收敛玩笑意味，伸出手，“交出簪子，我不杀他们。”

    陈平安手指颤抖。

    阿良缓缓说道：“这是齐静春的先生遗物，这也算是齐静春的遗物。”

    陈平安抬起手臂，伸向头顶。

    阿良笑道：“你亲手折断簪子，我不杀你。我从不骗人。”

    陈平安突然停下手，深呼吸一口气，一脚后撤，如搏杀起手式。

    阿良问道：“你是觉得反正自己死了，我也会放过李宝瓶他们，所以你哪怕死，也要试试看，能否凭本事护住这根簪子？”

    陈平安一言不发，两步重重踏地，就冲到了阿良身前，一拳挥出。

    下一刻，陈平安突然发现眼前已经没有了阿良的身影。

    陈平安身体僵硬地转过身，果不其然，那斗笠男人就站在那里，只是手里多了一根簪子。

    阿良叹了口气，似乎对那根簪子根本没有太大兴趣，伸出手递给少年，“拿回去。”

    陈平安小心翼翼走上前数步，从他接过那根碧玉簪子，刹那间少年只觉得头顶一沉，原来是斗笠男人一只手轻轻按在了他头上，两人肩并肩站立，只不过两人朝向相反。一直以吊儿郎当面孔示人的男人叹了口气，“陈平安，以后别做傻事了，天底下哪有死物，比人的性命还重要？一定要活下去，哪怕没办法好好活着，也要活着，天底下没有比这更大的道理了。”

    斗笠男人拍了拍陈平安的脑袋，抬头望着黑沉沉的天幕，他笑道：“你要知道，不管这根簪子到底有多值钱，意义有多大，齐静春既然愿意交给你，就一定是相信你，所以只要是需要你做出生死抉择的时候，一定要选生，不可选死。壮壮烈烈而死，慷慨激昂赴死，风流写意去死，可死了就是死了啊。”

    斗笠男人收回手，“齐静春对这个世界很失望，那是他的事情，你陈平安就是你，别学他，你还没有真正见识过这个世界的好和不好。人生不满百，常怀千岁忧，那是他们读书人的事，我阿良不是读书人，你陈平安暂时也不是，所以……”

    男人最后也没有说出“所以”之后的原本内容，只是轻声道：“陈平安，相信我的眼光，你将来可以走很远的路，甚至能够比齐静春更远。”

    少年轻声问道，“为什么？”

    男人手心轻轻摩挲竹刀刀柄，笑道：“因为我是阿良啊。”

    两人最终一起沉默走下山顶。

    陈平安问道：“那边山坡的两个人？”

    阿良想了想，“死人？”

    陈平安欲言又止，想了想，还是不在这个问题上刨根问底，换了个话题问道：“你为什么不拿走簪子？”

    阿良嘴角抽搐，哀叹道：“簪子拿到手后，才知道比我设想最坏也只是退了一万步，更不像话，简直是退了几万步，它真的就只是一根破簪子，那我要它做什么？”

    少年说不出话来。

    阿良摇头道：“真正的读书人都穷，你以后就会明白了。我其实早就该想到的，按照道德林那老头子的脾气，和齐静春的性子，传下来这么根普通簪子才是正常。”

    阿良突然笑着转头，“知道吗，你拿走了我一样以为是囊中之物的东西，你知道我为此走了多少的冤枉路吗？”

    斗笠一头雨水，少年一头雾水。

    阿良气哼哼道：“我甚至已经在某个地方，刻下了一个字，但是到头来，等我屁颠屁颠跑来，结果是这么个惨淡光景，所以你要感谢我的不杀之恩啊。”

    阿良自顾自说道：“你要是以后没本事在那里刻下两三个字，看我不削你。”

    陈平安无奈道：“阿良，你能不能说一些我听得懂的话？”

    “可以啊。”

    阿良哈哈笑道：“我叫阿良，善良的良。”

    陈平安帮他说完下一句话，“我是一名剑客。”

    这一刻，阿良嘴角翘起，一巴掌拍在少年肩头，“那就这么说定了！”

    陈平安更加纳闷，“嗯？”

    阿良已经撇开话题，“送君千里终须一别，我会送你们到大骊边境后离开，相信到了那个时候，你们这帮孩子也能够清清爽爽远游求学了，暂时不会再有乌烟瘴气的事情，所以在那之后，你就要自求多福了，能不能带着他们走到大隋山崖书院，之后能不能活着回到大骊龙泉县，全看你自己本事。”

    陈平安突然说道：“谢谢。”

    从初次相逢，直到现在，少年才开始彻底信任这个自称阿良的男人。

    阿良摇头道：“没事，我只是在弥补自己的亏欠，跟你关系不大。”

    很多年前，曾经有一位姓齐的少年读书郎，读书读烦了之后，说想要跟他一起闯荡江湖，那次名叫阿良的剑客，没有点头答应。

    男人觉得如果当时自己稍微多点耐心，那个少年就不会走到今天这一步。

    阿良最后说道：“陈平安，你知道吗？”

    少年说道：“什么？”

    阿良语重心长道：“以后对我这种绝世高手，要发自肺腑的尊重啊。”

    少年好奇问道：“你打得过朱河？”

    阿良有些头疼。

    觉得这家伙比当年的齐静春更惹人厌。
------------

next：第九十二章 小竹箱

    水深无声，雨大皆短。

    这场暴雨在陈平安和阿良走回大树下没多久，就已经变成淅沥沥小雨，雨珠不断从树叶上滴落，红棉袄小姑娘在陈平安回到树下的时候，满脸隐忧，陈平安灿烂一笑，揉了揉她的小脑袋，轻声说没事了。小姑娘脸色呼啦一下蓦然灿烂起来，如一抹令人意外的雨后彩虹，干净得让人心颤。这一刻，陈平安突然有些愧疚，只是一时间不知如何开口，许多言语堵在心里头，便只好默默练习剑炉立桩。

    阿良看到这一幕后，会心一笑，但是李槐一句话很快打消了阿良的不错心情，阿良阿良，听陈平安说你是去山上拉屎了，因为这样可以不用擦屁股。阿良笑呵呵问道，真的是陈平安说的？李槐瞥了眼就站在不远处的陈平安，大概是生怕阿良跟陈平安当面对质，也学着阿良的语气呵呵一笑，说陈平安虽然没有说出来，但我觉得他肯定是这么想的，我当然觉得阿良你不是这样的人啊，我还专门给朱鹿姐姐解释过，拍胸脯保证你阿良不是这样的。阿良轻轻扯住李槐的耳朵，低头笑问道，哦？李槐痛心疾首道，阿良，都怪陈平安，太不是个东西了，要不要我替你骂他？阿良使劲拧转这个小王八蛋的耳朵，当我阿良好骗是吧？李槐鬼叫起来，只可惜没有人愿意理睬，李槐立即见风转舵，阿良阿良，我有个姐姐，叫李柳，名字是难听了一点，人可漂亮了，这个绝对不骗你，林守一和董水井两个色胚，就都偷偷喜欢我姐姐，董水井有事没事就去我们家蹭饭，每次见到我姐，恁大一个人了，还脸红，真是恶心。阿良，我觉得你比董水井强多了，人帅脾气好，骑得起驴子喝得起酒，要不要以后帮你和我姐，认识认识？

    阿良赶紧松开李槐耳朵，双手轻轻放在李槐肩膀上，往下一按，笑道咱们蹲下来慢慢聊。

    陈平安走到朱河朱鹿父女身前，问道：“朱河叔叔，能不能聊一下？”

    汉子咧嘴笑道：“等你这句话很久了。那我们随便走走，反正雨已经很小。”

    两人并肩走出那棵树荫大如峰峦的不知名大树，不等陈平安开口询问，朱河自己就自报家门和根脚了，“陈平安，小镇之前发生那么多奇怪事情，你既然能够在正阳山搬山猿手底下活下来，还与那位外乡少女成为结伴盟友，估计很多事情你都已经知晓，那么我也不藏掖什么了，毕竟小姐的安危是最重要的，我们父女二人皆是李家的家生子，就是世世代代作为杂役奴婢，在主人李家讨一口饭碗吃，虽然听着很可怜，其实没你想的那么惨，从一年到头也见不着几回的老祖宗，到家主，再到我们这位宝瓶小姐，没谁把我们父女当下人看待，尤其是小姐和我家闺女，其实她俩关系不比寻常人家的亲姐妹差了。”

    说到这里的时候，中年男人转头看了眼站在大树底下远望别处的女儿，正是少女身段抽条的时分，尚未真正长开，大概再过一年就会是真正的大姑娘了，他觉得自己女儿不会比大骊京城的任何一位千金小姐逊色，他对此一直很自豪，坚信女儿朱鹿以后一定会在大骊大放异彩。

    需知大骊素来尊重女子，不禁女子投身沙场奋勇杀敌，大骊先帝甚至专门下令礼部为女子武人、修士，设置了一整套武勋称号，开一洲之先河，曾经被观湖书院为首的士子文人，大肆抨击，掀起过一场大乱战，矛头直指北方蛮夷大骊王朝，若非身为山崖书院山主的齐静春力排众议，可能当时的年轻皇帝就要迫于朝野清议舆论，就要因此收回圣旨。

    朱河笑道：当年发现我有习武的根骨天赋之后，二话不说就花费重金栽培我朱河，所以我才有现在的身手，女儿朱鹿也是差不多，如果不是她自己不争气，在武道第二境功亏一篑，以后成就比我这个当爹的，只高不低，老祖宗在发现朱鹿是习武的一颗好苗子后，亲口对我说过，朱鹿有希望走到传说中的武人第七境，我朱河不过才堪堪第五境而已。”

    说到这里，朱河心情有些失落，武人升境，没有旗鼓相当的对敌厮杀，没有命悬一线的生死磨砺，只靠天资是注定走不长远的，而且一旦错失良机，无法一鼓作气往上攀登，就会越来越消磨意气，再而衰三而竭，彻底断了登顶之路。

    朱河压下心中阴霾，继续说道：“这次由我们护送小姐离开大骊，一来是我们离得最近，身手还算凑合，而且是李家的家生子，不敢说本事有多高，最少忠心。二来小姐第一次出远门，需要细心的人照顾饮食起居，朱鹿就是合适的人选。第三嘛，我家小姐是老祖宗最心疼的晚辈，其实原本这次真正护送小姐远游的人，不是别人，正是老祖宗自己亲自出马。只是阮师的风雪庙同门，那个阿良出现后，老祖宗就返回小镇了，因为如今小镇没了禁制，可以毫无顾忌地收纳天地灵气，等于是在一座洞天福地修行，老祖宗破境在即，机不可失时不再来，反正有阿良担任贴身扈从，应该不会出什么岔子。”

    朱河略作思量，解释道：“我们老祖宗眼光独到且心胸宽广，虽然打心眼疼爱宠溺小姐，可是在小姐远游求学一事上，老祖宗非但不把小姐强行挽留在身边，庇护在羽翼下，反而明言小丫头不但要去山崖书院，而且后半段路程，就由她自己去走，李家子孙，本就该有这样的气魄。”

    朱河突然笑出声，“只不过说到这里，老祖宗又是一脸愁肠百转的模样了，碎碎念叨着可是咱们家小宝瓶，才不到十岁啊，气魄啥的，是不是可以晚一点再说啊。最后老祖宗下定决心不再一路悄悄跟随的时候，一步三回头，跟老小孩似的，破天荒第一回。所以朱鹿私下跟我说，老祖宗对小姐，是真好。”

    朱河心怀感激道：“小姐对我家朱鹿，也好，小姐从小就喜欢跟朱鹿聊天，看朱鹿练武，朱鹿能够走到今天，事实上小姐功莫大焉。”

    陈平安松了口气，“朱河叔叔，有你们在，我就放心了。”

    小镇那边，除了齐先生，陈平安信不过任何人。

    哪怕是阮师傅，就像陈平安对李宝瓶所说，他相信的也只是一位此方圣人的承诺，是齐先生曾经遵守的某些规矩，而不是阮师傅本人。

    这是一种不可言说的直觉，可以说是天生的，但更多还是熬出来的，就像草鞋少年给那位宁姑娘煎的药。

    之前对阿良，对朱河，皆是如此，更不例外。

    陈平安不是衣食无忧，没吃过苦，所以傻乎乎对谁都好。生活的艰辛，人心的丑陋，贫穷的磨难，孤苦无依的少年，早就铭刻在自己骨头上。

    朱河拍了拍少年的纤细肩膀，只是一拍之下，骨头之结实坚韧，稍稍超出这位五境武人的意料，但是很快释然，若非如此，能够正面硬扛搬山猿？他朱河就绝无这样的胆识能耐，只是一想到这里，朱河更是难免唏嘘，自己还不到四十岁啊，就已经雄心壮志消磨殆尽了吗，竟然比不得一个刚刚在武道上蹒跚而行的少年。

    朱河也有些好奇，笑问道：“虽然我不曾走出过小镇，不晓得外边江湖的规矩，但是老祖宗曾经闲聊时说起，如果在山下遇到江湖同道，有这样那样的众多忌讳，比如僧不言名道不言寿，还有就是可问师门，不可问武学路数。不过我是真的很好奇，你是如何从搬山猿手下逃脱的，你们小镇那场追杀，我只是事后听老祖宗说起。”

    陈平安有些难为情，“其实就是一直在逃命，从泥瓶巷一直逃到山里，如果不是宁姑娘，我早就死了。”

    朱河犹豫了一下，然后轻声提醒道：“要珍惜这些善缘，和那位宁姑娘的，还有和阮师……阮师傅的，一定要小心维持稳固，千万别断了。”

    陈平安有些疑惑。

    朱河感慨道：“我们只是骊珠洞天的井底之蛙，大家差距有限，就像你我，武学修为，撑死了就是五境之差，至于身份，我一个家生子，难道还有资格瞧不起身世清白你？可是在井外的天地，会大不一样，你以后走得越远，在外边混得越久，就会理解得更透彻。”

    陈平安诚恳道：“我没想那么远。”

    朱河大笑道：“可以好好想一想了。”

    陈平安点点头。

    对于别人的善意，陈平安一向很珍惜。

    对于别人的恶意，若是暂时没办法跟那些人说清楚道理，那就且放心头，绝不忘记。

    毕竟路还很长。

    大树底下，刚刚把姐姐李柳给卖了的李槐，现在他在阿良面前腰杆子特别粗，大大咧咧说道：“阿良，回头我让陈平安给你做个酒葫芦，你把腰间那个小葫芦送给我吧，一家人不说两家话，绝不亏待你，反正你这个看着就显旧，配不上我妹夫的身份！”

    阿良神神秘秘道：“你懂个屁，这葫芦叫养剑葫，是全天下少有的好东西，看着不起眼，值钱得很，你有几个姐姐？反正一个打死也不够！”

    看到阿良难得用这么硬气的言语跟自己说话，小屁孩有些心里打鼓，眼馋地瞅着那只小葫芦，恋恋不舍地抬起头，试探性问道：“要不然我让爹娘多生几个姐姐？这事好商量啊，对不对？”

    阿良伸手捂住额头。

    没来由想起之前跟陈平安一起走下山坡，那少年竟然把自己跟第五境的朱河相提并论，阿良松开手，哀叹一声，随手捡起一干枯枝丫在地上划来划去。

    李槐探过头一看，是一个歪歪扭扭的字，写得真心不如自己这个蒙童好看，更比不上连齐先生也说不俗气的林守一了。

    李槐越看越觉得丢人现眼，看一下阿良的字，再看一下他腰间的银白色酒葫芦，一番天人交战之后，李槐说道：“阿良，你写字这么丑，我决定还是不让你做我的姐夫了，我爹娘都希望姐姐以后嫁给读书人的。”

    阿良缓缓抬起头，满脸匪夷所思，“很难看吗？”

    李槐心情沉重，使劲点头。

    小孩觉得姐姐李柳下次要是再敢跟自己抢东西吃，非要骂她没良心，自己可是为了她连那啥养剑葫都不要了。

    阿良一脸你年纪小你不懂事的神色，笑呵呵道：“怎么可能，不是我跟你吹牛，在一个离这个很远的地方，不知道多少人看到这个字后，都纷纷竖起大拇指。”

    李槐疑惑道：“当面？”

    阿良干笑道：“听说，听说。”

    李槐说道：“我就说嘛，谁有那脸皮跟你当面说写得好，我就拜他为师，估计连我娘也骂不过他。”

    阿良讥笑道：“你拜人家为师，人家就收你为徒啊？”

    李槐一本正经道：“不收？他眼瞎啊？”

    阿良再一次捂住额头，因为那家伙还真是个瞎子。

    阿良想着自己还是少跟这个小王八蛋说话，抬起头环顾四周，左看右看，最后看到少女朱鹿，笑道：“朱鹿，想不想学习剑术啊？我现在有一些出剑的兴致了……”

    不远处，朱鹿正在担心自家小姐。

    红棉袄小姑娘双手托着腮帮，望着小师叔离去的方向，眉头紧皱。

    听到阿良这句话后，少女愤懑道：“一边凉快去！”

    阿良眼神无辜且茫然：“刚下过这么一场大雨啊，你看我都浑身湿透了。”

    少女察觉到自己的失误，可仍是冷笑道：“吊儿郎当，不学无术，不是好人！”

    阿良气恼道：“小宝瓶，李槐，林守一，我是不是好人？！”

    李槐落井下石，“只是像好人。但如果肯送我酒葫芦，就是好人。”

    林守一冷淡道：“以后别骗我喝酒了，先生早就说过，文人斗酒诗百篇，全是假的。”

    只有红棉袄小姑娘对阿良偷偷一笑，阿良顿时心里暖洋洋的，朝她伸出大拇指，把其余两个家伙的冷嘲热讽当做了耳边风。

    阿良的江湖，终究不是白混的。

    等到陈平安和朱河走回，一行人重新上路。

    当原本东南方向的龙尾溪绕向正南方，成为大骊地方县志上崭新朱批的铁符河，顿时河水滔滔，水势大涨。

    河面之宽，河水之深，远胜之前的小溪气象。

    在陈平安的提议下，稍作休整，在这里煮米做饭，吃过午饭之后再赶路。

    李槐站在河边，叉腰啧啧道：“阿良，你以前见识过这么大的水吗？”

    前者白色驴子的阿良看了眼溪河交界处，又看了眼身后，最后对李槐笑道：“我见过的大江大河，比你吃过的饭粒还多。”

    李槐顿时不乐意了，“阿良，你是不是一天不吹牛就浑身不舒服？！”

    阿良置若罔闻，走到搭建简易灶台的少年身边，轻声道：“走，河边走走，有些话要跟你说。”

    陈平安愣了愣，就请李家婢女朱鹿帮忙，李宝瓶一路行来，其实已经能够帮上很多忙，甚至连帮助阿良喂养白驴也熟稔得很，所以手脚利索地帮着朱鹿姐姐一起煮饭，让她的小师叔只管去河边散步，一切包在她身上的俏皮模样。

    这些日子里，小姑娘始终坚持自己背着背篓，尽力自己打理一切。

    少年每次打拳走桩的时候，她往往都会默默陪在身边，有样学样，娇憨可爱。

    两人走到河边，然后沿着河水向下游行去。

    阿良坦诚相见道：“我很喜欢宝瓶这个小丫头，当然，你只会比我更喜欢。”

    陈平安回头望去，小姑娘在那边忙来忙去，又是车轱辘似的双腿，对比说一句做一事的林守一和万事不动手的李槐，虽然李宝瓶年纪还小，但是生机勃勃，哪怕只是看着她，就像看到一个美好的春季。

    陈平安点了点头。

    阿良又说道：“但是你总觉得哪里不对，是不是？”

    陈平安嗯了一声，“自从上次跟我聊了关于武学的事情后，一口气说了很多，可是在那之后，好像她不太爱说话了。”

    阿良问道：“你是不是跟她说了什么期望的话语，比如说你希望她以后可以成为怎么样的人？”

    陈平安猛然转头，满脸震惊。

    阿良大概也是不想无意间言语伤人，难得小心酝酿措辞，干脆停下脚步，蹲在河边，轻轻丢掷石子，在少年蹲在自己身边后，阿良轻声道：“情深不寿，慧极必伤，一般人自然没资格套用这两个说法，但是李宝瓶不一样，虽然现在还小，第一点当然是没影的事情，可第二点，她是已经适用了，她将你陈平安当做了依靠，所以你的一句无心之语，一件无心之举，都会让小姑娘深深放在心里，话语这东西，很奇怪，是会一个一个字一句一句话，落在心头堆积起来的，可能你觉得我这个说法比较像半桶水的老学究、酸秀才，可道理还真就是这个道理。”

    陈平安轻轻呼出一口气，“是我的错，我当时怕她没信心走到山崖书院，就说了我希望她能够成为一位女先生，小夫子。”

    阿良笑了笑，“‘是我的错’？陈平安，你错了。”

    少年疑惑不解。

    阿良不看少年，只是懒洋洋望向平静无澜的河面，“你只是没有做得更好，而不是做错了。”

    少年更加纳闷，这两者说法不同而已，可造成的结果，不还是一样的吗？

    阿良终于转头，似乎一眼看穿少年的心思，摇头道：“很不一样。知道为什么天底下的好人，一个比一个做得憋屈吗？比如齐静春，你们认识的齐先生，明明可以更做事更痛快，可到最后的结果，就只是那么窝囊憋屈？等到你环顾四周，好像那些个坏人，却又一个比一个活得潇洒快活，比如你之前跟我提到过的两个仇家，正阳山护山猿，老龙城苻少城主，他们回到自己的地盘后，确实会过得很舒心，一个地位崇高，躺在功劳簿上享受尊敬，一个野心勃勃，志在北方。”

    阿良看着陷入沉思的少年，洒然笑道：“所以啊，做好人是很累的事情，你千万不能做了好人，没有得到回报，或者只是得到意料之外的答复，就觉得自己做错了，更不能觉得自己以后再也不当好人了。这样……是不对的！”

    阿良脸色严肃，加重语气，重复最后一句话：“这样是不对的！”

    阿良笑了起来，重新变成那个万事不挂心头的浪荡子，“当然，李宝瓶好得很，小姑娘只是以她独有的方式在回报你，你可别想岔了。”

    陈平安使劲摇头道：“没有没有。”

    阿良点点头，“所以我才愿意跟你说这些。”

    他干脆一屁股坐在地上，横放竹刀在双膝，“要知道，我很少跟人讲道理的，我的道理……”

    阿良略作停顿，拍了拍自己膝盖上的绿色竹刀，“以前在剑，如今暂时在这刀。”

    阿良哪怕不下雨，日头不大，也会戴着那顶不起眼的竹篾斗笠，他随手扶了扶斗笠，“如果你的性格不对我的胃口，哪怕那根簪子意义跟我之前想象那般重大，哪怕你是齐静春挑中的人，我也不会跟你唠叨这些话，大不了把你送到大骊，心情好的话，直接把你丢到大隋就是了，对我来说，有什么难的？”

    这个嬉皮笑脸的汉子认真起来，别有风范，双手轻轻拍打竹刀，“对我阿良来说，人生于天地间，路要自己走，话要自己说，人要自己做。我觉得你陈平安，也该这样，不一定全部像我，但要腰杆够直，拳头够大，骨头够硬，更要剑术够高！”

    阿良哈哈大笑起来，“别忘了，最重要的是活得够久！”

    陈平安老老实实道：“阿良，虽然有些听明白了，有些还不是很懂，但我都会记在心里，以后遇到什么事情，都会拿出来好好想一想。”

    阿良点点头，欣慰道：“这就很够了。”

    阿良率先站起身，走出去几步，突然转头说道：“陈平安，我带的干粮吃完啦。”

    说完之后，阿良就快步离去，走向李宝瓶朱鹿那边，嚷嚷道：“开饭没，开饭没？！”

    留下一个没回过神的少年。

    说来说去，绕这么大一个圈子，这家伙就是为了光明正大的蹭吃蹭喝？

    陈平安笑着跟上。

    有一天黄昏，一行人远远经过一片绿意葱葱的山间竹林，红棉袄小姑娘扯了扯陈平安袖子，伸手指向那边，小声问道：“小师叔，竹林哦，好看吧？”

    忙着赶路的少年嗯了一声，继续埋头赶路，因为他们马上就要见到阿良所谓的驿路了，大骊朝廷的官道。

    小姑娘默不作声，颠了颠身后的背篓，仍然紧紧跟在少年身后。

    夜里睡在朱鹿搭起的狭窄牛皮小帐篷里，小姑娘想起一事，撅了噘嘴，有些委屈，最后告诉自己小师叔已经很好啦很好啦。然后沉沉睡去。

    第二天清晨，睡眼惺忪的小姑娘不敢贪睡，怕耽误了小师叔的既定行程，自己迅速穿好衣裳，穿上那双小师叔帮她做的草鞋，结果小姑娘刚钻出帐篷，整个人就呆住了。

    就在帐篷外，放着一只漂漂亮亮的绿竹小书箱。

    小姑娘愣了很久，然后一下子就嚎啕大哭起来。

    忙了一晚上的少年正在远处昏睡，被哭声惊醒后，赶紧起身跑过去，站在小姑娘身前，陈平安一时间有些手足无措，摸着脑袋不知道如何安慰她，本以为小丫头天一亮看到小竹箱后，会高兴呢。

    看到李宝瓶这么伤心，陈平安真是心疼得厉害。

    小姑娘闭着眼睛哭了很久，睁眼看到陈平安之后，一下子止住哭声，快步跑到他身前，狠狠抱住陈平安，哽咽道：“小师叔，对不起！”

    陈平安只好轻轻拍着小姑娘的脑袋，“不哭不哭。”

    小姑娘只是哭，伤心坏了。

    陈平安柔声道：“不喜欢小竹箱？是小师叔做得不好看？没事没事，下次可以改样子，没办法，小师叔以前只见过一次小书箱，以后到了外边的热闹地方，再见着了好看的书箱，你告诉小师叔……”

    小姑娘抬起头，满脸泪水，“喜欢！没有比这个更喜欢了！”

    可似乎越是喜欢，小姑娘就越觉得自己没良心，越对自己的小师叔心怀愧疚，蹲在地上抽泣起来，不敢看小师叔。

    陈平安想到昨天阿良的言语，一下子想明白了，蹲下身，摸着小姑娘的脑袋，轻声道：“李宝瓶，知道吗？小师叔能够陪你一起远游求学，真的很高兴，只是以前没有跟你说过，所以现在小师叔跟你说了，如果你还能喜欢这个不值钱的小竹子书箱，那小师叔就更开心了，真的，不骗你。”

    小姑娘缓缓抬起头，但是双手还是蒙住脸，她只敢露出指缝，悄悄露出那双灵气盎然的眼眸，怯生生抽泣道：“小师叔不骗人？”

    少年眼神清澈，点头道：“小师叔也会骗人，但是不骗李宝瓶。”

    小姑娘迅速拿开手，笑容灿烂。

    又是少年印象里的那个无忧无虑、天真烂漫的小姑娘了。

    所以少年也很笑容灿烂。

    有些人心如花木，皆向阳而生。

    小师叔和小姑娘尤为如此。
------------

next：第九十三章 墙上有个字

    一座高不过十多丈的小山坡，分散站着二十余个人，穿着衣饰并无定数，但是脸色、眼神都像是一个模子里刻出来的。

    一名魁梧男子单膝跪地，正在仔细查探身躯僵硬的两具尸体，他用手指撑开一具尸体的眼皮，露出冰裂纹瓷片一样的眼珠子。

    一名换上一身市井妇人棉布衣裳的矮小女子，缓缓走上山坡，身后跟着捧剑女子和白脸老人。

    她没有靠近那两具尸体，捂住鼻子，用浓重的鼻音问道：“王毅甫，怎么说？”

    王毅甫叹息道：“两人都是被高手一刀毙命，不伤身体，但是经脉皆碎，五脏六腑都烂透了。”

    妇人脸色阴沉不定，“我们大骊出现了这么强大的武道宗师，而且还是两位同行，咱们那位藩王殿下，一向负责边关监视，号称，难道偏偏这次就一点蛛丝马迹也不曾抓到，总不可能是故意放跑漏网之鱼吧？”

    王毅甫有些犹豫，“娘娘，如果我没有看错，是一人所为。”

    妇人骤然眯眼，气势凌人，“你说什么？！”

    王毅甫指了指两人的脖颈，出现一缕细微的红线，“两名死者之间的这条线，气势衔接紧密，分明是一人以刀横抹。”

    妇人深呼吸一口气，竭力让自己的怒气杀机不要太明显外露，讥笑道：“风雪庙什么时候这么天下无敌了？随便跑出来一个莫名其妙的家伙，就能杀人跟杀鸡一样简单？这两个人是谁，你王毅甫不知道，徐浑然知道，来，说说看，让我们王大将军如雷贯耳一下。”

    徐浑然脸色尴尬，硬着头皮解释道：“一位是刚刚跻身武道第七境的宗师，精通拳法，擅长近身厮杀，一位是八楼修士，兼修飞剑和道家符箓，二十年间，两人联手刺杀六次，从未失手过，如今更是娘娘麾下竹叶亭的甲字高手。”

    妇人愤怒至极，只是一直在苦苦压抑而已，此时便迁怒这位大骊第一剑师，尖声道：“徐浑然！报上他们的名字！死人也有名字！”

    老人心中悚然，微微低头道：“武人名叫李侯，修士名为胡英麟，都曾为娘娘一次次出生入死，为我大骊立下汗马功劳。”

    妇人这才神色微微转好，只是很快满脸颓然，有气无力道：“对，李侯和胡英麟，当年你们卢氏王朝的边关砥柱叶庆，就是这两人杀掉的。没死在敌国境内，没有死在沙场上，而是死在了我们大骊自己疆土上。”

    妇人兴许是意识到自己的失态，会让王毅甫看笑话，就拿这位武将曾经效忠的卢氏开刀，“说来可笑，开始我们觉得叶庆这么一号重要人物，身边肯定会有数名大练气士暗中保护，为了除掉他，我甚至不得不和我家叔叔联手。哪里想得到，从渗透边境，潜入杀人，再到功成身退，卢氏王朝竟然一点反应也没有。他叶庆不过是惹恼了几股边境仙家势力而已，至于在朝堂上也被孤立到这一步？卢氏皇帝不是最推崇山上仙人吗？为何最后愿意陪你们卢氏殉葬的仙家宗门，就只有一家而已？”

    说完这些，妇人有些神清气爽，心里痛快多了。果然是吃苦不怕，只要身边有人更苦，享福可以，但是不可以身边有人享福更多。

    这恐怕就是她愿意将其中一个孩子交给国师崔瀺，而不是山崖书院齐静春的理由了。

    省心省力，不怕长大之后被人欺负得只会哭着找爹娘。

    王毅甫脸色闪过一抹黯然。

    大将军叶庆，国之忠良，国之栋梁。为卢氏王朝镇守边关三十年，硬生生挡住大骊边军的三次大型攻势。当年宋长镜有次差点战死战阵之中，不知道多少回大骂叶庆是冥顽不化的老匹夫。但是到最后，叶庆死后，卢氏朝廷竟然连追封谥号一事，就争吵了一旬之久，关键是哪怕这样，也没给太高的美谥，以至于犹有一战之力的六万精锐边军，军心慢慢散尽。

    宋长镜挥师而过，如入无人之境。第一件事情，就是亲自去此人坟头敬酒上香，事后大骊礼部非议，被宋长镜一份折子就打得满脸肿，“岂是唯我大骊有豪杰？”

    大骊皇帝接连批阅三个大大的好字，大笑不已。龙颜大悦的皇帝，不过最后对身边宦官笑着说，这句话是皇弟的心里话，至于这几个字嘛，肯定是找了捉刀郎代劳的。

    妇人其实一直在观察这位亡国猛将的脸色。妇人暗暗点头。虽未因此就对他彻底放心。

    若是连人之常情都失去了，必是怀有坚忍不拔之志。做什么？除了复国能够做什么？

    那么王毅甫就真是找死了。

    若是王毅甫只知道打打杀杀的一介武夫，能够心思细腻到演戏到如此境界，那也算王毅甫有本事。

    不过她一样不怕。

    老剑师徐浑然疑惑问道：“娘娘分明已经跟阮师打过招呼，答应不会在龙泉县境内动手，咱们也传信给李侯胡英麟，让他们近期不要轻举妄动，一切等走到大骊边境再说。照理说阮师怎么都该卖娘娘这个面子才对，总不至于是那风雪庙的人，连娘娘和阮师的面子都不在乎吧？”

    王毅甫问道：“那名佩刀男子的详细身份，依然没有查出来？”

    捧剑女子摇头道：“尚未有结果，这种事情，我们不好找上门去问阮师，更不好去找那拨风雪庙兵家修士，只能靠大骊自己的谍报机构寻找蛛丝马迹，而边境谍报事务，娘娘不方便插手……”

    说到这里就停下，年轻女子不再说话。

    这涉及到了大骊朝政最高层的暗流涌动。

    王毅甫问道：“有没有可能是那个叫朱河的李家扈从，其实深藏不露？”

    妇人嗤笑道：“那个不过武夫五境的家伙，不值一提。李家更没有胆子在我的眼皮子底下捣乱。”

    老剑师叹了口气，“这就有点难办了。”

    妇人妩媚一笑，“难办？好办得很，立即回京！我跟皇帝陛下哭去。”

    这件事，终究是别人先坏了大骊的规矩，那么皇帝陛下是愿意为她出头的。

    李宝瓶有了崭新的小书箱，背篓里的大小物件就要挪窝，一大一小两人借此机会，在休息的时候，找了个远离李槐等人的僻静地方，偷偷摸摸清点家当，以防遗失或是损坏。

    陈平安也摘下自己的背篓。

    一把老槐木剑，猜测是齐先生赠送，因为当时陈平安头顶莫名其妙戴上了玉簪子。陈平安和李宝瓶都觉得应该是齐先生故意所为，陈平安平时都把槐木剑放在斜放在背篓里，只在夜深人静的时候，拿出来放在膝盖上，少年的心境就会祥和安宁。

    一颗黄色的蛇胆石，放在阳光照射下，就会映照出一丝丝黄金色的漂亮筋脉。

    其余十二颗小巧玲珑的蛇胆石，则已经褪去原本鲜艳色彩，但是质地细腻，依然不俗。

    李宝瓶对这些小玩意儿爱不释手，手心托着那颗黄色蛇胆石，说道：“小师叔，这颗千万别卖，其它十二颗石头，以后就算要卖，也一定要找识货的买家，要不然咱们肯定亏死了。”

    陈平安笑道：“那当然。”

    背篓里还有一块一尺长短的黑色长条石，看着很像斩龙台，但是陈平安不敢确定，记得宁姑娘说过，想要分开斩龙台做天底下最好的磨剑石，不但需要什么剑仙出手，还需要折损一把很值钱的兵器，当然对于少年目前来说，很厉害或者是很珍贵的兵器、物件，都可以直接与值钱挂钩。

    就像对于那位重返姑娘的少女来说，对手的战力，都可以跟多少个陈平安直接挂钩。

    陈平安知道这绝对不会是阮师傅赠送给他的，是齐先生一并送了槐木剑和磨剑石？还是那位白衣飘飘的神仙女子，使出了神通术法？又或者难道是阮姑娘私藏的体己之物？

    陈平安有些头疼。

    阮姑娘之前在李宝瓶背篓里，留下了金锭一颗，银锭两颗，一袋子普通铜钱。有次李宝瓶无意间打开钱袋子，陈平安才惊骇发现里边竟然夹杂有一颗金精铜钱。

    这颗压胜钱，绝对是阮秀偷偷留下的。

    这让陈平安吓了一大跳，当时就满头大汗。如果一直粗心大意，没能发现真相，然后不小心把这颗铜钱当做普通铜钱花出去，一想到这个后果，陈平安就恨不得先给自己两耳光。

    大大小小的物件，陈平安一样样收拾齐整妥帖，就像是精打细算惯了的妇人，在搭理一个小家似的。

    每次李宝瓶看到这一幕都想笑，心想小师叔也太会过日子了。

    那么以后得多优秀的姑娘，才配得上自己小师叔啊？

    小姑娘觉得好难找到，于是她有些小小的忧伤。

    一个鬼头鬼脑的孩子偷摸过来，被李宝瓶发现后，他看着她脚边那只小书箱，对陈平安说道：“陈平安，你要是给我做一个比小竹箱子，要比李宝瓶那只更大更好看，我就喊你小师叔，咋样？”

    陈平安看了他一眼，不说话。

    李槐有些急了，决定退让一步，“那跟李宝瓶那小书箱一样大就行，这总行了吧？”

    陈平安无意间发现李槐的靴子，已经破烂不堪，露出了脚指，说道：“回头给你做两双草鞋。”

    李槐大怒，跳脚道：“我稀罕那破草鞋，我要的是书箱！用来装圣贤典籍的书箱！我李槐也是齐先生的弟子！”

    陈平安皱了皱眉头，“一边去。”

    李槐愕然，仔细打量着陈平安的脸色，两人对视后，李槐突然有些害怕心虚，这个天不怕地不怕的小孩，破天荒没有还嘴骂人，悻悻然离开，只是跑出去几步，转头理直气壮道：“草鞋别忘了啊，要两双，可以换着穿。”

    陈平安点了点头。

    等到李槐跑远，小姑娘满脸崇拜道：“小师叔，你真厉害，你是不知道，李槐这个家伙，我都只能把他打服气，吵架是不行的，就算是齐先生跟他说道理，李槐也不太爱听。”

    陈平安伸手揉了揉小姑娘脑袋，背起背篓，“准备动身，再走两天，咱们马上就可以看到大骊驿路了。”

    小姑娘背起小书箱。

    小姑娘，红棉袄，绿竹箱。

    其实阿良憋得很辛苦，很想告诉这一大一小，如果不是咱们小宝瓶足够可爱，就这颜色装扮，能够让人笑话死。

    李宝瓶突然说道：“这个李槐，有点像小师叔你们泥瓶巷的那个鼻涕虫啊。”

    陈平安愣了一下，好像从来没有把两个字放在一起比较过，仔细想了想，摇头道：“不像的，以后如果有机会见到顾粲，你就会明白了。”

    小姑娘哦了一声，反正也只是随口一提，很快就去想象大骊驿路到底是如何的。

    陈平安其实跟李宝瓶一样，起先也有些觉得鼻涕虫顾粲和李槐有些像，但是相处久了，就会发现两者差别很大。

    李槐跟顾粲看着差不多的性格，嘴里跟长了一窝蜈蚣蝎子似的，毒的很，能够一句话把人气得够呛，在陈平安眼中，其实大不一样，同样是没心没肺，同样穷苦出身，顾粲看似贼兮兮，转起眼珠子来比谁都快，但顾粲身上那股超乎年纪的精明，更多是一种自保，李槐则是纯粹的小刺猬一个，逮着谁都要刺一下，这是因为李槐到底父母健在，上边还有个姐姐，心性其实不复杂，而且上过学塾读过书，身边的同窗蒙童是李宝瓶，林守一，石春嘉这些稍大的孩子，大体上李槐是没吃过大苦头的。

    顾粲不一样，一手拉扯他长大的娘亲，有些时候不得不说也连累了他，使得小小岁数，便尝过了人情冷暖，陈平安就曾经亲眼看到，一个满身酒气的醉汉骂骂咧咧走出泥瓶巷，看到玩耍回家的顾粲，什么也没说，走过去就狠狠踹了顾粲肚子一脚，顾粲倒地后，还狠狠踩了他脑袋一脚，那么点大孩子抱着肚子蜷缩在墙根，哭都哭不出来。

    如果不是陈平安凑巧出门碰到，飞奔过去，一拳打得那汉子踉跄后退，然后赶紧背起顾粲去了趟杨家铺子，天晓得会不会落下什么病根。

    也更加记仇，心里头有个小账本，一笔笔账，记得很清楚，谁今天泼妇骂街骂过了他娘亲，哪家不要脸的汉子嘴花花调戏了他娘亲，他全记得，可能随着岁数增长，有些事情和细节已经忘了，但是对某个人的憎恶印象，顾粲肯定不会忘。当然，那个给了他两脚的汉子，顾粲记得死死的，叫什么名字，住什么巷弄，家里有谁，顾粲全部一清二楚，私底下跟陈平安独处的时候，总是嚷嚷着要把那人的祖坟给刨了，还说那人有个女儿，等她长大了，一定要睡她，往死里欺负她。

    大概那个时候的孩子，根本就不知道睡是什么意思，只知道很多婆姨汉子喜欢“开玩笑”，与他娘亲相关的言语，妇人说偷人二字，汉子则往往都带着个睡字。

    陈平安至今记忆犹新，孩子不过四岁多，那张稚嫩的小脸，脸庞狰狞，满是凶光，眼神狠厉。

    陈平安有些担心，他当然希望顾粲在外边过得比谁都好，但同时打心底不希望顾粲成为蔡金简、苻南华那样的神仙人物。

    看着心不在焉的小师叔，李宝瓶问道：“怎么了？”

    陈平安若是以前，就会说没事，但是现在开门见山说出了心里话，“我怕下一次见到鼻涕虫，会变得不认识他了。”

    李宝瓶疑惑道：“小孩子个子窜得快，如果过个四五年七八年才见面，你们不认识也很正常啊。”

    陈平安咧嘴一笑，更像是自己给自己打气鼓劲：“我相信顾粲，一直会是那个泥瓶巷的鼻涕虫。”

    至于认不认得自己，没关系。只要那孩子过得好，比什么都好。

    铁符河的河床出现断层石崖，下跌迅猛，下游水势顿时暴涨。

    陈平安站在河畔石崖上练拳，来来回回都是那走桩六步。

    阿良不知道何时站在石崖边缘。

    水花四溅，水声滔滔，水雾弥漫，好在暮春时节，寒气已降，并不显得寒意刺骨。

    阿良大声说道：“你练这个拳，没太大意思。这走桩，是个很入门的小架，随便哪个江湖门派都有，倒是那个立桩，还算马虎，最少能够帮你勉强活命，像是吊命用的药材，不名贵，但好在对症下药。”

    少年听在耳中，笑了笑，没有说话。

    因为姚老头说过，练拳之时，切忌泄气。

    阿良点点头，“但是一件没意思的事情，有意思的人可以做得很有意思。你这么练拳，问题不大。武道一途，本就是实打实的滴水钻石，靠的就是水磨工夫。”

    陈平安练拳完毕，擦了擦额头汗水，问道：“阿良，你不是那个什么神仙台魏晋吧？”

    阿良笑道：“当然不是，他念诗那是一套一套的，酒品奇差无比，一喝高了就喜欢一把鼻涕一把泪，比李槐还不如。我怎么可能是这种人。”

    陈平安愣了一下，似乎没想到阿良这么直截了当，“那毛驴和酒葫芦？”

    阿良白眼道：“自然都是魏晋的。我可没他这么穷讲究，喝酒倒是喜欢，骑驴看山河什么的，真做不来，慢腾腾的，能把我急死。”

    陈平安小心翼翼问道：“他不会是死了吧？”

    阿良笑意玩味，“我杀他干嘛，杀人夺宝啊？”

    陈平安看着阿良，摇摇头，“我相信你不会杀他。”

    阿良拿起本该用来养剑的酒葫芦喝了口酒，“这只养剑小葫芦是他送给我的，我教了他一手上乘剑术，那小子茅舍顿开，终于打破了瓶颈，所以闭关去了。作为酬劳，他就把葫芦送给了我。别觉得是我占便宜，是他赚大发了。我只是帮着照看这头毛驴而已。”

    风雪庙兵家剑修的十搂，想要破开，难得很。

    不过这种话，阿良不想跟陈平安解释得太清楚。

    路是要一步步走的。

    陈平安有些奇怪，问道：“阮师傅为何没有认出你来？”

    阿良找了个地方坐在，晃了晃银白色的小葫芦，“葫芦里的本命剑气犹在，且无残缺，这意味着主人尚存，神魂体魄皆全。你们东宝瓶洲是个小地方，阮邛不觉得在这里有太过吓人的高手，能够瞬间斩杀魏晋不说，还能够快到连魏晋的本命飞剑都来不及联系。”

    陈平安惊讶道：“小地方？有人说我们东宝瓶洲王朝有千百个，我们到现在还没走到大骊边境呢。”

    阿良扭头把酒壶丢给身边站着的少年，“你也知道是‘走‘的啊，来来来，喝口酒，男人不会喝酒，就是白走一遭了。”

    “不喝酒。朱河说过练武之人，不能喝酒。”陈平安小心接过酒葫芦，坐在阿良身边，递还给他，阿良却没接，陈平安只好小心翼翼捧在怀里，望着河水，轻声感慨道：“也是，我见过踩在剑上飞来飞去的神仙，从咱们小镇头顶上飞过去，很多。”

    阿良现在一听到朱河就有些烦，偏偏身边这家伙喜欢拿自己跟朱河比较。

    陈平安笑问道：“阿良，你真能教魏晋剑术？那你岂不是要比朱河还要厉害？”

    又来了。

    阿良叹了口气，“我也就是脾气好，不跟你一般见识。”

    陈平安是真的很好奇这件事，打破砂锅问到底，“难道还要厉害很多？”

    阿良一把抢过酒葫芦，仰头灌了一口酒，满脸嫌弃道：“滚滚滚。”

    陈平安哈哈大笑，转头看着一脸郁闷的斗笠汉子，眨眨眼，嘿嘿道：“其实我知道你比朱河厉害很多。”

    阿良总算好受一些。

    陈平安马上补了一句，语气诚恳道：“我觉得两个朱河都未必打得过你。”

    阿良无奈道：“你如果真想拍马屁，有点诚意行不行，好歹把‘未必’两个字去掉啊。”

    陈平安默不作声，嘴角翘起，望着那条声势浩荡的青色瀑布，突然说道：“阿良，谢谢你。”

    阿良一口一口喝着酒，随口问道：“嗯？谢我做什么，既没有教你练拳，也没有教你练剑。”

    陈平安盘腿而坐，习惯性双手十指在胸口，练习剑炉拳桩，“遇到你之后，觉得外边的世界，没那么让人觉得害怕了。因为我发现原来外边，也是有好人的，不都是谁都本事高就随意欺负人。一路上李槐朱鹿那么说你，也从不生气。”

    阿良笑着喝了一口酒，慢了一些，“这一番表扬，来得让人措手不及，让我喝口酒压压惊。不过你小子也会害怕？敢小巷杀年纪轻轻的神仙人物，敢和搬山猿正面硬扛？敢二话不说就带着小宝瓶出来远游大隋？你胆子真不小。”

    陈平安轻声道：“有些事情做了，是因为必须要做，不代表我就一点不害怕啊。我就是一个烧瓷的窑工学徒，胆子能大到哪里去？”

    阿良点点头，“是这个理。”

    两两无言，唯有水声。

    阿良率先打破沉默，问道：“如果在一个很出名的地方，你做了一件很出风头的事情，然后你可以刻下一个传承千秋万年的大字，你会挑选哪个字？”

    陈平安想了想，“应该是我的姓氏吧，我爹娘都姓陈，刻下陈这个字，多好。”

    阿良摇头叹息，“真俗气，不像我。”

    阿良很快自顾自解释道：“正常正常，像我这样的奇男子，毕竟是凤毛麟角的存在，牛羊成群于平地，猛虎独行于深山。寂寞啊。”

    斗笠汉子兴许是自己把自己给说感动了，赶紧狠狠灌了一大口酒。

    草鞋少年突然咧嘴笑起来，笑得怎么都合不拢嘴，像是也想到很开心的事情。

    这绝对是稀罕事。

    于是阿良问道：“想什么呢，傻乐呵？”

    少年有些脸红，赧颜道：“如果可以多刻字的话，那我就在那堵墙上，写下心爱姑娘的名字。”

    阿良龇牙咧嘴，啧啧道：“那你多烧香，祈求你未来媳妇的名字只有两个字，如果是三个字，四个字，呵呵。”

    陈平安愣了一下，“难道还有人的名字是四个字？那不是很怪吗？”

    阿良拍拍少年肩膀，“陈平安，以后多读书。”

    陈平安有些难为情。

    阿良猛然惊醒，“陈平安，你有喜欢的姑娘了？！谁谁谁，赶紧说出来，让我乐呵乐呵！”

    陈平安笑眯起眼，摇头道：“没呢。”

    阿良伸手指了指少年，“一开始就知道你不老实。”

    陈平安小声问道：“阿良，你现在还是打光棍吧？”

    阿良：“闭嘴！”

    陈平安还以颜色，“一开始我就知道了。”

    阿良伸出大拇指，指着自己，道：“知道在别的几处地方，多少女侠仙子哭着喊着要嫁给我阿良吗？”

    陈平安一本正经回答道：“我当然不知道啊。”

    阿良吃瘪后，默默喝酒。

    陈平安问道：“对了阿良，你刻了个什么字？可以说吗？”

    阿良立即神采焕发，得意洋洋，“那可了不得，我那个字写得铁画银钩天下无双不说，关键是那个字很有味道！朗朗上口，气势如虹，比起什么姓氏啊浩然啊雷池啊，要好上太多了。你是不知道，为了拦阻我刻下这么个字，好些老乌龟王八蛋的脸都黑了，没法子，就怕货比货，其中有几个辈分挺高的家伙，气得吹胡子瞪眼睛，差点就要卷起袖子跟我干架，我才懒得理睬他们，你们几个不要脸皮合伙打我一个，我不跑？我傻啊，对吧？当然了，我是刻完字再跑的。”

    陈平安有点后悔问了这个问题。

    阿良一脸“你快问是哪个字”的表情。

    陈平安轻轻转头，重新望向河水，打死也不开口说话。

    阿良呆若木鸡。

    斗笠汉子轻轻塞好香气四溢的酒葫芦，显然是连喝酒的兴致也没了。

    就在此时，陈平安蓦然瞪大眼睛，发现铁符河下游的河面上，竟然有四五人联袂踏水而行，有白发苍苍的蓑衣老人高歌“自古名山待圣人”，有衣裳艳丽的妖娆女子娇笑连连，还有身穿道袍的小童子手持竹杖，老气横秋。

    陈平安瞪大眼睛，喃喃道：“神仙？”

    阿良连正眼也没瞧一下。

    朱河手持一串红色铃铛，急促响动，往陈平安和阿良这边飞奔而来，脸色沉重道：“这是老祖宗留给我的震妖铃，一旦有妖魅山精靠近铃铛百丈之内，便会无风自响，阿良前辈，陈平安，我们最好小心一些，先离开这河畔石崖，以免发生不必要的冲突。”

    陈平安想了想，就要起身。

    阿良根本不看河面那边的奇异景象，拔出酒塞子，对两人晃了晃，笑道：“我喝过这口酒就走，很快的。”

    朱河有些焦急，“阿良前辈，咱们大骊朝廷对于山野妖魅的管束，一向极为宽松，只要不闹出人命，一般是从来不插手的……”

    阿良啊了一声，说着这样啊，赶紧起身，就要跟他们一起离开石崖，给那拨不速之客让路。

    但是河面之上，那五位神异非凡的家伙，各自的境界修为，高下立判，道行最高的蓑衣老叟第一个像是被天雷劈在脑门上，止住身形，一动不动，之后四位皆是如出一辙。再然后，又是满身仙气的老叟第一个掉头，撒腿狂奔，这次可顾不上什么神仙风采了，恨不得手脚并用，之后四人仍是如此。

    阿良一脸假得不能再假的狐疑神色，还带着坏笑。

    朱河咽了口唾沫。

    手中铃铛已经寂静不动。

    他试探性问道：“阿良前辈，这是？”

    阿良系好那只银色小葫芦，揉了揉下巴，“难道是我杀气太重？”

    陈平安小声问道：“阿良，是那些家伙认出了你的这只养剑葫芦？”

    阿良爽朗大笑，搂着少年的肩膀，走下石崖，“有可能有可能，养剑葫芦里大有玄机嘛。一般人我不告诉他。”

    阿良突然松开手，让陈平安先回去。

    草鞋少年小跑离去。

    阿良仍然跟朱河勾肩搭背，低声问道：“朱河，你是武夫第五境，对吧？你是怎么含蓄得让陈平安觉得你是高手的？不如教教我，否则我费了这么大力气，白白摆了那么多高手架子，那小子也照样睁眼瞎啊。”

    朱河身体僵硬，忐忑不安道：“阿良前辈，这个我真不知道啊。”

    阿良怒道：“这就没劲了啊。”

    朱河哭丧着脸，“阿良前辈，我真不知道。”

    前边，少年转身倒退着小跑，面朝阿良，大声笑问道：“阿良，那个字到底是啥？”

    阿良顿时神采飞扬，咳嗽一声，一手扶了扶斗笠，一手高高伸出大拇指，“猛！”

    少年跟河面上那五个家伙一样，如遭雷击，然后默默转身，飞奔离去，嘀咕道：“你大爷的！”
------------

next：第九十四章 秀色可餐

    铁匠铺子那边总计挖出七口水井，井水甘甜，冷气森森。

    传言那个曾经在骑龙巷住过一段时间的阮师傅，是会铸剑的神仙，连朝廷也敬重得很。礼部官老爷和小吴大人，都曾经亲自去拜访过。所以阮师傅的身份不简单，绝对假不了。很多人都想着把孩子塞进铁匠铺子，只可惜已经不招人了，不过阮师傅倒是有次去镇上买酒，挑中了两个孩子做学徒，第二天酒铺子就人满为患，全是大人长辈拎着自家孩子，问题在于也没人真正买酒，全眼巴巴等着阮师傅能够看中谁，孩子可不管什么前程不前程，撒腿闹得欢，鸡飞狗跳吵翻天。

    小镇其实在县令吴鸢出现之前，只知道自己是大骊子民，龙窑是为大骊皇帝家里烧制瓷器，仅此而已，其余一概不知，小镇人员流通极少，根本不存在什么拜访亲戚、出门游学、远嫁他乡，书上不教，老辈不说，世世代代皆是如此，四姓十族当中知道一些内幕的人物，更不敢泄露天机。

    那些本命瓷被挑中的幸运儿，能够走出去欣赏外边的大好河山，在骊珠洞天破碎下坠之前，根本没有衣锦还乡的机会，这是小镇四方圣人早年订立的规矩之一。

    如今按照县衙张贴的告示和识字之人的讲解，才知道以前是因为龙泉县的山路，太过险峻，如今朝廷花了大力气才开通道路，是为了开山一事，要把那些山头送给某些相中此地风水的大人物，与此同时，县衙礼房吏员为首的一拨人，开始为辖境百姓讲解各种规矩，应该如何与外乡人相处，

    比如不可胡乱对着外乡人指指点点，稚童不可冲撞街道行人，绝对不许擅自触碰外乡人的坐骑等等，如果一旦出现任何争执，百姓则必须如实向龙泉县衙禀报，不可自作主张，官府会秉公处理。

    四姓十族对此并未展露出太过热情，更没有帮着县衙出面做点力所能及的意思，更多还是冷眼旁观，至于是不是等着看县衙闹笑话，就只有吴鸢和那帮老狐狸肚子里清楚了。

    小镇的巨大变化，对自幼在兵家祖庭风雪庙长大的阮秀而言，感触不深，或者说也不在意。

    她自从遇到某个矮冬瓜之后，就心情郁郁。

    那蛮横妇人大摇大摆去了陈平安家的宅子不说，还把院门和屋门铜锁都给弄坏了，她之前跑去给两栋宅子打扫的时候，刚好撞到那拨前去换锁的人，阮秀气得柳眉倒竖，跑上去讲道理，那几人仿佛知晓她的身份，毕恭毕敬道歉赔礼，但是幕后罪魁祸首到底是谁，摆出一副阮小姐你就算活活打死我们也不敢说的无赖架势，这也就罢了，阮秀要他们交出旧锁和崭新钥匙，回到铁匠铺子，就碰到那个矮冬瓜，她竟敢还有脸笑眯眯说是自己不小心，才打坏了铜锁。

    阮秀还依照约定，雇人修缮泥瓶巷一栋无人居住的破败宅子，屋顶塌陷出一个大洞，房梁腐朽，红漆剥落。阮秀要那些小镇出身的砖瓦匠，仔细修补，小心添砖加瓦，最后实在不放心，还专门盯着他们做事大半天功夫。

    再就是相邻的压岁铺子和草头铺子，都挂名在了陈平安名下，两间老字号铺子的老伙计，走得七七八八，只得另外雇佣伙计，她不敢挑选一些油滑之辈，便让自家剑铺的人，推荐了些性情本分却手脚伶俐的妇人少女，帮忙打理生意。

    压岁铺子继续贩卖各式糕点吃食，草头铺子则继续兜售杂项物件，文玩清供、古琴字画，五花八门的东西都有。

    阮秀只要剑铺没事的时候，就会趴在某一间铺子柜台上，怔怔出神，很多时候大半天时光就这么悠悠然流逝。反正不用她招徕生意，她也不擅长跟人讨价还价，事实上这两家铺子都属于陈平安的家底，青衣少女恨不得一块糕点卖出几两银子的天价，只不过终究是心性淳朴的少女，没好意思这么做，只是犹豫着要不要帮他找几个懂得察言观色的人，帮着铺子多赚些钱，但是她又怕那样的人，他回到家乡的时候，会不喜欢。

    因为他不是那样的人。

    就连糕点也没那么馋嘴贪吃的少女，所以原本圆圆润润的下巴，逐渐有些尖尖的了。

    如小荷露出尖尖角，清新动人。

    阮邛倒是几次提起，要是她觉得小镇这边闷得慌，可以去神秀山横槊峰那边走走看看，山水风光还不错。只是少女一直提不起这个劲儿，一直拖拖拉拉，阮邛也就作罢。但少女越是这么浑浑噩噩，打铁铸剑的时候，反而越是聚精会神，神意充沛，境界攀升更是一路高歌猛进，这才让阮邛放下心来，既然于修行是好事，他就不会去指手画脚。

    因为一个凡夫俗子的坟头，早已青草葱葱，甚至子孙也已白发，可是曾经同龄的修行有成之人，却依然还是女子貌美的光景。

    阮秀这两天更加心烦，因为每次她来到铺子发呆，都会有人来打搅。

    是一个腰间别有一支朱红色长笛的年轻人，锦衣玉带，头戴紫金冠，很趾高气昂的作态，可是这个人的样子，她倒是忘了，或者说从来没有认真看过。

    因为阮秀自从年幼记事起，就见过太多太多这样的人了。因为她爹是阮邛，不但是风雪庙大修士，更是东宝瓶洲首屈一指的铸剑师。

    不过到了这里后，阮邛跟她说过，已经跟大骊朝廷打过招呼，在甲子之内，大骊不可以对外大肆宣扬，用他阮邛这块金字招牌来谋划什么。一旦被他阮邛发现，商量是可以商量，但是结果如何，阮邛不会保证。在阮邛在洞天下坠沦为大骊版图之后，那场厮杀，不但杀得周围修士肝胆欲裂，其实连大骊朝廷和更远的山上势力，都已领教过圣人阮师的脾气，没人愿意拿性命来跟阮邛讲道理，敢这么做的人，要么被阮师在自己地盘上名正言顺地打死，要么被扯进地界光明正大地打死。

    都不用阮邛直说，大骊那一小撮真正的大人物，其实心知肚明，这位从风雪庙脱离出来自立门户的圣人，真正的逆鳞所在，是他那个公认天资卓绝的女儿。若非阮秀的缘故，阮邛当初绝对不会从风雪庙离开，从齐静春手里接手骊珠洞天，因为当时没有谁会将坐镇这座小洞天视为美差，那意味着一身修为和境界受到天道压制，能够维持境界不跌落、体魄不朽坏，已是极致。

    当然，齐静春是例外，很大的一个意外。

    既然阮邛的命脉是他女儿，所以如今大骊刻意帮忙保密，绝不敢轻易对外提及阮秀的名字。

    于是就有不明就里的家伙，无意间逛荡到小镇骑龙巷的草头铺子，见到那位马尾辫少女后，立即惊为天人，心想一间铺子的少女罢了，身份撑死了也高不到哪里去，以他的容貌谈吐和身世背景，还不是手到擒来，让她对自己一见钟情，心甘情愿做那红袖添香的奴婢，素手研磨的丫鬟？

    不过他到底是身负家族使命，来这里买山头，而且小镇如今藏龙卧虎，不说那位高高在上且脾气暴躁的兵家圣人，大骊礼部和钦天监的人都在，据说连县令都是大骊国师的得意门生，所以这位公子哥谨守父辈的叮嘱，到了小镇，夹起尾巴做人，真要闯了祸，家族连收尸也不会做。所以他绝不敢像在自家辖境内那么敢胡作非为，再说了，强抢民女什么的，他做起来虽然熟门熟路，可真的很无趣。

    这位自诩风流的年轻公子哥，估计打破脑袋也想不到，那个看上去傻乎乎的慵懒少女，竟然姓阮。

    他今天又跨过门槛，装着在一排排百宝架上挑选心仪物件，然后装着跟一位妇人砍价，最后笑着开口，跟那位像是小掌柜的青衣姑娘打招呼，轻轻扬起手中那块挺有眼缘的书案清供石，一手高，却是云头雨脚美人腰的模样，定价三十两银子，他问那少女能不能便宜一些，三十两银子实在太贵了些。

    实则对他来说，三十两黄金又算什么？

    阮秀头也没抬，淡然道：“不能。”

    男子故作潇洒地耸耸肩，说这石头他买了，最后他又挑了两样物件，又问那少女买了这么多东西，总该便宜一些吧？而且他要在小镇常住，肯定是回头客的，所以会经常光顾生意……总之啰里啰嗦一大堆，柜台那边阮秀听得心烦，还是不抬头，淡然道：“东西可以买，照着价格付钱便是，话少说。”

    那年轻公子哥不怒反笑，呦呵，看不出来，还是一匹性情贞烈的胭脂马？

    他还真不生气，只觉得激起了自己的求胜心，本来买山一事就板上钉钉了，他不过为财大气粗的家族露个脸画个押而已，为何不找点无伤大雅的乐子？于是他让妇人将三件东西打包后，离去之前，笑道：“这位姑娘，我明天还会来的。”

    阮秀终于抬起头，第一次正视他，“你以后别来了。”

    年轻男人饶有兴致地凝视少女，真是一张越看越喜欢的脸庞，绝对不是家里那些庸脂俗粉可以媲美的，所以他笑眯眯道：“为什么？”

    阮秀脸色平静，“这家铺子是我……朋友开的，所以我可以决定欢迎哪些客人进门，不欢迎哪些客人来碍眼。”

    那人指着自己鼻子，笑容更浓，“我碍眼？姑娘这话从何说起。”

    阮秀重新趴在柜台桌面上，挥挥手，“你走吧，我不想跟你这种人说话。”

    铺子外边站着一位身材高大的健硕男子，满脸不悦和戾气，冷冷看着那个不知好歹的市井少女。

    年轻男人笑着朝那名扈从摆摆手，眼神示意他别吓着自己的盘中餐，付完账后，他走向门口，不忘回头说道：“明天见啊。”

    阮秀叹了口气，站起身，绕过柜台，对那个刚刚跨出门槛后转身站定的家伙，说道：“我劝你以后多听听别人说话。”

    年轻男子看着少女那令人惊艳的婀娜身姿，感慨自己这趟真是艳福不浅。

    至于少女说了什么，他自然听见了，只是没有上心，更不会当真。

    那名扈从骤然间身体紧绷，头皮发麻，如芒在背，正要有所动作，只见青衣少女和自家公子一起冲向了骑龙巷对面的墙壁。

    他眼睁睁看着公子被那少女一手按住额头，最后整个人的头颅和后背，全部嵌入那堵墙壁之内。

    年轻公子哥瞬间失去知觉，七窍流血，他背后墙壁被砸裂出一张巨大蛛网。

    少女对着翻白眼晕死过去的男人说道：“以后要听劝，听明白了吗？嗯？还是不听？”

    少女高高抬起一腿，又是一脚迅猛踢出。

    本就可怜至极的公子哥连身躯带墙壁，一同凹陷下去，很是惨不忍睹。

    少女收回腿，转身走向铺子，对那个丝毫不敢动弹的高大扈从说道：“人抬走，记得修好墙壁。”

    那武夫第五境的扈从，咽了咽口水，连一句狠话都不敢说。

    他只是明面上的贴身护卫，真正的顶梁柱，是一位外姓家族供奉，如今还跟诸多势力一般无二，去了山里，跟随在大骊礼部侍郎和钦天监青乌先生屁股后头，既是与大骊朝廷联络感情，也是象征性查看那两座重金购得的山头。

    不是第五境武人烂大街，谁都可以欺负，而是这位马尾辫小姑娘的出手，太过恐怖了。

    要知道自家公子已经跻身第四楼，虽然比不得那些仙家府邸的真正天纵奇才，可只要最终能够跻身第五楼，那就等于拥有了雄踞一方的霸主资质，毕竟在武人辈出的大骊版图上，练气士比起武人，要吃香太多。所以那两座山头，会是自家公子的龙兴之地。

    这位第五境武人顾不得自报家门，震慑那个出手狠辣的少女，赶紧飞掠到巷子对面的墙下，片刻之后，眼眶通红的男人猛然转身，脸色铁青，大骂道：“小贱货！你知不知道自己打烂了我家公子的修行根本？！”

    阮秀已经走入铺子，闻言停步却没转身，只是扭头道：“知道啊，我故意不杀他留着受罪。”

    那武人几乎要疯了，这小丫头不会是个脑子坏掉的疯子吧？

    少女笑了笑，“你骂我，我不跟你计较，因为我会跟你家族算账。按照你们的套路，一般是打了小的跑来老的，所以你大可以喊那个家伙的长辈朋友之类，让他们过来找我的麻烦，放心，我就在这里等你们，什么地方都不去。如果你们既没人来寻仇，也没有人来道歉，事先说好，别当什么事情都没发生。”

    少女想了想，“如果你们的老祖宗或是家族援手，真能打败我，那我也会把我爹搬出来，没办法，我就只有这么一个亲人了。”

    少女突然莫名其妙就开心起来，笑得需要抿起嘴，才能不让自己显得那么开心。

    如今她好像多出了一个朋友，就是这间铺子的主人。

    那武人瞠目结舌看着少女的“诡谲”笑意，可以确定她真是疯子了。

    他不敢过多逗留，当务之急是尽可能留住自家公子的修为，背起自家公子，在骑龙巷飞奔而走，能够成为重要人物的贴身护卫，终究不是蠢人，他跑出一段距离后，立即对着某处大声吼道：“我家公子是丰城楚家，是你们大骊贵客！我家老祖更是摇铃山副宗主！”

    但是并无任何反应。

    这位武人瞬间透心凉，遍体生寒。

    那些潜伏暗处的大骊谍子，选择了见死不救！

    这绝对不合常理，不合规矩！

    武人如丧考妣，难道自家公子惹上了不能惹的硬钉子？可是老祖宗不是分明说过，除去先后两位圣人不提，世代盘踞小镇的那些地头蛇，并无太大成就吗？怎么小小一间铺子的少女，武力就如此惊人？

    远处，一个年轻人悄然坐在视野遮蔽的墙头，单手托着腮帮，打了个哈欠后，冷笑道：“真当我大骊怕你一个丰城楚家啊。”

    最后他收回视线，望向那间铺子，已经看不到柜台后的少女身影，轻声笑道：“不愧是传说中风雪庙第一好说话的姑娘。”

    他很快收起笑意，继续监视四周动静，一有风吹草动，他有权力调动附近所有大骊死士，出手杀人，可以不计代价和不计后果，无论对方是谁。

    但是同时他也猜得出来，这桩风波，不会到此为止，说不定就会牵扯到皇帝陛下，当然还有圣人阮邛。因为丰城楚家可以拿这件事上纲上线，大做文章，以形势舆论压迫大骊朝廷。大骊如今国势鼎盛，什么都不怕，唯独对于文人清议，一向极为重视，先帝与当今陛下皆是如此，十分厚待和容忍读书人。

    铺子内的几位妇人少女，一个个吓得战战兢兢，大气不敢喘。哪里想得到平时这么好脾气的秀秀姑娘，有这么一面？一出手就把人打了个半死不活？

    少女趴在柜台上，继续发呆。

    她突然想起什么，从柜台抽屉里拿出一块小石头，放在桌面，然后少女换了一个姿势，脸颊贴在桌面上，伸出手指轻轻拨动那颗石头，看着它滚来滚去。

    秀秀姑娘，秀色可餐。
------------

next：第九十五章 小庙

    龙泉县西南边境地带，落魄山山势宛如独树一帜，格外瞩目。

    一行人按照规矩，临近龙泉地界后，便选择脚踏实地地行走至此，并未御风凌空或是御剑飞掠，之后他们就要入山，去勘探那座出产斩龙台的龙脊山，那将是东宝瓶洲最大的一块磨剑石，哪怕一分为三，单独拎出一块，亦是如此。

    对于这这四位出身一洲兵家祖庭的修士而言，徒步行走山岳湖泽，算不得什么苦事，毕竟风雪庙兵家修士一向看重淬炼体魄，这本身就是在砥砺修为，既是修力也修心。

    当四人看到远处阮师的身影，纷纷加快脚步，主动向这位宗门前辈抱拳行礼。阮邛在风雪庙辈分算不得太高，但是口碑极好，开辟出那座蜚声南北的长距剑炉后，先后为同门铸剑十余把，结下了许多善缘和香火情。

    但真正让阮邛获得风雪庙六脉势力的共同认可，是一桩大风波，东宝瓶洲中部如日中天的水符王朝，大墨山庄是首屈一指的仙家府邸，有一位天资卓绝的年轻老祖，刚刚破境升为陆地剑仙，缺少一把趁手兵器，听闻阮邛铸剑之术登峰造极，亲自登门风雪庙绿水潭，向阮邛求剑，许诺了一份天大好处，可当时阮邛答应为一位文清峰晚辈铸剑，需要耗时数年，不管那名生性桀骜的剑仙如何劝说，阮邛只说是自己铸剑只讲先来后到，他可以为大墨山庄免费打造一把剑，但只能是当下那把剑出炉之后，为此年轻剑仙觉得阮邛是故意羞辱自己，一怒之下大打出手，阮邛当时只是九楼修士，拼着重伤也不曾低头，一战成名。

    大墨山庄为此付出了不可估量的巨大代价，除去那名陆地剑仙被拘押在风雪庙受罚五十年，短短六年之间，风雪庙六脉各有一人前去大墨山庄挑战，打得大墨山庄从水符王朝当之无愧的第一宗门，掉落到二流势力垫底，至今尚未缓过来。

    阮邛笑着向四人抱拳还礼，风雪庙并无繁文缛节，便是晚辈面对那些修为通天的老祖，礼仪仍是如此简单。

    阮邛与他们说过了一些龙脊山事宜，以及大骊朝廷在龙泉县的大略部署，然后随口问道：““神仙台魏晋，此次是不是与你们同行北上？”

    一位白衣负剑老人笑道：“宗门中途有传递过飞剑讯息，魏师伯这次确实北上了，只是却没有与我们同行，好像听说贺仙子此次作为道家代言人，进入了这座骊珠洞天，师伯这才愿意赶来凑热闹。如果没有意外的话，应该已经见过了那位南归宗门的贺仙子。”

    阮邛问道：“你们有人见过魏晋吗？”

    四人皆摇头，“不曾见过真容。”

    负剑老人问道：“阮师有此问，可是有事发生？”

    阮邛笑着摆手道：“只是好奇而已，如果我没有记错，魏晋堪堪四十岁，就已经坐稳十楼境界，神仙台也确实需要有人站出来，挑起刘老祖一脉的大梁。”

    五人一起行走在僻静山路上，负剑老人辈分和修为都最高，其余三人则该称呼魏晋为魏师伯祖，老人与阮师并肩而行，风雪庙六脉，以神仙台最为香火单薄，几乎沦为俗世王朝数代单传的惨淡景象，恰恰又是神仙台在三百年中对风雪庙贡献最大，所以阮师曾经所在的绿水潭，老剑修所在的大鲵沟，都对神仙台报以由衷的善意和期待，哪怕风雪庙内部六座山头各有争执，但是如果门风严谨、传承有序的神仙台彻底消逝，那么不管对风雪庙哪一脉，注定都不是好事。

    老人闻言后抚须笑道：“魏师伯天纵奇才，神龙见首不见尾，在江湖上也赢得偌大名声，说不定下次见面，就是咱们东宝瓶洲最年轻的上五楼的大修士了。”

    阮邛轻声道：“树大招风，越是如此，越要小心啊。”

    老剑师转头看着阮师凝重神色，顿时了然，沉声道：“等这次事了，返回风雪庙，我就会跟宗主建言，争取将魏师伯召回宗门，魏师伯不管如何，最好等到成功跻身上五楼之后，再行走江湖。”

    阮邛点头道：“这是老成之见，理当如此。相信魏晋在江湖闯荡多年，也见识过人心险恶，能够理解宗门的苦心。”

    老人欲言又止。

    阮邛摇头道：“最后魏晋愿不愿意回到风雪庙修行，那就是他自己的决定了。”

    阮邛突然望向小镇那边，抱拳道：“我家秀秀出了点事情，我得去看看，就不与诸位同行了。”

    负剑老人一挑眉头，已是满身杀气，“阮师，若是不方便出手，打声招呼，交由我来。谁敢欺负咱们秀秀，活腻歪了不是？！”

    阮邛会心一笑，道：“小事而已。”

    阮邛身形拔地而起，转瞬即逝。

    风雪庙其余三人有些诧异，不晓得老人何时如此喜爱宠溺阮秀了，要知道这十多年老人多仗剑远游，不曾待在山上，与那位小姑娘自然算不得如何熟悉，甚至远远不如他们三个。倒是大鲵沟秦老祖，确实很早就对小姑娘刮目相看。

    老剑师脸色平静，缓缓前行，只是脑海不断浮现出自己这一脉秦老祖的私下言语，“风雪庙的庙太小，容不下阮秀的。”

    草头铺子，阮邛走入铺子，犹豫了一下，没有直接用东宝瓶洲雅言与自己闺女说话，那些小镇妇人少女虽然为了店铺生意，暂时只学了一些与外乡人打交道的简单雅言，可保不齐会有意外，阮邛便用手指轻轻敲打柜台，少女茫然抬头，疑惑道：“爹，你怎么来了，今天不是不打铁吗？”

    阮邛柔声道：“出来说话。”

    父女二人离开铺子，走在行人稀少的骑龙巷，在阮邛出现后，那拨大骊谍子死士就自行悄然撤退。

    这是在对一位兵家圣人传达一种无声的敬意。

    阮邛对此暗暗点头，见微知著，心想大骊能够有今日强盛国力，不是没有理由的。

    阮秀有些恼火，问道：“是那个丰城楚家跑去跟你告状了？事先说好，我出手之前，警告过那人很多次了。”

    阮邛笑道：“多借给丰城楚家几个胆子，也不敢拿这种破烂事去烦爹，说不定很快就会有人携重礼登门道歉了。”

    阮秀嘀咕道：“那家伙看着就让人恶心，跟那个矮冬瓜一个德行，满身业障因果，只不过是厚薄之差而已，这种人跻身中五楼后，不知道要祸害多少人。如果不是担心给爹惹麻烦，我当时就一掌打死他了，省得将来造孽。”

    阮邛深呼吸一口气，额头渗出汗水，幸好自己方才驱使阴神出窍，气息将整条骑龙巷笼罩住，已经无人可以探查此地动静，要不然阮秀这席话落入有心人耳朵里，就真是遗祸无穷了。世间练气士百家争鸣，诸子百家中又以阴阳家，最擅长查探人之气运、业障，但那些本事能耐，几乎全是后天修行而成，所行神通，往往亦是顺势而为，如同抽丝剥茧，小心翼翼，佛家对此更是讳莫如深，只恨避之不及。唯有兵家，最是肆无忌惮，一副谁也敢杀、谁都可杀的架势，但这些都只是浮于表面的假象，可是自家这个闺女，不一样，很不一样。

    她自幼便能看穿人心，看到他们的七情六欲和因果报应，随着修为增加，她甚至能够直接斩断因果，一旦杀人，后果更是匪夷所思。

    这绝不是天生火神之体能够解释一切的。

    阮邛只知道在女儿的眼中，这个世界的色彩，与别人不一样。

    阮邛为此翻遍风雪庙珍藏典籍，只有一个失传已久的古老说法，勉强能够解释缘由。

    天生神灵，应运而生。

    所以阮邛之前才会主动要求贬谪到骊珠洞天，试图在阮秀真正成长起来之前，为她赢取六十年遮蔽天机的时间。
------------

next：第九十六章 山水有神怪

    铁符河水面上那些个已经化为人形、稳固魂魄的大妖，不知为何要仓皇撤退，朱河手中铜铃的铃声自然而然随之停歇，只是朱河担心那些光天化日就敢行走人间的大妖，使了什么障眼法，便让阿良前辈暂时不急于沿着河水南下，他高高提起那串篆文古朴的铜铃，在铁符河下游方向，不断反复跨越河面，大踏步四处游荡，以防妖魅隐匿在暗处伺机害人。

    于是陈平安一行人就这么收拾好行礼后，全部待在原地，眼睁睁看着朱河无头苍蝇似的乱窜李槐乐不可支，林守一是满怀好奇心，而朱鹿则觉得丢人现眼，恨不得把爹拽回来，别再这么瞎折腾给人笑话了，到底是脸皮子薄的少女。

    陈平安无意间发现阿良神色平静，丝毫没有像以往那般调侃打趣朱河，看到陈平安的视线后，阿良摘下酒葫芦，笑问道：“真不喝？”

    陈平安摇摇头，阿良便转头问林守一，“小子，遇见了不常见的妖怪唉，而且还不是一两个，很难得的，要不要喝口酒压压惊？”

    林守一不知为何，估计是生平第一次遇到传说中的妖物，大开眼界，少年心中有些意动，破天荒点头道：“喝一口试试看。”

    阿良斜瞥一眼陈平安，总算恢复玩世不恭的常态，“看看人家，有口福了，你小子就没躺着享福的命。”

    林守一接过银色小葫芦，仰头轻轻抿了一口，瞬间满脸通红，养尊处优的少年本就皮肤白皙，愈发红光满面，少年赶紧用手心捂住嘴巴，免得一口喷出来，喉咙滚烫，入肚后，五脏六腑都像是在燃烧，整个人都在打颤，第一次喝酒就来了个下马威，少年狼狈不堪，眼见着李槐捧腹大笑，自尊心极强的林守一咬咬牙，就要再喝一口，不曾想阿良已经伸手拿回小葫芦，一手轻轻按住少年肩膀，笑眯眯道：“喝酒不贪杯才有乐趣，以后每天给你喝一口，保证这世上从此多出一个逍遥忘忧人。”

    李槐人小鬼精，笑着拆穿阿良，“不舍得给林守一多喝就直说。”

    阿良从林守一肩膀上缩回手，叹了口气，“能不心疼嘛，我这酒来历极大，价格极贵，关键是有价无市。林守一是撞了大运。”

    李槐试探性问道：“给我喝一口？”

    阿良赶紧在腰间别好酒葫芦，“年纪太小，气府尚未成形，不宜喝烈酒，否则会坏了你的根骨。”

    李槐愣了愣，随即跳脚破口大骂：“阿良！干你娘！我前年的年夜饭，就能用筷子偷偷蘸酒喝了，那可是咱们小镇最厉害的烧酒，连我爹都说我酒量随他，谁不知道我爹是小镇喝酒最凶的汉子，再说了，我从去年春开始，每个月就要被我爹丢在药酒桶里泡着，低头就能喝到酒，你现在跟我说这个？”

    阿良哎呦一声，随即瞥了眼气势汹汹的小屁孩，心想难怪，小小年纪就能够跟上大队伍的脚步，脚底板连个水泡也没长过，身体明显比林守一还要强上不少，应该就是这药酒打熬体魄的缘故了。

    阿良头一回饶有兴致地仔细打量起李槐，不看不知道，一看吓一跳，竟然是被人以相当不俗的武学神通，故意遮掩了孩子的体内气象，如今阿良想要看，自然便没了那些迷障，于是在斗笠汉子的视野中，便呈现出一副玄妙另类的山水形势图，去其皮肉，只看全身窍穴景象和气血游走，隐约有淡紫气升腾，山脉雄健且牢固，水势汹涌且平稳，最终在一座窍穴内百川汇流，气蒸大泽，不容小觑。

    阿良啧啧称奇道：“真没想到我路边随便认了个老丈人，还挺不一般啊，李槐，你爹姓甚名甚，说不定我这边的朋友认得。”

    李槐突然沉默下来，病恹恹独自走远，不愿意搭理阿良。

    林守一低声解释道：“李槐他爹名叫李二，是小镇出了名的酒鬼混子，一年到头不务正业，以前在学塾，李槐没少因为他爹被人嘲笑，一开始李槐也跟人吵架，好像还打过几次，后来估摸着是觉得他爹是真没出息，久而久之，就无所谓了。”

    阿良忍俊不禁道：“小崽子身在福中不知福啊。”

    言者无意，听者有心，林守一默默记下。

    约莫半个时辰后，朱河终于返回，笑道：“方圆十里之内，铜铃没有异样，咱们可以动身了。”

    李宝瓶递过去一只水壶，笑道：“朱叔叔辛苦了。”

    朱河接过水壶，大大咧咧回复一句，“小姐，这本就是分内事。”

    朱鹿看在眼中，眼神晦暗，转过头，望向铁符河的瀑布大水，她咬着嘴唇，默不作声。

    少女心思情怀，如山风如水雾，不可捉摸。

    陈平安目不转睛看着朱河手中那只震妖铃。

    除了宁姑娘那把能够自己飞来飞去的剑，朱河手中的铜铃，是陈平安近距离亲眼见过的第二样法宝，所以就看得格外专注。

    朱河不是小气人，大大方方就将那只铜铃交给少年，解释道：“是出门前老祖宗赏赐下来的宝贝，老祖宗说此物在仙家法宝当中，品秩算不得高，只是每有幻化人形的妖魅精怪靠近，铃铛便会无风自响，震荡出阵阵清音，使人不受魅惑，也有警戒提醒的功效，老祖宗还笑称那阵阵铃声，有凝神清心之效，如果胆子大一点的修行之人，大可以与妖物相邻而居，借此铃声修养心性，当然，前提是做邻居的妖物无伤人之心，同时还要能够承受铃声的不断袭扰，如此修为高、脾气好的妖物不好找，故而老祖宗也只是权当笑谈而已。”

    陈平安小心翼翼抓住铜铃把手，朱河牵马与之并肩而行，“大者为钟，小者为铃，如果是仙家器物，大多有辟邪护宅的作用。寻常百姓家宅喜欢在檐下悬挂风铃，自然更多是装饰，如果是专程从寺庙道观请来，经由高功大德之士的经文护持，应该确实可以遮挡煞气，蓄留福荫。”

    朱河看到少年轻轻摇晃铜铃，朱河哈哈大笑道：“若无妖物靠近，里边两颗铃铛不易撼动，所以就不会有铃声传出了，要不然白白让主人整天疑神疑鬼，岂不是遭了大罪？”

    陈平安也想通其中关节，正要把珍贵异常的震妖铃交还给朱河，发现袖子一扯，红棉袄小姑娘满脸期待神色，看到朱河笑着点头后，就交给李宝瓶，她双手抓住铜铃，翻来倒去，仔细研究起来，时不时伸手使劲扯动里头的铃铛，看得陈平安一阵心慌，不断提醒她小心些，别扯坏了。

    陈平安一边盯着小姑娘，一边好奇问道：“朱叔叔，河上那些妖精不会害人吗？我们大骊有很多这样的奇怪存在吗？”

    朱河不是信口开河之辈，只拣选自己从老祖宗那边亲口听来的话说，娓娓道来，“咱们东宝瓶洲幅员辽阔，仅是人口超过一千万户的庞大王朝，就多达十数个，名山大川更是不计其数，种种妙不可言的因缘际会之下，那些个山鬼精魅妖怪，侥幸化形，踏足修行之路，不常见，却也算不得如何罕见。”

    “咱们老祖宗便说过，跟我们小镇不一样，外边天地，只要不是太过偏远闭塞的东宝瓶洲人氏，对此多有所耳闻，虽然未必人人亲眼目睹，但是往往听多了稗官野史、神仙志怪，以至于很多市井百姓坚信，在那些人迹罕至的深山古寺里，往往住着妖艳动人的小狐娘子，等着进京赶考的穷书生。又或是哪里有妖精作祟害人，只需书信一封给龙虎山，必有天师府的真人腾云驾鹤而至，为当地百姓斩妖除魔。以至于有井水处必有稚童口口传颂：有妖魔鬼怪作祟处，必有天师府真人。”

    “总之，我们这一路行去，不要大惊小怪就是，当然，更要小心。老祖宗说妖物一旦化作人形，而不是用一些障眼法迷惑人眼的话，那么便等同于半个修行之人了，大骊朝廷对此乐见其成，非但不会打压排挤，反而破例准许在版图上开山立派，只需要在礼部挂案即可，不过碍于某些约定俗成的规矩，大骊朝堂尚未吸纳妖魅精怪跻身其中，倒是边境沙场，传言多有妖修为大骊建功立业，平时日常起居，风俗人情，看上去跟人已无差异。”

    朱河这番话说得通俗易懂，趣味十足。

    陈平安听得津津有味，李槐林守一更是竖起耳朵，一个字也不肯错过。

    唯有走在最前头的阿良，戴着斗笠牵着毛驴，手心轻轻拍打刀柄，轻轻哼着走调的异乡小曲儿。

    走在队伍最后的少女朱鹿，更是心不在焉，好似离乡越远，思乡越浓。

    在这支南下队伍走出一个时辰后，在龙须溪和铁符河交界处的那条瀑布，一位中年妇人模样身段的女子出现在石崖上，坐在边缘，一头鸦青色青丝竟然长达五六丈，从头到脚，再延伸到溪水当中，妇人低头死死盯着铁符河瀑布下的汹涌河水，眼神炙热，充满垂涎。妇人面貌模糊，变幻不定，似乎尚未真正定型，在等待某种契机的出现。

    河婆，河神，一字之差，无论是地位还是修为，皆是云泥之别。

    她最多便只能游曳至此，再往下就是过界了，就像人间郡县官员不可擅离职守，为王朝镇守一地风水的山水正神，更是如此，否则就会引发洪水泛滥种种灾祸异象。如今成神在即，她当然不会在这个紧要关头自找麻烦，她曾偷偷沿着溪水往上游深山潜伏而去，结果只是被大骊朝廷一位临水观瀑的青乌先生，随意瞧了一眼，就只觉得头皮炸裂，在那之后，她再不敢小觑小镇之外的高人异士。

    这一路她尾随至此，可不是什么包藏祸心，只是听命于圣人阮师，小心盯着那位不知深浅的斗笠汉子，以防纰漏。她这些日夜观察，做得兢兢业业，不敢有丝毫懈怠。委实是那位手镯化为火龙的小姑娘，让妇人吓得不轻，尤其是让自己窃据河婆之位的那位大仙杨老头，泄露天机后，她更怕有朝一日沦为小姑娘的证道契机，简直是怕到了骨子里。

    成为河婆之后，体会到了种种妙不可言的神通，比如每天都在返老还颜，比如水中游曳就会通体舒泰，又比如每逢大雨天气，她就能够通过地下水或是天井雨幕，借此查看小镇风景。更比如这些天的不断辛苦收集，在河底很是搜罗到了几件好东西，全部被她收入囊中，其中一枚碧玉戒指，就被她戴在手上，一有空就拿出来欣赏，如那市井妇人佩戴黄金饰物，沾沾自喜。

    越是如此高于俗人一头，她骨子里深处，越是惧怕杨老头和姓阮的小姑娘，因为这两人，仿佛随手就能毁掉她现在的一切。

    她收敛杂乱思绪，环顾四周，如今骊珠洞天与大骊疆土接壤混淆，灵气充沛，成为七十二福地一般的修行好地方，使得外方许多飞禽走兽开始向这里流窜，尤其是那些灵智开窍的山野精怪，更是凭借本能，希冀着捷足先登，早早占据一方风水宝地。看护着一地风水，本就是山神河神的职责所在，她如今便已经在龙须溪当中收了几条长出龙须的锦鲤做喽啰，平时出行，众多水族灵物，充当扈从跟随护驾，让她很是满足。

    所以她虽然暂时无法游入铁符河，但是必须守住瀑布这道关隘，争取收取一些天经地义的过路钱，关于这件事，杨老头是点头认可的，于是她就格外有底气，名正言顺地在此耀武扬威。只不过内心深处，生性谨小慎微的妇人依然有些惴惴不安，生怕外边的过江龙打个喷嚏，就能淹死她这龙须溪小小河婆。

    总算来了。

    再也不是毙命之时老妪模样的长发妇人，眯起眼，望向铁符河对岸做贼似的五人。

    之前她躲在瀑布顶部的溪水当中，举目远眺，那五人来势汹汹，架子摆得很足，一个比一个像神仙中人，差点就要让她生出退避三舍的怯懦念头。只是后来那五个妖气轻重不一的家伙，不知为何吓得屁滚尿流撒腿就跑，如此一来，不管那五位为何而退，总之她就再无惧意了，心中反而只剩下讥讽和洋洋得意，自己如今不但正儿八经为圣人阮师做事，为他的铸剑用水加重阴寒之气，还是曾被秀秀姑娘那条火龙踩在脚底下、还能劫后余生的角色！

    这难道还不值得骄傲？

    一想到这些，她便心稳许多，竭力让自己面容平淡，装模作样坐在大石崖畔，冷冷望着溪水对岸的五位妖物，有白发苍苍的老人身披蓑衣，如人间喜好游山玩水的年迈儒士。有衣裳艳丽惹眼的丰满女子，一双勾人心魄的桃花眼眸。有稚童小儿手持紫竹手杖，眉眼深沉。还有一双妖气最重的年轻少年少女，眼神怯生生，躲在蓑衣老人身后，不敢正眼看人。

    妖精鬼怪，遇人避让，遇神跪拜。

    相传这曾是上古时代流传下来的不成文规矩，只是如今神仙神仙，神祇除了那些被供奉起来的金身泥塑，一尊尊死气沉沉，早已难见真身，倒是市井巷弄的黄口小儿，也晓得山上住着许多仙人。不过朝廷以玉书金字敕封的山水正神，哪怕不是高高在上的五岳正神，在种类驳杂的山鬼精魅眼中，除非修为境界高出对方太多，否则哪怕只是小河河婆、小山土地，依旧是高不可攀、不容得罪的“官家贵人”。

    “小的们本是大骊边境的山林野修，路过宝地，拜见河神大人。”

    蓑衣老人毕恭毕敬作揖而拜，起身后脸色庄重，“自古名山待圣人，我们来历不正，当然不敢以圣人自居，只有由衷的仰慕之心，如今洞天大开，咱们只是想着能够在圣人脚下，老老实实修行，日后大道有成，必然反哺此方天地，还希望河神大人今日能够借道一行。”

    山林野修，算是这些妖物的常见自称，一般都是遇上了修行高人后的自谦语气。

    河婆妇人直截了当道：“一人一样见面礼，交出来后，如果我觉得不错，便亲自带你们去小镇西边的大山。”

    蓑衣老人愣了愣，似乎没有想到这位河神如此爽快坦诚。

    那持杖稚童愤懑出声道：“她如今神位不过是最低贱的河婆而已，咱们客气尊称一声河神，已是给她天大颜面，竟然还敢当面索贿，就不怕事后大骊朝廷一纸令下，就让她打回原形，孤魂野鬼也做不得吗？！”

    妇人可是小镇杏花巷的骂街高手，加上大仙杨老头给她透过一些底，哪里会怕这些恐吓，反而清晰看出了那帮人的色厉内荏，便底气更足，抬手一挥，冷笑道：“那就速速滚远，胆敢靠近龙须溪百丈之内，就算你们忤逆大骊川流正统，到时候看谁吃不了兜着走！”

    稚童勃然大怒，正要出言反驳，被慈眉善目的蓑衣老人猛然转头，一个凶狠噬人的眼神狠狠瞪住，稚童模样的山精顿时噤若寒蝉。

    一炷香过后，五位“山林野修”沿着溪水向龙泉县行去。

    半身露出龙须溪水的妇人，身上则多出了五件东西，其中就有那根原本稚童手持的紫竹小杖，晶莹剔透，灵气充沛。

    在溪水中游曳的妇人暗自窃喜之余，突然有些莫名伤感。

    如果自己孙子还在杏花巷住着就好了，这些好东西都能一股脑儿送给他。

    只是不知牛年马月才能见着孙子了，而且听说修行路上，一不留神就误入歧路，身死道消，真正成长起来的幸运儿，凤毛麟角。

    一想到这个，河婆便有些兴致不高，身形一闪而逝，潜入河底，在水中悄然呜咽起来。
------------

next：第九十七章 拜山头

    一行人沿着龙须溪和铁符河缓缓南下，可日行六十余里，李宝瓶和李槐都是脚力异于常人的孩子，林守一虽然草鞋都磨破了两双，也是富家子弟，可不愿在两个李姓孩子面前叫苦认输，硬是熬着，加上陈平安教了他用草药敷脚的土法子，终究是咬牙熬过来了，队伍里有白驴和马匹帮着驮物，所以走得并不算太艰难。

    陈平安心底很佩服李宝瓶这三个孩子，于是游学两个字，以及读书人这个称呼，在草鞋少年心目中，分量愈发加重。

    龙泉县隶属于大骊永嘉郡，在很久之前，东宝瓶洲所有王朝一起下诏，天下州郡县如果带龙字，皆需要避讳修改，换上其它字顶替，如今龙泉县估计是沾了骊珠洞天的光，才得以破例。

    破碎洞天落地生根之处，比起早先悬空位置，已经往南偏移了很多，距离大骊南部边境的野夫关，若是车马走官道驿路，其实不过月余时间。

    朱河在福禄街李家，应该翻阅过许多私家藏书，知晓许多门外事，陈平安有事没事就跟朱河讨教，反之朱河也乐意跟少年请教一下入山下水的规矩门道，阿良不知为何，喝酒的次数多了，说话的时候少了，林守一自从喝过银葫芦里的烈酒后，跟阿良走得很近，经常跟他问东问西，同时有成为小酒鬼的趋势。

    李宝瓶小书箱里，摆着一部大骊朝廷颁布的彩绘版郡县堪舆图册，照理只有一州刺史衙署才有资格存档秘藏。按照图册显示，他们很快就要攀爬一条名为棋墩山的山脉，山路长达三百余里，途径永嘉、白云在内四郡。

    一行人在山脚稍作休息，李槐看着宽不过骑龙巷的小路，呆若木鸡，震惊之后转头怒骂道：“阿良！这就是你说的驿路，大骊朝廷特建的官马大道？！鸡肠子一样细的破路，也算官道？”

    驿路，俗称官马大道，将一座王朝疆土的全部郡县相互衔接，驿路就像是人体经脉，一旦阻塞，就会气血不通，放在国家身上，就是政令不行。

    阿良坐在路旁一块朽木墩子上，仰头喝过酒后，笑哈哈道：“驿路也分等级，大骊南部边境的野夫关，有三条驿路通往北方，棋墩山驿路属于最小的一条，多用来运用瓷器、茶叶和精盐，以前人来人往很热闹，如今一座骊珠洞天这么往地上一摔，阻断了原本南北通道，这条驿路就暂时弃而不用了，断了好些人的财路，许多货物都停滞在棋墩山山脉南麓的一座水运码头那边，叫红烛镇，嗯，那里的花船，大多是两三人的小船，一到晚上，灯火通明，船上的姐儿俏得很，坐在船头或是船尾，一条条白花花大腿，就那么故意露给你看，在两岸酒铺子点一壶酒一碟花生米，不花钱就能白看一宿。”

    婢女朱鹿赶紧弯腰捂住自家小姐的耳朵，以免被这个登徒子的浪荡言语污了耳朵，她怒容道：“我们不在那红烛镇过夜！”

    阿良用酒葫芦指了指一旁的陈平安，笑嘻嘻道：“过不过夜，得问他，他才是管咱们钱袋子的财神爷。”

    朱鹿眼神凌厉，杀机重重，像是陈平安敢点头她就敢杀人。

    陈平安想了想，脸色认真道：“肯定要在小镇停留，添置补充一些必须物品，至于要不要在那边过夜，得看那边客栈旅舍收钱贵不贵，我们人多，如果价格不公道，就只能算了。”

    朱鹿脸色阴沉，咄咄逼人，“如果便宜，咱们就要住在那种烟花脂粉的肮脏地方？陈平安！你有没有想过，我家小姐，和林守一都算是半个儒家子弟，还是山崖书院的学子，怎么可以与那些伤风败俗的女人毗邻而居，哪怕看不到那些作呕画面，总会听到一些不堪入耳靡靡之音！”

    陈平安硬着头皮答道：“到了小镇再说。”

    朱鹿火冒三丈，朱河拦住女儿，“就按照平安说的，不要妄下定论，到了那边再看，我们又不是一定要在红烛镇过夜。”

    朱鹿伸手指着陈平安，犹然气咻咻道：“幸好你不是读书人，要不然那些圣贤书真是因你蒙羞！”

    陈平安这一路上跟李宝瓶和朱河识字认字，看着大义凛然的朱鹿，少年顿时有些败下阵来。

    罪魁祸首阿良在一旁幸灾乐祸。

    朱鹿最后斜瞥一眼少年头上的碧玉簪子，觉得真是碍眼，讥笑道：“沐猴而冠！”

    朱河轻喝道：“朱鹿！”

    李宝瓶和林守一同时皱了皱眉头。

    阿良懒洋洋喝了口酒，再好的酒，一直喝下去也没甚滋味，转念想到红烛镇的新酿杏花春，就有些期待，想着怎么从陈平安那边骗点银子来过过嘴瘾。

    陈平安欲言又止，终于还是没有开口，默默带着他们登山。

    只是入山之前，草鞋少年依旧向以往那般，拜了三拜。

    这是姚老头传下来的老规矩，但是从不跟陈平安解释缘由，陈平安这些年始终照做不误。

    阿良对此嗤之以鼻，就连陈平安不要他随便坐树墩子，也从不理会，累了就一屁股坐下，就像现在那样大大咧咧。

    陈平安不是那种喜欢把自己的喜好强加于人的人，劝过两次后，阿良一直我行我素，也就不再劝阻，而且一路行来也无不妥，陈平安就更不会多嘴。

    接下来这一段漫长山路，虽是多青石铺就的驿路，却颇为难行。

    暮春时节，山野草木却毫无迟暮之气，草木深深，花树怒放，生机勃勃，像是今年的春天尤为漫长，迟迟不愿散场。

    山路弯曲，盘旋而上，一行人不管大小，腿上都裹了棉布行缠，用以增长脚力，人手持有一根木杖，当然还有陈平安亲手编制的草鞋，就连行囊备有好几双结实靴子的朱河朱鹿父女，也不例外。

    朱鹿一开始死活不肯，嫌弃太过丑陋寒酸，后来入山遇上雨天，山路泥泞不堪，经常脚底打滑，朱鹿是登堂入室的武人，虽然不至于险象环生，却也踉跄难堪，最后不得不从她爹手中拿过草鞋，默默换上，李槐偷着乐呵，被恼羞成怒的少女一脚使劲踩在烂泥里，二境巅峰的武人，有意为之的一脚踩踏，自然势大力沉，当场溅得李槐半身泥浆。

    孩子家境贫寒，本就没带几身换洗衣物，立即戳中了伤心处，哭得稀里哗啦，气喘吁吁的林守一不愿掺和这摊子烂事，停步在旁休息的时候翻白眼。朱河是性子淳朴的人，哪怕已是五境武人，依然耐着性子跟孩子赔礼道歉，答应出了山进了市镇，一定给他买一整套崭新衣物，可孩子在意之事，就是自家穷苦自己可怜，一看到那婢女脾气这么坏，偏偏身边还跟着一个有钱的爹，孩子只觉得自己被伤口撒盐，哭得更加撕心裂肺，双脚使劲踩着泥泞地面，很快就跟一只小泥猴似的，一来二去，所有人都心烦气躁起来，陈平安上去劝说，李槐不愿听，陈平安很快就被连累得一身黄泥，所幸陈平安什么苦头灾殃没受过，倒是没急眼，只是有点无奈。

    朱鹿趁机煽风点火，看吧，好心没好报，陈平安，你赶紧把这种没心没肺的东西丢下得了。

    李槐哭得更加厉害。

    李宝瓶大声呵斥也不管用。

    陈平安思来想去，最后只得试探性问道：“李槐，我回头帮你做一只小竹箱，咋样？”

    那孩子立马止住哭声，胡乱抹去眼泪鼻涕，认真问道：“多大的？”

    陈平安回答道：“不能太大，你个子小，背起来不能觉着重才行，要是不答应，就当我没说，你继续哭，然后我们继续赶路，跟不跟上随你。”

    李槐咧嘴笑道：“小可以，一定要做得漂亮点！最少也要跟李宝瓶那只书箱一样好看！”

    朱鹿啧啧道：“上梁不正下梁歪，小小年纪，就学会坑蒙拐骗了，爹娘品行如何，不看便知。真是好正的家风！”

    竹箱即将到手的李槐挤眉弄眼，差点把朱鹿气得七窍生烟。

    陈平安转头对林守一说道：“给你也做一只书箱？”

    他笑了笑，“反正也是随手顺便的。”

    林守一刚要摇头拒绝，听到后边那句话后，犹豫了一下，点点头。

    棋墩山的山巅景象极其奇异，像是一个小镇常见的巨大晒谷场，地面平整，搁在这里，便如仙人以刀剑削去高耸山头一般。

    孩子们雀跃不已，就连朱河放眼远眺北方，也颇为心旷神怡，恨不得长啸几声。

    陈平安是见惯山头的人，尤其是最后那趟进山，一座座山头一步步走过，此刻反而显得相对神色从容。

    今夜要在山顶过夜，朱河朱鹿开始搭帐篷，李槐和林守一跑去拾取易燃的柴禾，陈平安和李宝瓶则用石子搭灶煮饭，如今几个行囊里的米粮和干菜都已吃得差不多，确实是要寻一处闹市补给，陈平安为此一路上见到药材，就摘下放入背篓，因为翻山越岭熟门熟路，腿脚利索，哪怕需要绕路攀援山崖，一样很快就可以跟上队伍，不会耽误行程，如今已经攒下小半背篓晒干的珍稀草药，争取能够少花一点积蓄是一点。

    就着几碟子腌渍咸菜吃完米饭，阿良起头造反，带着李槐一起用筷子敲着白碗，嚷着要吃肉要吃肉。

    陈平安点点头，说今夜去做几个陷阱套子，看明早能不能逮几只山跳野鸡来开开荤。

    蛇有蛇道鼠有鼠路，山上走兽皆是如此，陈平安对此并不陌生，只要仔细观察，很容易就发现一些山林野兽觅食喝水的线路，而且以树木石块做成的小巧陷阱，并不复杂，熟能生巧。黄昏里，彩霞满天，在少年独自离开山顶大坪去碰运气后，没过多久，只见山巅四周彩云聚散不定，速度极快，如顽劣孩童的变脸，而众人丝毫不觉得山风迅猛，与此同时，原本堂堂正正清清爽爽的山河景象，给有心人带来一种蒙上雾霾的阴森感觉。

    这让朱河立即心情沉重起来，尽量不惊扰三个聚头背诵书籍的求学蒙童，也不去跟独自坐在崖畔发呆的女儿打招呼，朱河想了想，来到无人处，掏出怀中一本泛黄古籍，翻到中间“开山”一页，手指停在“撮壤诀”附近，仔细浏览那些细微如蝇头的鲜红文字，翻过一页，则是两幅图案，一幅绘有小山模样，只是底部山根如竹笋盘结，旁边空白处注解为“太山符”，一幅为双手结印之玄奇手势。

    朱河神情凝重，断断续续默念，不断加深印象，“取山之东、南之土各一抔，捻嶽字最佳，捻山字亦可”，“焚礼敬山神符一张，脚踏魁罡二字，呵气一口，可向山神、土地借取一山，气与地连……”

    合上古籍，小心翼翼放回怀中，朱河又从袖中一摞黄色符箓当中，抽出一张黄纸，开始依循书上记载去石坪东方和南方各抓取一把土壤，捻出一个古体的岳字，即嶽，上山下狱。朱河正要搓燃手中那张李氏老祖赠送的黄符，突然吓了一大跳，原来阿良不知何时蹲在了他旁边，后者提着酒壶，笑呵呵道：“你手上那张寻常材质的入山箓，下笔之人的画符手法，还是不错的，但是符箓一道，一步差不得，纸张材质如人之根骨一般重要，所以它可承受不起‘嶽’字的重量，所以我劝你写个岳字就可以了，省得请神没成，还惹恼了山神。”

    朱河毕竟是第一次接触到传说中的山精神怪，有些紧张，轻声道：“阿良前辈，这棋墩山真有那土地或是山神盘踞？那为何还有这么重的阴煞气息？”

    阿良悠悠然喝了口酒，嗤笑道：“谁跟你说山神土地，一定是性情良善之辈？”

    朱河满脸错愕，“不然？”

    阿良嘿嘿道：“我就是随口一说，天晓得这里的主人家，待客的脾气是好是坏。”

    朱河猛然惊醒道：“不好，陈平安一个人不在山顶！”

    阿良点了点头。

    朱河火急火燎道：“阿良前辈，你去找陈平安，我继续完成这道撮壤成山诀，如何？我朱河只是五境武人，对付世俗高手自信还有一搏之力，可是对付那些古怪东西，真是心里没底啊。”

    阿良笑着起身，大摇大摆离去，轻飘飘撂下一句话，“那你自己小心啊。”
------------

next：第九十八章 山神作祟

    朱河按部就班完成那道撮壤成山诀，捻出岳字，烧掉黄符，踏罡呵气，最后双指并拢，对着地面上的土符轻声念道：“奉三山九侯先生律令，敕！”

    朱河始终保持这个手指朝地的姿势，神色越来越尴尬，因为地面上的那个岳字纹丝不动，朱河额头渗出汗水，几个保证符箓灵验的紧要处，例如烧符之时，从自身何处气府注入黄符多少真气，等等，朱河自问都没有纰漏，照理来说应该大功告成才对。

    按照泛黄古籍所记载的解释，开山篇中所谓的捻土造山，并非实实在在出现一座山峰，这与走水篇中名副其实的吐唾横江符，大不相同，撮壤之后，这个岳字将会成为一地山神、土地走出栖息洞府的桥梁，只要不是太蛮横的非分之想，那么被邀请出山的神祇，多半会答应烧符之人的要求，因为那张黄纸符箓本身，就类似一份登门礼，坐镇一方山水的神灵只要出现，就意味着他们愿意开门迎客。

    可是朱河觉得自己这次临时抱佛脚的请神仪式，多半是黄了。

    但是当朱河循着一阵巨大的声响，向山脊望去，树木依次轰然倒塌，明显是有庞然大物在飞快登山，矛头直指山顶石坪众人，以排山倒海之势迅猛向上。

    响彻山脉的惊人动静，使得朱鹿李宝瓶他们迅速向朱河靠拢，朱河转头沉声道：“退回去！你们站在石坪中间，不要轻举妄动，接下来不管发生什么，都不要随意靠近我这边。”

    年纪最小的李槐脸色苍白，扯了扯身旁李宝瓶的袖子，“不会是吃人的妖怪吧？要不然就是山神作祟？之前陈平安告诉阿良别随便乱坐树墩子，说那是山神老爷的交椅，坐不得……”

    李宝瓶双臂环胸，胸有成竹道：“我们不要自乱阵脚，就算朱叔叔挡不住那东西，小师叔和阿良很快就会赶来帮忙。”

    只是红棉袄小姑娘的白皙双手，手背青筋绽起，显然并没有她表面那么镇定自若。

    林守一反而是最镇静的一个，眼神中隐藏着期待。

    朱鹿望向父亲的背影，她其实比李槐更加担心。

    朱河突然低下头，看到一个身高不及腰部的矮小老头，邋里邋遢的白发白须，手持一根幽绿竹鞭拐杖，正在狠狠打着朱河的小腿，像是撒泼泄愤的无赖。等到朱河低头后，老翁与他对视片刻，悻悻然收回手，退后数步，沙哑开口：“晓不晓得东宝瓶洲大雅言？”

    朱河怔怔点头。

    老翁又问：“那么大骊官话呢？”

    朱河再次点头，尚未从震惊之中回过神。

    老翁手持绿杖跳起身就给了朱河肩头一拐杖，落地后，朱河没什么感觉，老翁自己一个踉跄差点摔倒，赶紧一手扶住老腰，气急败坏地用大骊官话痛骂道：“干你祖宗十八代！屁大本事没有，害人的能耐算你最厉害，老子像缩头老鼠一样，可怜兮兮躲了畜生几百年了，本以为就这么苟延残喘下去，好不容易能够等到这一次千载难逢的翻身机会，只等大骊朝廷这拨大肆敕封山水正神的东风，老子就能媳妇熬成婆，总算可以从土地升为山神，以后再也不用受这窝囊气，哪怕依然斗不过它们，好歹能勉强果腹不是……”

    老翁一边骂骂咧咧，一边抬臂擦拭眼泪，悲愤欲绝，最后用竹杖使劲敲打地面，“有本事自己去跟那些畜生厮杀啊，干你祖宗十八代的王八蛋玩意儿！用一张破符，非要把老子揪出来，想躲都没法躲，结果要跟你们这帮挨千刀的家伙一起葬身蛇腹，殉情啊？老子是二八娇娘，还是徐娘半老咋的，你难道就好我这一口啊？！啊？！大声告诉我！干你祖宗……”

    绿竹老翁像是被人掐住了脖子，一个字都说不出口。

    朱河转头望去，毛骨悚然。

    一颗硕大如水缸的漆黑头颅，从山脊那边缓缓抬起，最后完整出现在山巅石坪的众人视野当中。

    一双银色眼眸，一条猩红舌头长如大木，飞快摇动，呲呲作响。

    这条大到惊世骇俗的黑蛇，半截身躯缓缓挪到石坪上，头背皆有对称大鳞，通体漆黑如墨，在夕阳映照下熠熠生辉。

    虽是畜生，它的眼神却极其似人，促狭玩味地望着须发打结乱如麻的白衣老翁，好像在说猫抓耗子这么多年，总算逮着你了。

    老翁仿佛认命了，一屁股坐地上，丢了那根相依为命的竹杖，捶胸蹬腿，嚎啕大哭，“造孽啊，堂堂一山土地老爷，到头来被畜生欺负到这般田地，这日子么得法子过了啊……”

    黑蛇缓缓直起腰身抬升头颅，腹部露出一双小爪，如世俗王朝藩王蟒服上所绣图案的四趾，而非帝王龙袍上的那种五趾。

    可这一趾之差，对山巅众人和自称土地的矮小老翁而言，实在可以忽略不计。

    老翁眼珠子突然滴溜溜乱转，猛然站起身，扬起脑袋望向那条黑蛇，惊喜道：“这武人莽夫的皮肉肯定糙得很，你是为了身后那些皮滑肉嫩的小娃娃们来的，因为他们一个比一个灵气十足，对不对？”

    老翁越说越兴奋，唾沫四溅，大笑道：“吃吃吃，尽管吃，吃饱了，你就终于能够成就墨蛟真身，再也不用惦记我这点臭皮囊，到时候小老儿当我的大骊棋墩山山神，你争取做你的走江龙，在走江之前，这儿依旧你是山大王，一样能够在小老儿头顶上拉屎撒尿，所以你现在吃我没意义嘛，吃了虽然是能增长丁点儿修为，可小老儿我毕竟是土地神祇之一，对你将来走江入海为龙，也是一个大坎，因为那些江河湖水的正神们，一定会同仇敌忾，一路上不断给你下绊子的……”

    黑蛇那张大嘴轻轻裂出一条缝隙，如人讥讽而笑，它的头颅往老翁身后点了点。

    老翁再次呆若木鸡，一屁股颓然坐地，这次没有老泪纵横，只是干嚎道：“一公一母，皆要证道，你吃了那帮灵丹妙药似的儒家小娃儿，为走江化龙奠定基础，你那婆娘吃了我，以便顺利篡位成为下任山神，好算计好算计，我认栽，小老儿认栽了……”

    衣衫褴褛的白衣老翁眼神痴呆，呢喃道：“大道难料，不过如此。”

    极其久远的岁月里，曾有两位得道仙人联袂腾云驾雾，兴致偶起，降落此山，弈棋于山巅，一人拂袖即削去山头，手指作剑，划出纵横十九道，一人捏土灵为黑棋，抓云根为白棋。双方手谈月余，双方每落一子，棋子即生根化为天地生灵，黑棋为黑蛇，白棋为白蟒，盘踞于山巅棋盘之上纹丝不动，白子被吃，便被附近黑蛇吞食入腹，反之亦然。

    那盘棋局势均力敌，两位术法通天的仙人，不等胜负水落石出，便尽兴离去，离山之时，山顶还剩下一百多条黑白蛇蟒，在之后漫长的岁月里，黑蛇白蟒相互厮杀，疯狂吞噬对方，最终只存活下来一条有望蜕皮为墨蛟的黑蛇，和一条腰间生出飞翅的灵性白蟒，不知为何，这双黑白蛇蟒，竟然不再捉对厮杀，而是成为了一双伴侣。

    它们极其狡猾奸诈，一开始对于能够造成威胁的修士，轻易不去招惹，只拣选那些落单的旅人商贾下手，而且次数绝不频繁，多在暴雨大雪天气里出洞杀人，数百年来，凭借着自身天生的长寿，一点点积攒肉身实力，耐心等待证道机缘的到来，一次次精准捕杀目标，也开始有意挑选那些入流的武人和练气士下嘴，使得它们的实力攀升，越来越快，以至于连一山土地都成了它们梦寐以求的盘中餐，早期双方其实相安无事，土地奈何不得它们为祸一方，它们也抓不住泥鳅一般滑溜的土地老翁。

    李槐实在忍不住了，大骂道：“就你这种货色，也配做土地山神？！老天爷又没瞎眼！”

    老翁背对着那拨孩子，用竹杖使劲砸了一下石坪，懒得跟他们一般见识，只是没好气地小声嘀咕道：“大概是真瞎了。”

    朱鹿其实是最气恼愤怒的人，可当她看到那条黑蛇后，少女浑身不由自主地颤抖起来，二境巅峰的她，发现自己根本就没有与那种怪物对峙的勇气，哪怕一步，只是一步，她也没有胆量踏出去。

    朱河到底是五境武人，胆气十足，再者也容不得他退缩半步，身后就是自家小姐，更有自己女儿，这个男人已经不敢擅自转身，竭力怒吼提醒道：“朱鹿！小心身后崖畔，还有一条畜生躲在暗处！”

    少女只能嘴唇微动，似乎是想告诉她爹不用担心，可嗓音之小细弱蚊蝇。

    武人朱河根本顾不得这些，眼前这条悠悠然晃动头颅的黑蛇，就已经带给他近乎窒息的威慑感。

    石崖峭壁外的空中，一阵嗡嗡声响刺耳响起。

    朱鹿和李宝瓶他们骇然转头。

    一条身躯略显纤细的雪白蟒蛇，悬停在悬崖外不远处的高空，它并无生出四爪，但是一双近乎透明的翅膀正在飞快振动，它一双阴沉眼眸，死死盯住少女朱鹿，一次次吐信，不断有白色浓稠蛇涎坠落，简直就是老饕在垂涎一道美味。

    它打量着清秀少女的身段，最后视线凝固在少女的那张脸庞上。

    被这头畜生凝视的朱鹿，只觉得双腿一软，全身无力，她虽然没有跌倒，但是呼吸困难起来，少女心知肚明，别说出拳退敌，就是动一下手指头，都已是奢望。

    她甚至不知道，自己那张平时颇为自傲的脸蛋，早已满是泪水。

    自习武第一天起就对江湖充满憧憬的少女，这一刻充满痛苦和悔恨。

    她不该死在这里。她怎么可以死在这里。

    少女那双泪水盈眶的秋水眼眸，充满祈求。

    白蟒对于少女的可怜眼神，根本无动于衷，它只是使劲盯着那张楚楚可怜的少女脸庞，愈发垂涎三尺，好像下一刻这张脸颊就会变成她的容颜。

    土地老翁看似垂头丧气耷拉着脑袋，其实眼珠子就没停过，眼角余光一直瞥向那个捻土而成的岳字，覆着那张黄符烧出的灰烬，如果有用的话，他恨不得趴在地上，鼓起腮帮将那些灰烬从岳字上吹走。只可惜他知道，这只会是徒劳无功。

    林守一开始有些焦急，左右张望。

    反倒是李槐扯了扯嘴角，想哭又没哭出来，蹲下身，背靠着李宝瓶脚边的绿色小竹箱，双手抱住膝盖，背后传来阵阵清凉，这个孩子有些想念娘亲一天到晚的骂声，爹每天晚上的打雷鼾声。

    唯有李宝瓶眼神越来越坚定，小姑娘虽然满头汗水，可仍是高高抬起下巴，毫无惧意。

    黑蛇骤然头颅撞向朱河。

    一直屏气凝神小心蓄力的朱河一脚后撤，一脚前踏，以正面一拳，硬扛黑蛇的巨大头颅。

    朱河拳罡刚猛，一拳之后，竟是打得那颗头颅轰然巨响。

    剧烈冲击之下，黑蛇脑袋往后一个晃荡，上半身直起的庞大身躯也随之后仰几分。

    手臂酥麻的朱河一咬牙，下陷半尺的双脚，迅速从石坪当中拔起，身形不退反进，大步前冲，每一步都在山顶石板上重重踏出凹陷脚印。

    方才硬碰硬一撞，朱河不认为自己没有一战之力！

    黑蛇再次蛮横以头直撞而来，朱河体内气机流转如江河决堤，血气蓦然雄壮，手臂肌肉鼓涨，几乎要撑破袖子，怒喝一声，一拳凶狠砸在那头孽畜头颅正中。

    势大力沉的倾力一击，爆发出铁锤砸巨钟的雄浑声势。

    水缸大小的蛇头被一拳砸得摔在石坪上，扬起无数尘土。

    占据上风的朱河正要趁胜追击，身后不远处的土地老翁轻轻叹息。

    有一物拦腰横扫而至，速度之快，远胜于之前黑蛇的两次出头冲撞，瞬间砸在朱河身侧，他整个人被一扫出去十数丈，虽未被一击致命，可朱河皮开肉绽不说，满脸是血，显然受伤不轻，在地面上打了几个滚，堪堪止住后退势头，强提一口气，咽下涌至喉咙的那口鲜血，顾不得伤及肺腑，就要继续前冲继续与那孽畜拼命。

    原来黑蛇先前两次故意示弱，只是为了这一次快若闪电的扫尾做铺垫。

    朱河瞪大眼睛，肝胆欲裂。

    眼角余光之中，白蟒身躯一拱，骤然发力，对他女儿朱鹿发起攻击，那张血盆大嘴，触目惊心。

    就在此刻，一道消瘦身形沿着黑蛇背脊一路飞奔，最后踩在头颅之上，纵身一跃，少年手持柴刀，扑向那条白蟒。

    在千钧一发之际，这位草鞋少年一刀刚好砍断白蟒左边翅膀！

    但是少年也一样被身躯倾斜的白蟒狠狠撞得倒飞出去。

    石坪下的山脊某处，斗笠汉子坐在一棵老松横出悬崖外的枝干上，小口喝着酒，面无表情。

    他扶了扶斗笠，呵呵一笑。
------------

next：第九十九章 山神和竹刀

    体态如女子纤细的白蟒，那对翅膀不算大到夸张，透明晶莹，若非细看，几乎很难察觉。很难想象，扇动这对翅膀，就能让它从石坪悬崖外升空而起，难免让人猜测，它是否掌控了类似练气士某种悬空浮游的术法神通。

    只是如今这一切都意义不大了，白蟒拱背之后迅猛俯冲，张开血盆大嘴，试图吞食掉拥有清秀容颜的婢女朱鹿，不曾想竟然被一名横空出世的持刀少年，用黑蛇背脊和头颅作为阶梯和跳板，一跃而至，手持柴刀恰好砍在白蟒飞翅与身躯接连之处。白蟒需要那对翅膀来升空以及掌控方向，被一刀砍掉飞翅之后，身躯凭借惯性继续前冲，但是立即歪斜横移了丈余距离，白蟒那张血盆大嘴刚好从少女身边擦肩而过，整条身躯重重摔石坪上。

    朱鹿以及她身后的三位学塾蒙童，同样逃过一劫，趁着白蟒撞地后晕头转向的间隙，李宝瓶赶紧背起书箱喊着快跑，林守一默默拿起行囊尾随其后，李槐早就吓得牙齿打架，跑出去一段距离后，无意间发现没有看到讨厌鬼朱鹿的身影，转头一看，李槐呆了一呆，那家伙傻乎乎站在原地，这不是束手待毙是什么？李槐忍不住高声喊道：“朱鹿，还不跑？！”

    朱鹿终于打了个激灵，略微还魂，只是依然有些六神无主，转过头，眼神恍惚地望向李槐，只见那孩子边跑边吼道：“跑啊！等死啊！”

    朱鹿一旦回过神，立即就展现出二境巅峰武人的矫健身姿，四五步便掠到李槐身边，跟他们一起退到远离白蟒的石坪地带，果不其然，朱鹿刚刚离开原地，那条飞翅断折处鲜血喷涌的白蟒，便开始因为疼痛而剧烈挣扎，尾巴疯狂甩动，砸得石坪碎石飞溅，若是朱鹿晚上片刻，恐怕就要被白蟒粗如水桶的大尾砸成一滩肉泥。

    白蟒似乎失去一只飞翅后，元气大伤，胡乱扑腾，溅起无数飞沙走石，久久没有平静下来。

    不过少年也好不到哪里去，握有柴刀的左手虎口迸裂，满手鲜血。

    陈平安单膝跪地，抬起手臂抹去额头汗水，以免模糊视线。

    柴刀已经断去半截，雪亮刀刃反弹之际，若非陈平安见机得快，赶紧侧过脑袋，说不定脸面上就要戳-入半截柴刀，最少脸颊也会被刮去一大块血肉。

    陈平安现在所处位置，与黑蛇白蟒形成掎角之势，那条黑蛇行为诡谲，看到白蟒遭受重创后，并未急匆匆丢下朱河，跑来跟陈平安厮杀，反而比起先前“面容神色”，更加悠闲镇静，好整以暇地慢悠悠晃动上半身躯，始终与朱河保持对峙姿势，黑蛇那双阴气森森的银白色眼眸，偶尔落在白蟒身上的视线，与白蟒之前看待少女朱鹿如盘中美味的眼神，并无不同。

    石坪正中位置，白衣老翁手捧绿色竹杖，瑟瑟发抖，那半截柴刀刚好插在他脚边地面不远处，老翁蹑手蹑脚走近，蹲下身，用手指肚小心翼翼地抹了抹刀刃，手指头瞬间流淌出夹杂有一丝金色的土黄色鲜血，吓得老翁赶紧缩回手，又弯曲手指，轻轻弹指敲击刀身，满脸疑惑，两根手指捻住雪白胡须，嘀咕道：“锋利无匹，当得起锋利无匹的美誉，却竟然只是寻常柴刀，连武人百炼刀也称不上，所以刀身极脆，远远不够坚韧，若是刀身与刀刃品相匹配，再交给那空有一身武艺的憨直汉子作为兵器，未必没有一丝胜算。现在嘛，万事皆休喽。”

    老翁仔细打量着刀刃那条清亮鲜明的漂亮锋线，感慨唏嘘道：“至于这把柴刀的玄机……就只能是在那少年的磨刀石上了？可问题在于，得是多好的一块磨刀石，才能将一把材质粗劣的廉价柴刀，磨出此等锋芒？”

    老翁视线之中有些贪婪炙热，偷偷望向朱鹿李宝瓶那边的箩筐行囊，不出意外，那块磨刀石就藏在其中。

    老翁随即重重叹息，东西再好，哪怕能够拿到手，他如今好像也没命去享福了。

    千恨万恨，只恨那个五境武人鬼使神差使出的撮壤成山诀，本是一门失传无数年的开山术，老翁当时躲在地底下，还报以一种看人鬼画符的笑话心态，到最后自己偏偏就栽在了这个大跟头上。其实这门捻土撮壤的开山神通，算不得如何上乘高明，只是此类神通沉寂太久了，在老翁担任棋墩山土地的年月里，只有一次被人以此术请出山腹府邸，便是那两位来此山顶弈棋的仙人，当然那两位是术法通天的陆地真仙，一个小小五境武人，给那两人提鞋也不配。当年他之所以被喊到山顶，不过是两位真仙不愿坏了某些老规矩，照顾的可不是他这位棋墩山小土地的颜面。

    陈平安不是不想借机解决了白蟒，实在是五脏六腑在翻江倒海，让他根本无力多做什么，一次汗水抹掉之后，很快就会重新布满脸庞，陈平安干脆就不再去浪费力气，只是不断调整呼吸，尽量让体内絮乱气息趋于平静，这种调整，就像在对大雨天四面漏风的窗户，尽力进行缝缝补补。

    擂鼓之声，再度从心口响起，声响渐渐变大，声响不是从耳传入，反而有点像是玄之又玄的心声，在清清楚楚传达身躯体魄的颤抖哀鸣。

    少年这种近乎本能的直觉，最早源于年幼时在泥瓶巷的那次绞痛，之后在山上还经历过一次。

    这次之所以没有满地打滚，是陈平安察觉到体内那条势若火龙的古怪气息，开始由腹部逆流而上，所经之地，无论是从宋集薪家那具木人认识到的一座座气府窍穴，还是人体关隘城池之间相连接通的经脉，很大程度减缓了疼痛感，如武将带兵平定叛乱一般，或是宋集薪所谓演义小说上的御驾亲征，效果显著，虽然无法解决根源，但是最少能够让那些叛军避其锋芒。

    朱河虽然受伤不轻，但是气势不降反升，一身雄浑战意昂扬奋发，两袖鼓荡猎猎作响，颇有几分不容轻侮的宗师风范。

    腹部缓缓在石坪边缘游走的黑蛇眯起眼眸，即便朱河展现出不俗的战力，它始终不急不躁，左右大幅度摇晃头颅，像是在蹩脚地寻找漏洞，如此一来，无形中送给了朱河压下伤势的大好良机。

    老翁看在眼中，犹豫了一下，仍是有气无力地出声提醒道：“别垂死挣扎了，这条孽畜之所以不急着吃掉你，无非是希望你完全激发气血，它只是在等待一颗青涩果子的成熟罢了，莫要以为它拿你没辙，否则哪怕它吞下你的这副身躯，仍是消化不掉你的精气神，要晓得那才是真正的大补之物。”

    老翁哀叹一声，开始捯饬杂乱须发和破败衣衫，自嘲道：“好歹是一方土地，死之前总得有个山岳神祇该有的样子。”

    老翁坐在地上，一边收拾一边冷笑，“对了，孽畜可不止是肉身强横，动作敏锐，它在百余年前吞吃了一位中五楼修为的道家练气士，如今估摸着怎么也该修成了一两种入门道法，说是粗浅不堪，可是由这头孽畜用出，恐怕任你是五境体魄也扛不住，说到底，算你们点子背，好死不死，是一个五境武人担任领头羊率队入山，若是六境，两头孽畜虽然也吃得下，可未必愿意出洞，怕两败俱伤嘛，若是七境，嘿，它们早就主动避让几十里路了，恨不得你们赶紧滚出棋墩山的地界。”

    少女朱鹿悚然，闻言后万念俱灰。

    林守一喃喃自语道：“阿良，阿良前辈呢？”

    李槐突然发现李宝瓶在悄悄翻动书箱，摸出一只小瓷瓶后，紧紧攥在手心。

    顺着她的视线，远处陈平安不动声色地朝他们点了点头。

    李槐突然有些羡慕李宝瓶和她那位小师叔的这种默契。

    书上说，这叫心有灵犀。

    而朱河听到土地老翁的泄露天机后，脸上并无半点惊惧神色，拧了拧手腕，洒然笑道：“束手束脚窝囊是死，放开手脚痛快一战，也是死，既然都是死，还管什么死后会不会成为那头孽畜化龙的垫脚石？！”

    五境武人，已经有资格被誉为武道小宗师，魂意壮大，神魄坚固，只差凝聚出一颗武胆而已。

    朱河身陷必死之地，全无退意，其实契合武道宗旨“向死而生塑武胆”之真意，只是仍需继续锤炼打磨而已。

    朱河一身武人气势早已攀升到顶点，蓄势待发。

    黑蛇瞬间一改先前悠闲懒散的模样，仿佛是真正确定了朱河再无保留余力，一身魂魄皆已于气府沸腾，随着气血急速流转全身，那么它就可以下嘴品尝这道美味了。

    黑蛇抬高头颅，同时张了张嘴巴，逐渐露出两颗象牙色毒牙的恐怖面貌，粗如青壮手臂，相比白蟒一张嘴就会蛇涎流淌的污秽模样，有望成为神物墨蛟的这条黑蛇相对要干净许多，大嘴之内雪白一片，一阵阵寒气向外流泻，反差鲜明的黑白两色，衬托得这条成精畜生威严十足，反而比那邋遢老翁更像是货真价实的土地山神。

    黑蛇骤然发起攻势，这一次不再是示敌以弱的头颅直撞，瞬间将嘴巴张开到极致，看似朝石坪地面上的朱河脑袋一咬而下，实则在半途就喷出一口腥臭至极的雪白瘴气，瘴气凝如实质，好似一支床弩箭矢直射地面。

    朱河是小镇土生土长的李家家生子，实战经验并不丰富，习武生涯当中，多是与家族老祖宗一场场点到即止的切磋，生死之战更是头一遭，可是吃过一次孽畜声东击西的大亏后，朱河对黑蛇的阴险奸诈，身形随之而动，决不再与其正面硬碰硬。

    果不其然，那道如箭矢锋锐的冰冻瘴气刚刚落空，石坪地面激荡粉碎，朱河横移数步后，立马就感受到侧面一股劲风横扫而来，又是之前的明暗两板斧，朱河早有预料，脚尖一点，不退反进，笔直向前，直扑黑蛇腹部。

    不曾想那条黑蛇身躯后仰，嘴中瘴气一口口频繁吐出，用意不在贯穿朱河身躯，只为阻滞他的前冲，同时尾部不断延伸，直到形成盘踞山头之势，一个大圈牢笼，将朱河瞬间围困其中，迫使朱河做那困兽之斗。

    黑蛇漫长的身躯，在围出足足两圈“城墙”之后，竟然还能高高翘起尾部，如巡城士卒，防止朱河飞窜出去。朱河一次应对已经足够迅速，在蛇身第二圈形成之前就要拔地而起，只是身形刚刚腾空，就被那条尾巴迅猛砸下，朱河双臂护住头颅，被猛然拍落回石坪，虽未伤及内脏，但是气海如沸水蒸腾，使得一张脸庞涨得通红，流转全身的魂魄神意出于好意，为了庇护主人不受创伤，不得不离开既定的经脉道路，转而渗透进入更外围的血肉肌肤。

    黑蛇冰冷银眸流露出一丝得意笑意。

    如果说之前这位武人是七分熟的美味，那么现在就有九分熟了。

    所以它不再继续消耗元气，而是张开大嘴，一次次低下头颅扑向朱河。

    朱河出拳如虹，在这座斗兽场内灵活辗转腾挪，两条手臂绽放出青蒙蒙的罡气，每次出拳皆可裂空，风声大震。

    虽然处于绝对下风，朱河却没有半点颓势，眼眸熠熠，精气神更是前所未有的充沛。

    白衣老翁竖起耳朵，啧啧称奇，虽未亲眼见到大战光景，却猜出个大概，心想真是个不错的武道宗师胚子，半路夭折，惜哉惜哉。

    他猛然火烧屁股地惊醒起身，捡起那根黯淡无光的绿色竹杖，对那些武人的同行之人喊道：“快来一个人，随便谁都行，只要是童男童女皆可，将你们长辈捏出的岳字用脚踩平，我就能脱身，不受此符拘束，到时候我可以助他一臂之力，不敢说斩杀孽畜，脱困总是不难，快！”

    老翁焦急视线在那几人脸上游移。

    林守一嘴角泛起冷笑。

    李槐刚要鼓起胆气去冒死涉险一趟，却被李宝瓶一把扯住胳膊。

    老翁愕然，痛心疾首跳脚骂道：“不知好歹的蠢货，难道要眼睁睁看着你们长辈力竭战死？！你们这帮小崽子的良心都被狗吃了不成？”

    朱鹿身形一闪，向那位棋墩山土地狂奔而去。

    远处陈平安突然厉色喊道：“朱鹿你别去！你如果不帮他，他无路可退，说不定只能跟我们并肩作战，如果帮了他，以他胆小怕事的心性，肯定就跑了！再者我们还不确定他到底是不是跟两条畜生一伙的，你别冲动！他从头到尾，看似一直在帮我们，但你有没有发现，他其实一点都不曾帮到朱叔叔！”

    朱鹿哪里愿意听陈平安的言语，只管埋头前冲。

    陈平安在开口说话的瞬间，其实就已经开始向土地老翁冲去，速度丝毫不比朱鹿逊色。

    如果没有意外，草鞋少年有希望拦下朱鹿的举动。

    土地老翁脸色阴晴不定，手持绿杖站在原地。

    断去一翅的白蟒，在翻腾之后，很快就躺在石坪上不动弹，奄奄一息，像是再也无法参加这场搏杀。

    但是当陈平安冲向土地老翁，身形出现在它头颅十数步外，白蟒毫无征兆地向前一窜，大嘴狠狠咬向少年，哪里还有之前那副半死不活的濒死架势。

    陈平安却猛然停下脚步，向后倒退而去，躲掉了白蟒的凶险扑杀，怒喊道：“朱鹿！看到没！这条孽畜同样希望你毁掉朱叔叔的那个岳字！那人跟两头畜生说不定早就达成了秘密约定！”

    陈平安被白蟒身躯阻隔了视线，看不到白衣老翁那边的景象。

    但是那颗白蟒的头颅，先是略显慌张地望向少女那方，继而缓缓扭向少年，眼眸充满讥讽之色。

    那一刻，少年满怀愤懑和失望。

    以至于连体内那条火龙，在经过高处三座气府窍穴的时候，莫名其妙从势如破竹的气势，变成小心翼翼的卑微姿势，少年也不曾注意留心。

    脑子里一团浆糊的少女朱鹿跑到那个岳字附近，满脸泪水，伸出脚一通乱踩，少女哽咽道：“我要救我爹！我要救他！我知道，因为他是我爹，所以你们才会这么无所谓他的生死！”

    岳字上边的黄符灰烬，被踩得混入泥土，最终消散不见，岳字在少女的踩踏之下，终于模糊不见。

    白衣老翁呆呆低头看着少女的双脚，从喉咙深处发出一阵压抑至极的笑声，“嘿嘿……”

    然后老翁抬起头，玩味凝视着那个仓皇失措的少女，老人手腕随意拧转，绿色竹杖在空中带出一片翠绿流萤，苍老脸庞，如枯木逢春，老人笑逐颜开，点头道：“呵呵，救父心切，理解理解。”

    老翁的身形开始迅速增高，容颜变得越来越年轻，筋骨伸展，发出一连串黄豆崩裂的刺耳声响，已是中年男子模样的他仰天大笑，似哭似笑，快意至极，“哈哈哈！”

    变得容颜俊美的绿杖男子，笑望向那头白蟒，“按照约定，我帮你们对付那个藏头藏尾的斗笠汉子，至于这些家伙嘛，随便你们处置，当然了，以后咱们双方相处，可就不能继续是之前数百年的样子了，放心，我只等被敕封为山神后，会将你提拔为此处的土地，至于你那汉子走江一事，我也会扶持一二，说到底，大家互利互惠，共襄盛举。”

    绿杖男子说完这些言语，已是俊逸潇洒的弱冠男子，笑眯眯望向那个目瞪口呆的少女，“你爹与我有缘啊，本来大骊这次封赏版图上的各路山河神祇，我撑死了就是借机恢复土地正身，可他竟然能够喊出那位‘先生’的名讳，实在是震撼人心，等于帮我重新钦定了原本被仙人剥夺摘去的土地之身，实不相瞒，若是他当时捻土撮壤写出那部开山篇的嶽字，说不得我此时根本无需大骊敕封，就已是棋墩山的正统山神了。”

    男人神色无比欢愉，慢慢踱步，自顾自摆摆手，笑道：“没关系没关系，我很知足了。你爹是好人啊，你也是。你们是我的贵人，只可惜滴水之恩，才要涌泉相报，结果你们这么大的敕封之恩，我实在是无以回报啊。”

    少女面无人色，嘴唇颤抖，反复呢喃道：“你骗人，你骗人……”

    玉树临风的男人瞥了眼白蟒，“飞翅被斩断一事，咱们可都意料不到，别奢望我会额外补偿什么，如今我穷酸得很，棋墩山方圆数百里，这么多年早被你们搜刮殆尽了，我这堂堂土地老爷只剩下一层地皮，很不像话啊。”

    白蟒温顺点头，透露出一丝罕见的谄媚，然后轻轻晃了晃头颅。

    男人大手一挥绿杖，豪迈道：“你们的那点破烂家底，我可不稀罕，所有以往过节，就让它随风而逝好了。”

    最后他环顾四周，笑嘻嘻道：“那个被你们称呼为阿良的兄弟呢，不拜山头也就罢了，还敢坐我的交椅，最后更是让嶽字降为岳字……”

    这位正值意气风发的山神，突然眼神茫然地低头望去，一脸痛苦欲绝和匪夷所思。

    一把普普通通的竹刀从他心口穿过。

    斗笠汉子与他并肩而站，只是面朝方向相反，那人松开刀柄，然后拍了拍这位山神老爷的肩膀，笑眯眯回答道：“你找我？”
------------

next：第一百章 脚下河山

    当斗笠汉子松开那柄竹刀的刀柄后，换作肩头一拍，在鬼门关打了个转的俊美男子，非但没有如释重负，反而愈发战战兢兢，他脸上再无先前指点江山的畅快笑意，身形一动不动，嗓音干涩道：“前辈，今日误会，是我唐突了。”

    事实上，这个来历不明的汉子，既然能够神不知鬼不觉地出现在身侧，轻而易举以寻常竹刀捅穿他的心窍，那么他就确定无疑，自己绝非此人的对手，兴许唯有等到自己成为棋墩山正神，才有与其扳手腕的底气，那么一个棘手问题就摆在了他眼前，是老老实实站直了挨打，还是硬气地搏上一搏？

    其实当那人手心离开刀柄的瞬间，普通材质的竹刀就已经失去了震慑力，作为神祇，哪怕仅是不入流的土地公，搁在世俗王朝的官场，他就是没有官身的胥吏罢了，可神祇到底是神祇，比如他当下这副经受无数香火熏陶的金身，足可媲美七境武人的体魄，尤其是没有死穴一说，所以哪怕被竹刀捅穿后背心口，仍是不碍大事，可名叫阿良的斗笠汉子，越是如此漫不经心，他就越忐忑不安。

    犹记得当初被那两位莅临此山的陆地真仙，以无上神通销毁他的神位金身，当时那两人的气态姿容，亦是如此轻描淡写，甚至远远不如他们对弈手谈的任意一次落子。

    阿良出刀之后，此时又恢复玩世不恭的德行，摘下腰间小葫芦，轻轻晃动，酒香四散，阿良灌了一口烈酒，绕着这位年轻俊美的土地公转圈散步，啧啧道：“你这家伙演戏的本事挺好，当然那条白蟒也不差，加上暴戾的黑蛇，配合得堪称天衣无缝。不过你自认为大功告成后的真情流露，更符合我的胃口，三次笑声，很精彩，我喜欢。”

    那双黑蛇白蟒早已开窍通晓人性，在斗笠汉子笑眯眯跟男子打招呼的同时，几乎同时就急急退去，黑蛇迅速散开身躯长墙，退回山巅石坪一侧边缘，失去一翅的白蟒扭曲后撤，乖乖盘踞在悬崖畔，皆头颅低垂，低眉顺眼，温驯异常。

    这一次，绝不是假装，蛇蟒双方那覆盖庞大身躯的鳞片，微微颤抖，发乎本心。

    它们甚至不敢正眼打量那名斗笠汉子。

    阿良一记竹刀，就让一切尘埃落定。

    年轻土地听到斗笠汉子的打趣后，满脸尴尬，“阿良前辈说笑了。”

    阿良收敛笑意，“说笑？”

    俊美风流的年轻土地好像察觉到不妙，大概以为眼前这位斗笠汉子，是那种翻脸无情的性格，是要对自己痛下杀手了，一急之下，便是使出一方山水神祇的神通，身躯如黄泥软化流淌，立身之处的地面泥浆翻涌，几乎一个眨眼功夫，这位土地就不见了踪迹，烂泥塘似的地面，也瞬间恢复如常。

    缩地成寸，其实道门兵家都有类似术法。

    没了身躯支撑，绿色竹刀下坠。

    阿良伸手握住竹刀，发现红棉袄小姑娘三人瞪大眼睛望向自己。

    阿良赶紧抬头挺胸，没有将竹刀放回刀鞘，而是以刀尖拄地，摆出一副抬头望天的潇洒姿态。

    斗笠汉子偷偷碎碎念：“夸我，使劲夸我。我阿良最大的两个优点，就是喜欢接受批评，你批评我，我就打死你。再就是经得住别人的称赞褒奖，再没谱再肉麻，都接得住。”

    李槐率先开口，孩子一路小跑到阿良身边，上下打量了一番，说道：“阿良，你来这么晚，是不是拉屎去了？真是懒人屎尿多，你知不知道再晚来一点，以后就没人陪你唠叨，陪你一起撒尿了？那么到时候你会不会想我？”

    假装高人风范很是辛苦的阿良顿时破功，恼羞成怒道：“我想你娘想你姐，就是不想你这个没良心的兔崽子。”

    李槐破天荒不反骂回去，低下头，脸色有些黯然。

    阿良叹了口气，摸了摸孩子的脑袋，“你这不是没死翘翘嘛，愁眉苦脸做啥，行了行了……”

    李槐立马笑嘻嘻抬起头，“阿良，你教我绝世武功吧？”

    阿良笑问道：“你能吃苦？”

    孩子一本正经摇头道：“当然吃不住苦，你就没有让我不用吃苦，也能练成天下无敌的厉害功夫？”

    阿良嘴角抽搐，“你觉得呢？”

    李槐撇撇嘴，斜眼斗笠汉子，“阿良，你让我很失望啊。”

    李宝瓶背着小书箱，朝阿良笑了笑，然后跑去看陈平安。

    林守一来到阿良身前，有些疑惑，却没有开口询问什么，阿良对少年点了点头，示意私下聊。

    浑身浴血的朱河盘膝而坐，只是看着吓人而已，并未伤及魂魄和元气根本，汉子抹了把脸上的血迹，满脸笑意，只觉得痛快，真是痛快，这辈子不曾如此酣畅淋漓，好像所有心胸间的积郁都因为这场大战，一扫而空，脑海清明，筋骨舒张。

    朱鹿飞奔到朱河身边，蹲下身，还带着满脸泪痕，朱河摆手大笑道：“闺女，大难不死必有后福，好事，天大的好事！爹感觉像是抓住了一丝破境的契机，原本死气沉沉的几座关键窍穴，有了新气抽芽的迹象，别小看这点苗头，对于爹这种原本武道前途断绝的人来说，莫大幸事！”

    朱鹿将信将疑，忧心忡忡道：“爹，你别急着说话了，小心扯到伤口。”

    朱河笑意更浓，双手撑在膝盖上，容光焕发，整个人显得格外精神饱满，“这点小伤算什么，若是再熬上一刻钟一炷香的功夫，爹说不得就能一只脚跨入第六境的门槛了，当然，前提是爹没死在那条畜生的嘴下。”

    朱河说到这里，望向斗笠汉子那边，伸出大拇指，“阿良前辈，到了红烛镇，请你喝那新酿的杏花春！”

    背对朱河的阿良抬起手臂，摆摆手，说了句很煞风景的话，“老朱啊，大恩不言谢，记在心里就好，说出来显得多没诚意。”

    陈平安那边接过李宝瓶递过来的小瓷瓶，正是杨家铺子的祖传独家秘方，用处很简单，就是扛痛，之前在小镇神仙坟，与马苦玄那番差点分出生死的惨烈搏杀后，少年便用过一次。如果阿良没有及时出现，那么这只小瓷瓶就一定会派上用场。现在就不需要了，陈平安此刻虽然满身绞痛，但是还不至于用上它，杨老头曾经说得很清楚，是药三分毒，能不用就别用，尤其是习武之后，如果滥用所谓的灵丹妙药，长远来看，就是在挖自己的墙角。

    李宝瓶看着脸色苍白的小师叔，心思细腻的小姑娘敏锐发现，小师叔握着柴刀的左手，一直在克制不住地颤抖。

    陈平安轻声安慰道：“不打紧，只是身子骨暂时被打回了原形，但不是没有好处，如果我的感觉没有出错的话，将来好处要更多一些。”

    李宝瓶使劲点头，一点也不怀疑，因为小师叔说过不会骗她。

    阿良环顾四周，分别看过了黑蛇和白蟒，想了想，悄然加重力道，拄地刀尖不易察觉地往地面钉入一寸距离。

    一位失魂落魄逃回山腹洞府的土地，脑袋上就跟被一记天雷砸中，鲜血爆溅，他吓得屁滚尿流，躲远几步后抬头望去，仅是空中露出一小截绿色刀尖而已，再无其它。这位气度翩翩如豪阀俊彦的貌美青年，咬咬牙一跺脚。

    下一刻，他的身形便从棋墩山石坪如雨后春笋，破土而出，他一只手掌按住伤口，哭丧着脸望向那个高深莫测的斗笠汉子，恨不得跪地求饶，苦苦哀求道：“恳请大仙不要再戏耍小的了。”

    当这位年轻土地去而复还后，少女朱鹿下意识吓了一大跳，她不知为何瞬间就情绪爆发，站起身对着阿良喊道：“杀了他们！”

    阿良笑着转过身，看着那个脸色狰狞的少女，问道：“为什么要杀掉他们？跟我无缘无故，无冤无仇的。”

    少女清秀可人的脸庞愈发扭曲，伸出手指，遥遥指着斗笠汉子，“无缘无故？！那两条畜生方才要吃了我们！这个棋墩山土地更是幕后的罪魁祸首！

    阿良恍然，看了眼满脸焦急的年轻土地，然后各自看了眼黑蛇白蟒，“你要吃我？你？还是你？”

    棋墩山土地和两头尚未化形的蛇蟒，自然一起死命摇头。

    少女气得浑身颤抖，哭腔道：“我爹差点就死了，我们都差点死了！”

    她泪眼朦胧，望着那个陌生至极的斗笠汉子，“你明明有这份能耐，为民除害，为何不做？两头孽畜，一个假公济私，不庇护旅人，反而合伙害人，你阿良怎么就杀不得？”

    阿良默然片刻，突然大笑起来，“哈哈，你这口气，像是我未过门的媳妇啊。不行不行，我其实喜欢年纪稍大一些，身段完全长开了的姑娘……”

    说到这里，阿良从地面抽出竹刀，放回刀鞘，双手做了一个浑圆饱满的手势，贼兮兮道：“我喜欢这样的。”

    少女愣了愣，尖声道：“你不可理喻！”

    朱河挣扎着起身，拍了拍自己女儿的肩头，沉声道：“不可无礼，更不可意气用事，一切就交由阿良前辈自行处置好了。”

    朱鹿猛然转过头，望向远处，满脸委屈愤懑。

    阿良望向陈平安，少年点头道：“阿良你做决定。”

    阿良懒洋洋道：“行吧，那就我说了算，老话说得好，做人留一线，日后好相见。身为江湖儿女，咱们要大度些……”

    年轻土地使劲点头。

    石坪那两条小山似的蛇蟒也微微低垂头颅。

    阿良突然转变口风，“可害我受了这么大惊吓，没有一点补偿就不合情理了。”

    年轻土地欲哭无泪。

    这位阿良大仙，真正差点胆子吓破的人，现在就站在你对面啊。

    阿良想了想，一把搂过棋墩山土地的肩膀，尴尬的是一人身材不高，另一个却是玉树临风的修长身材，幸好后者识趣，连忙低头弯腰，才让阿良不用踮起脚跟与自己勾肩搭背。阿良拉着他窃窃私语，他小鸡啄米不断点头，绝不敢说半个不字。

    到最后，似乎是被阿良的简单要求震惊到了，起先唯恐要掉一层皮的年轻土地，既惊喜且狐疑。

    阿良不耐烦地挥挥手，“趁我改变主意之前，赶紧消失。”

    之后年轻土地与蛇蟒，以类似唇语的偏门术法沟通，然后他很快就遁地而走，白蟒小心翼翼摇摆游曳，用嘴巴叼起那只摔落在石坪上的断翅，尽量绕开众人，与那条黑蛇一起离开山巅，离去之前，面朝那位某个瞬间让它们几乎蛇胆炸裂的斗笠汉子，两颗硕大头颅缓缓落下，最终触及地面，向阿良摆出臣服示弱之意。

    暮色里，一场突如其来的惊险大战之后，朱河喊上陈平安一起，去靠近石坪的一处溪涧清洗伤口，少女朱鹿默默跟上。

    一大一小蹲在水边，各自清洗掉脸庞衣衫上的血迹，朱河欲言又止，陈平安眼见少女一个人远远坐在溪涧石头上，少年就说先回去了，朱河点点头，没有挽留。在陈平安离开后，朱河站起身，来到女儿身边坐下，柔声道：“怎么连一声对不起也不说？”

    少女脱掉靴子长袜，露出白白嫩嫩的脚丫，听到父亲略带责问的言语后，少女蓦然睁大眼眸，委屈道：“爹，你什么意思？”

    朱河看着女儿的眼睛，那是一双像极了她娘亲的漂亮眼眸，使得这个正直汉子一些到了嘴边的生硬话语，稍稍打了个转，叹了口气，语气平缓道：“先前陈平安阻止你不要毁掉岳字，事后证明他是对的。”

    朱鹿双手抱住膝盖，望向溪涧流水，冷哼道：“你又不是他爹，他陈平安当然不担心，我当时哪里顾得上这些，如果万一他错了呢，难道我就看着你死在那里？”

    朱河默不作声。

    她扭过头，红着眼睛，“爹，如果我那个时候不做点什么，还是你的女儿吗？”

    朱河忍住一些伤人的话，硬生生把一个字一个字憋回肚子。

    男人本想说你身为二境巅峰的武人，不该面对强敌便轻易失去斗志的。

    只是这些话，如果只是武道的同道中人，朱河可以说。

    但他还是她的父亲，那么这些话，就不能说了。最少在这个时候不能说，只能等到以后找个合适的机会。

    但是朱河在内心深处，始终觉得哪里不对劲，可具体是什么，男人又说不上来。

    刚刚在武道之上重新看到一线曙光的男人，没来由有些愧疚伤感，心想她娘如果还活着就好了。

    通往石坪的山路上，少年缓缓独行，夕阳将少年的瘦弱身影拉得很长。

    山巅，李宝瓶在收拾小书箱里的家当，李槐凑热闹蹲在一边，莫名其妙蹦出一句，“李宝瓶，小书箱我马上也会有了哦？”

    李宝瓶狠狠剐了他一眼，“有就有，但是你不可以喊我的小师叔叫小师叔！”

    李槐问道：“凭啥？”

    李宝瓶杀气腾腾地扬起一颗拳头，眯眼问道：“够了吗？”

    李槐咽了咽口水，嘀咕道：“小师叔算什么，我还不稀罕呢，白白降了一个辈分。”

    李槐拍拍屁股站起身，走远了后，才转头笑道：“李宝瓶，以后万一跟我陈平安称兄道弟，你咋办？应该喊我啥？”

    李宝瓶呵呵笑着，站起身后，拧了拧手腕。

    李槐慌张道：“李宝瓶，你能不能总这么用拳头讲道理啊，我们好好说话不成吗？我们是读书人，读书人要……”

    不等李槐说完，李宝瓶快步上前，就要揍这个李槐。

    李槐急中生智，硬着头皮一步不退，苦口婆心道：“李宝瓶，你就不怕你家小师叔，觉得你是蛮横不讲理的千金小姐？到时候他不喜欢你了，你找谁哭去？可别怪我没提醒过你，这叫勿谓言之不预！”

    李宝瓶停下身形，皱紧眉头。

    李槐拍胸脯道：“放心放心，咱们三个里头，陈平安最喜欢你了，只要你以后别像那个朱鹿就行。”

    李宝瓶笑着返回原位蹲下，继续收拾小书箱。

    李槐跟大摇大摆离开，满脸得意，“山人有妙计，治国平天下。以后再也不怕李宝瓶喽。”

    李槐高兴得很，就忍不住想要跟他那位阿良兄弟众乐乐一下，怒吼道：“阿良？阿良，死出来！”

    孩子举目望去，结果看到阿良和林守一不知道什么时候凑在了一起，李槐刚要跑去，结果猛然停步，因为那一处石坪崖畔，正是先前白蟒出现的地方。李槐一阵后怕，犹豫了一下，还是转身跑去蹲在李宝瓶身边，然后寻找陈平安的身影。

    一想到那家伙毅然决然飞扑向白蟒的身影，李槐怔怔出神，这个鬼怪灵精的顽劣孩子，下意识觉得那个李宝瓶的小师叔，挺靠谱，最少比那个朱鹿好太多了。

    崖畔，阿良和少年林守一坐望远方山河，林守一仰头喝了一口烈酒后，将酒葫芦递还给阿良。

    林守一坐姿端正，相比阿良的歪七倒八，大不相同，少年轻声问道：“阿良，这葫芦里的酒是不是很不简单？”

    阿良嗯了一声。

    林守一好奇问道：“怎么个不简单？我只知道喝过酒之后，我的身体变好了很多。”

    阿良晃了晃小酒壶，一语道破天机，“仅是故意摇晃出一点点酒气，就能吓退铁符河上那些成了人形的妖物，你说厉害不厉害？当然了，像平时这样拔出酒塞而已，鼻子再好，也只能闻到酒香。”

    林守一愈发好奇，问道：“那你为何要放过那位此山土地和两条蛇蟒？”

    阿良扶了扶斗笠，笑道：“一山土地，是有护身符的存在，杀了不难，但是之后会很麻烦，而我现在最怕的就是麻烦。再说了，他们跟你们有生死大仇，跟我阿良可是无冤无仇，现在你们什么都没有少，朱河还得了天大裨益，为什么还要赶尽杀绝？”

    阿良停顿片刻，“有人倒是少了些东西，不过我估计他不会太在乎就是了。没办法，这家伙对于得失的计算方法，跟别人不太一样。”

    林守一说道：“是说陈平安吧？他受的伤显然比朱河要重一些，不过他掩饰得比较好。”

    阿良对此不做评论。

    林守一自顾自说道：“那朱鹿救父心切，自然没有错，但是她错在……”

    阿良摆摆手，打断少年的盖棺定论，笑道：“背后不说人是非，公道自在人心。”

    林守一嗯了一声，果然不再说话。

    清风拂面，阿良慢悠悠喝着酒，缓缓道：“林守一，你很聪明，你是第一个意识到我值得结交示好的聪明人，别急啊，我可没有贬低你的意思，恰恰相反，修行路上，有人有慧根，如李宝瓶，有人如福缘，如李槐，而有人有悟性，就像你，全都是好事。齐静春的眼光，一向很好的，要不然……”

    林守一竖起耳朵。

    阿良咧嘴一笑，“他能认识我这样的朋友？”

    林守一会心一笑，这个男人从来不放弃自我吹捧的机会，早就习惯了。

    可是心智成熟的少年，越来越确定一件事。

    那就是阿良的吹嘘，听上去很不着边，可那是因为连同自己在内，没有谁真正知道这个家伙的厉害。

    “对酒当歌，人生几何？譬如朝露，去日苦多。”

    阿良狠狠灌了一口酒，仰起头望向夜幕降临的天空，轻声念道：“还有那青青子衿，悠悠我心……世上怎么会有如此动人的言语？”

    阿良晃晃脑袋，散去那点愁绪，自嘲一笑，伸手指向那连绵山脉，“在有些人眼中，人间就像一条倒挂的银河。”

    林守一问了一个极有深意的问题，“阿良，‘有些人’之中，有你吗？”

    阿良摇摇头，“暂时还不是，我不太喜欢做那样的人。”

    阿良轻轻呼出一口气，不再喝酒，单手托起腮帮，歪着脑袋眺望远方，“昔年有一位脾气死犟的老先生，桃李满天下，得意弟子之中，齐静春的字最好，崔瀺的棋术最高，还有一人的剑术最强。”

    林守一忍住笑，转头望着斗笠男人的侧脸，道：“剑术最强的弟子，是叫阿良吗？”

    阿良哈哈大笑，“那个人当然不是我，怎么可能是我。”

    没有猜对答案的林守一有些错愕。

    只听那家伙笑着说道：“不过那个人的剑术，是我教的。”

    少年虽然被震撼得无以复加，可仍是对此深信不疑。

    阿良转过头，问道：“如果我说齐静春的字，也是我教的，你信不信？”

    正襟危坐的少年毫不犹豫，斩钉截铁道：“打死我也不信！”

    阿良拍了拍少年的肩膀，语重心长道：“林守一，果然很聪明，所以明天你没酒喝了。”

    一向古板冷漠的少年咧嘴而笑，不过依旧含蓄无声。

    阿良感慨道：“天地者，万物之逆旅。读书人说话，就是有学问。”

    林守一突然问了一个莫名其妙的问题，“阿良，陈平安让你失望了吗？”

    斗笠汉子脸色如常，“拭目以待吧。”

    夜幕深沉，后半夜的篝火旁，陈平安像往常那样跟朱河负责轮流守夜，少年同时编织着草鞋。

    朱河不知为何起身来到少年身边，陈平安有些讶异，朱河伸手烤火，火光映照着男人粗犷的脸庞，男人转头笑问道：“你应该找到那股气了吧？气若游龙，而且它不断下沉，四处游走，对不对？”

    陈平安点点头，坐正身体，这正是他最疑惑不解的地方。

    朱河没有藏藏掖掖卖关子，慢慢解释道：“这等于说你跻身了泥胚境，千万别小看这第一道坎，能否习武，就看你生不生得出、找不找得到、管不管得住这一口气。俗话说人争一口气佛受一炷香，差不多就是这个意思，身体依然是不成气候的泥塑菩萨，但只要有了这口气，就算登堂入室，之后一切皆有希望，武道之巅的风光再好，没有这关键的一小步，就全是空谈。”

    朱河打量了一下少年，赞赏道：“你的身子骨打熬得不错，嗯，是很不错才对，一点不输给那些药罐子里浸泡长大的豪阀子弟。我不知道你经历过什么，但是大致可以确定，你如今已是泥胚境之后的武夫第二境，木胎境了。虽然不太说得通，为何你尚未真正让那股气机找到栖息修养的气府窍穴，但你的体魄经脉，的的确确属于第二境的成就，不过远未二境大成而已。”

    陈平安屏气凝神，认真凝听这些千金难买的武学门道。

    被李家老祖宗誉为“明师”的男人，继续说道：“木胎境，这一层很有趣，成就高低，不靠天赋，不管根骨，就两个字，吃苦。之前阿良跟你们解释过大骊驿路，对吧？”

    陈平安点头问道：“这跟习武也有关系？”

    朱河给沟壑添了一把柴禾，尽量用通俗易懂的言语，解释那些原本云遮雾绕、晦涩难明习武关窍，笑道：“我们的人体经脉，其实就像驿路，想要车马通行，就只能一点点逢山开路，遇水搭桥，有些人惫懒，吃不住苦，修出了羊肠小道，搭建了独木桥，其实也能走，继续往武道高处走，但是越往后，局限会越大，很简单的道理，高手支招，如同两国之争，就看谁的兵马驰援更快，哪怕你有千军万马，但是道路狭窄难行，你如何顺利调兵遣将？”

    陈平安恍然大悟，“是这个道理！”

    “所以这一层又叫开山境，最考验水磨功夫，习武必须下死力气，下苦功夫，以至于被眼高于顶的练气士，视为下等人的末流活计，就跟这一层有很大关系。因为武人在这一级台阶上，实在是容不得半点懈怠偷懒，就跟庄稼汉差不多，想要收成，就只能埋头苦做。”

    陈平安笑道：“我吃苦还行，不比别人差多少。”

    朱河哑然，心想你陈平安如果才是“还行”的话，那我朱河该置身何地？

    朱河脸色肃穆起来，“但是切记，在这一层境界，勤勤恳恳是好事，却也不能滞留太久，道家为何推崇返璞归真四个字？就在于先天一口真气，随着岁数增长，会逐渐流失，或是被天地之间的污秽之气、阴煞之气在内，诸多杂气给混淆得浑浊不堪，这就像文人喜饮茶，他们种植茶树，最忌杂木丛生，即是此理。”

    “一般而言，在十六岁之前，最多十八岁之前，就要尝试着突破进入第三境，水银境，让自己的气血更加雄壮，如水银凝稠，与此同时，你的身躯会愈发轻盈，同时骨骼却愈发坚韧。人之气血，如沙场武将麾下的士卒，需要一支虎狼之师，而不是那种草台班子，绣花枕头，这么说能理解吗？”

    脚上穿着草鞋的少年，又低头看了眼手中正在编织的草鞋，赧颜道：“能理解。”

    朱河忍俊不禁，低声笑道：“第二境的大成之境，能够让你肌肤纹理精密，就像练气士的法宝，篆刻上了符文宝箓，再加上经脉开拓之后，武道的路子就越走越宽，至于第三境水银镜的巅峰，至关重要，需要渡过一劫，武学秘籍上往往称之为‘泥菩萨过江’，具体细节，本就玄之又玄，我不好多说，个人有个人的缘法，说不定我的经验之谈，反而害你误入歧途。”

    陈平安一个字不漏地默默记下。

    朱河沉声道：“前三境为炼体，相对务实，之后三境则有些务虚，魂魄胆三事，循序渐进。”

    然后朱河就陷入沉思，今日一战，受益匪浅，朱河需要将那些灵光乍现的思绪沉淀下来。

    陈平安不敢打搅他，便开始消化朱河那些深入浅出的金玉良言。

    朱河良久之后，才回过神，笑道：“炼气三境，讲求一个水到渠成，你只要走到那个关口，自然而然就会有所明悟，外人指点已经很难起到作用，而且真正的指点，从来不在大道理上，只在你真正自己走到门口之后，远处的旁人，才能出声为你解释缘由。武人炼气，与养炼兼备的练气士，道路几乎截然相反，以后你会明白的。”

    朱河最后神采奕奕道：“虽然有拔苗助长的嫌疑，但是我还是有些忍不住，想着要将武人传说中最后三境的山顶风光，说给你听一听，省得以后遇上了练气士胡乱嚼舌，都不知道如何反驳。炼神第七境，金身境，是名副其实的小宗师高手了，此境佼佼者，甚至可以修炼出佛家所谓的金刚不败之躯，或是道教所谓的无垢琉璃，金仙之体。更有一些手段，可以让武人以驱使、聘请、祈求三种方式，加持自身体魄，坚不可摧。”

    “第八境，羽化境！武人已经能够虚空悬停，御风而飞。故而又称‘远游境’。远游，远游境，谁说我们武人便粗鄙不堪了，我就觉得远游这个说法，极有余味！”

    “最后一重境界，便是第九境，山巅境，如你我二人身处这棋墩山的最高处，会当凌绝顶，一览众山小。这个境界的武人，又被尊称为‘止境宗师’，用以形容脚下的武道，已经走到尽头！”

    朱河说到这里，干脆站起身，绕着篝火缓缓而行，神色激动，双手握拳，朗声道：“虽不至于搬山倒海那么夸张，却亦是能够拳裂城墙、掌劈大江，一身雄浑罡气，百邪不侵，千军辟易。肉体强横至极，犹胜佛家罗汉之身。练气士一旦被近身，十丈之内，除非有上品护身法宝或者更高，否则必死无疑！”

    朱河眼神炙热，满腔热血，低头凝视着少年，“试想一下，一旦跻身止境，一眼望去，万里河山都在你脚底下，傲视仙人轻王侯，大丈夫当如此！”

    陈平安有些尴尬，一时间不知如何作答，因为少年此刻满脑子都是以后要多练习走桩，多练习剑炉，说不定这辈子就能跻身第三境了，哪里会想得那么远，毕竟仅是答应宁姑娘的出拳百万次，就让少年觉得很是艰难了。

    朱河离去之时，还心情激荡。

    留下一个继续编织草鞋的少年。

    拂晓时分，当阿良打着哈欠起身，结果看到少年位于崖畔，依旧是那枯燥乏味的六步走桩，迎着山风，挥汗如雨。

    一道身影呼啦一下从阿良身侧冲过去，很快就站在那少年身边，陪着她的小师叔，一起打拳。

    阿良喝了口酒，别好小葫芦后，屁颠屁颠跑过去一起凑热闹。

    很快身边就响起小姑娘的教训声，“阿良，你姿势不对唉，这一拳你手臂歪啦。”

    “阿良，你这步子太大了些，收一收，真的，我不骗你，不信你瞧瞧我小师叔，人家多稳。”

    “阿良，你再这样心不在焉，我可真生气了啊！”

    斗笠汉子终于憋屈坏了，忍不住幽怨道：“宝瓶啊，难道昨天那荡气回肠的巅峰一战，你没有发现我才是真正的绝世剑客吗？”

    红棉袄小姑娘认认真真六步走桩，点头道：“知道啊，可是你练拳真不咋的，齐先生说术业有专攻，阿良，你不用觉得丢脸，慢慢来，我保证不说你便是。”

    阿良大步离开，赌气地嚷嚷道：“不练拳不练拳了。”

    阿良蓦然转身，刚好看到小姑娘投来狡黠可爱的视线。

    阿良朝她做了个大大的鬼脸。

    小姑娘不搭理他。

    草鞋少年嘴角翘起。

    阿良远远看着打拳的少年和小姑娘，有些开心，也笑了。

    山风和煦，旭日东升。
------------

next：第一百零一章 坐镇山头

    在一行人吃过早餐即将动身的时候，阿良牵着毛驴，突然让所有人稍等片刻，然后喊了句出来吧，年轻俊美犹胜女子的棋墩山土地，一身飘飘欲仙的大袖白衣，很快就从山巅石坪钻了出来，手里捧着一只长条木匣，弯下腰，对斗笠汉子满脸谄媚道：“大仙，小的已经备好了车驾，余下两百里山路，保管畅通无阻，如履平地。”

    阿良与昨天那个一刀制敌的家伙判若两人，和颜悦色道：“辛苦了辛苦了，东西劳烦你先拿着，等到快要离开棋墩山辖境，你再交给我。”

    年轻土地受宠若惊，“大仙如此客气，折煞小的了。”

    阿良上前一步，拍了拍这位一地神灵的肩膀后，将白色驴子的缰绳交给他，“那就不跟你客气了，还有那匹马，一并由你带去边界。”

    年轻土地大义凛然道：“应该的，为大仙担任马前卒，实乃小人的荣幸。”

    阿良转头看着李槐，小兔崽子方才吃饭的时候，为了跟他争抢一块酱牛肉，一哭二闹三上吊，无所不用其极，卖了他娘他姐不说，如果阿良愿意收下的话，兔崽子指不定连他爹都能卖给阿良，当然了，阿良没有心慈手软，最后气得李槐张牙舞爪就要跟阿良决斗，到现在一大一小还是剑拔弩张的敌对关系。

    阿良伸出拇指，指向自己身后溜须拍马的年轻土地，意思是你小子瞧见没，大爷阿良我在江湖上是很混得开的，以后放尊重点。

    李槐翻了个白眼，扭头往地上吐了一口唾沫。

    阿良没好气道：“动身动身。”

    言语落地片刻之后，就有三只背甲大如圆桌的山龟，依次登顶，它们背甲为鲜红色，如同一大团火焰。当手持绿竹杖的年轻土地望向它们后，山龟同时缩了缩脖子，一物降一物，作为棋墩山名义上的山大王，年轻土地之前碍于修为束缚，数百年间一直无法收拾两条蛇蟒，但是其余气候未成的飞禽走兽，在他跟前，无异于市井百姓圈养的牛羊鸡犬。

    每只山龟背甲皆可容纳三人落座，年轻土地心细如发，在背甲边缘钉了一圈低矮栏杆，材质为就地取材的坚固硬木，充当扶手，以防那些贵客们颠簸摔落。李宝瓶，李槐和林守一，陆续爬上背甲，陈平安被李宝瓶喊到她挑中的山龟背甲上，阿良陪着李槐林守一，朱河朱鹿这对父女自有一块清净地。

    李槐雀跃不已，当山龟动身后，孩子身形仅是微微摇晃，丝毫不显颠簸，竟是比那牛车马车还要舒适许多，虽然看似笨拙，可是山龟下山速度并不慢。

    李槐大乐，使劲捶打阿良的膝盖，“我的亲娘咧！这辈子头一回坐这么大乌龟背上，阿良，你这个缺德鬼总算做了件善事啦！”

    阿良用怜悯的眼神看着李槐，“你能长到这么大，看来小镇民风很朴素啊。”

    李槐转头望向林守一，“阿良是不是说我坏话了？”

    林守一正在闭目养神，好像在默默感受暮春山风的徐徐而来，对李槐的问话，置若罔闻。

    李槐贼兮兮望向阿良，试图从斗笠汉子的脸色眼神当中找到蛛丝马迹。

    阿良板着脸正色道：“是好话。”

    李槐瞥了眼阿良横在腿上的绿鞘长刀，又看了眼他腰间的银色小葫芦，问道：“阿良，竹刀给我耍耍？”

    阿良摇头道：“你不适合用刀。”

    李槐皱眉道：“那我适合啥兵器？”

    阿良脸色严肃，“你可以跟人讲道理啊，以理服人，以德服人。”

    李槐叹息一声，垂头丧气道：“不行的。”

    本来就是逗孩子玩的阿良真正有些奇怪了，“为何？”

    李槐抬起头，望向别处，绿树葱葱，偶有春花绚烂一闪而逝，孩子轻声道：“我嗓门太小，我娘说过，吵架的时候谁的嗓门大，谁就有道理。可是在家里，我爹不爱说话，一棍子打不出个屁，我姐也是扭扭捏捏的软绵脾气，闷葫芦得很，所以家里出了事情的时候，只要我娘不在，爹和姐两个人，就只会大眼瞪小眼，能把人急死。其实我也不喜欢跟人吵架，可是有些时候，坐在墙头看着娘亲跟人粗脖子红脸，就很怕哪天我娘老了，吵不动架了，咋办？我们家本来就穷，连屋子破了个洞也没钱修，我爹没出息，我姐长大后，又是注定要嫁人的，到时候如果连个吵架的人都没了，我们家岂不是要被外人欺负死？”

    林守一神意微动。

    阿良打趣道：“啧啧，屁大年纪，就想这么远？”

    孩子无奈道：“没办法啊，我娘总说家里就只有我是带把的，齐先生教过我们，人无远虑必有近忧啊，所以我必须未雨……那个啥了。”

    阿良笑着帮忙说出那两个字：“绸缪。”

    李槐摇头，“林守一，齐先生说过君子是要如何的？”

    林守一睁开眼睛，缓缓道：“藏器于身，待时而动。”

    李槐指了指阿良，“阿良你啊，就是半桶水瞎晃荡。”

    林守一有点想要坐到陈平安李宝瓶那边去，最少耳根清净。

    阿良摘下酒葫芦喝了口酒，笑呵呵道：“我呢，昨天就跟那个棋墩山土地爷谈好了，分别之时，作为补偿，他和那两头孽畜会拿出一份赠别礼物，之前看到那只长条木匣了吧，江湖人称横宝阁，跟竖立起来的百宝架，有异曲同工之妙，里头装着的全是值钱宝贝，本来说好给你们人手一件，你李槐当然也不例外，现在嘛，没了。”

    李槐不为所动，只是一板一眼说道：“阿良，我知道你肚子里有一百条大船！”

    阿良愣了愣，“什么乱七八糟的。”

    林守一看似随意道：“宰相肚里能撑船。”

    阿良一巴掌摔在李槐脑袋上，爽朗大笑。

    山龟一路拣选僻静山道跋山涉水，轻松惬意，使得一行人优哉游哉，到了一些风景秀美的地方，阿良便让陈平安略作休憩，在此期间，陈平安路过一片竹竿碧绿如玉的小小竹林，就提着那只剩半截的柴刀去砍了两棵竹子，分成一截截长短不一的竹筒，装入背篓，李槐知道缘由，高兴得乱蹦乱跳，嚷着要背书箱喽。

    那三只山龟趴在远处，看着草鞋少年砍伐竹子的时候，拳头大小的黄色眼珠子，充满了钦佩。

    阿良在旁边喝着酒，看着手脚利索的忙碌少年，乐呵道：“眼光倒是不错，只可惜狗屎运……还是没有。”

    上路之前，红棉袄小姑娘跟朱河提出，她要跟朱鹿单独坐在一起，朱河自然不会拒绝，只是叮嘱女儿一定要照看好小姐，朱鹿点头。朱河便去和陈平安坐在同一块龟背上，少年将一节节翠绿欲滴的竹筒，又劈剖削成竹片竹篾，如今欠缺麻绳，所以要竹箱真正成形，最早也要到了那座红烛镇之后了。

    朱河捻起一片竹子，发现入手极轻，却颇为坚韧，想起棋墩山年轻土地手中的那根绿竹杖，顿时心中了然，方才那片不过一两亩大的竹林，肯定不是寻常竹子，说不定正是棋墩山灵气所聚的泉眼地带之一。

    朱河是打心眼喜欢自家小姐的，忍不住提醒道：“这些竹子大有来头，如果是一般的柴刀，早就崩出缺口或是砍到卷刃了。所以等到这两只书箱做成之后，我家小姐说不定会郁闷的，因为到头来反而是她的小竹箱最普通。”

    陈平安愕然，就转头望向身后驮着阿良三人的山龟，试探性问道：“那片竹林是不是跟棋墩山土地有关系？”

    阿良点头道：“算是他的老底子，汲取山地灵气，百年才能生出这种翠绿沁色，再过四五百年，才有希望凝聚出一点点青木精华。不过没事，你砍掉的两棵竹子，只是两百来岁的年龄，还不至于让那家伙心头滴血，最多一阵肉疼而已，屁事没有。”

    陈平安叹了口气，打消了返回再砍一棵绿竹的念头。

    阿良问道：“怎么？嫌两根少了？要不要帮你挑几根好点的竹子？”

    陈平安摇头道：“算了。”

    朱河好奇问道：“来回一趟，不到半个时辰，又不麻烦。”

    陈平安看了眼脚边的背篓，拥簇着一根根竹片一枝枝竹篾，犹有挺大的余地，不过少年仍是摇头道：“赶路要紧。”

    朱河对此不以为意，笑道：“习武一途，重在‘磨砺’二字，不跟人过招，没有人喂拳，练不出大名堂，所以有空的时候，我们切磋切磋，丑话说在前头，说是切磋，可我除了保证不会打伤你，此外出手，绝不含糊，所以你做好鼻青脸肿的心理准备。”

    陈平安满脸惊喜，咧嘴笑道：“朱叔叔你只管使劲揍。”

    不到正午，山龟就已经走了小半程山路，众人在一条瀑布下的水潭旁，分工明确，熟门熟路地烧火煮饭，陈平安就把小竹箱的事情跟小姑娘说了一下，听过了他悄悄告诉她的理由后，小姑娘笑得合不拢嘴，最后脸上满是自豪，拍了拍身旁每天形影不离的小竹箱，跟她小师叔说，天底下最好的书箱就在这里，而且她还给它取了个绰号，叫绿衣。

    吃过了饭，阿良把陈平安喊到幽绿深潭的水畔，瀑布水量不大，故而寒气不重，两人并肩前行，阿良犹豫了一下，问道：“按照你之前的说法，你如今在龙泉县西山一带，拥有落魄山，宝箓山，彩云峰，仙草山和真珠山，总计五座大小山头？”

    陈平安疑惑点头，没有任何隐瞒，缓缓道：“其中落魄山最值钱，宝箓山也不错，其余三座很一般，尤其是真珠山，就是个不起眼的小山包。”

    阿良手心轻轻拍打刀柄，思考片刻后，说道：“如今这些山头的真正价值，在于灵气蕴藉，远胜外方天地，所以我们这一路行来，不单单是那五位化形妖物循着铁符河，试图进入你们家乡，近水楼台汲取灵气，其实还有许多刚刚懵懂开窍的山魈精怪，正向那边飞奔而去，不过最终有哪些幸运儿能够成功占据一隅，得看它们各自的造化，到底有没有大道机缘了。”

    阿良喝了口酒，继续说道：“也别以为有了精怪入山，就是家里遭贼，就像这座气势不俗的棋墩山，那土地为何任由两条蛇蟒在他眼皮子底下，一点一点成长壮大？原因很简单，他被摘去正统身份后，棋墩山想要留住灵气，就需要有人站出来，帮着他坐镇山头、压胜阴煞和吸纳气数。”

    陈平安问道：“阿良，你的意思是要我邀请那位棋墩山土地，或是两条蛇蟒，去往我的山头？有点像是……帮我看家护院？”

    阿良蹲下身，随意捡起一颗石子，丢入水潭，笑着摇头，“你只说对了一半，敕封山水正神，是近期大骊朝廷的重中之重，涉及王朝气数，绝对不容外人染指插手，所以你家乡那些山头，到底有哪几座山峰能够拥有朝廷认可的山神，必然是大骊皇帝御笔钦点的某些死人，准确说来是英灵，棋墩山的土地，去了你的山头，名不正言不顺的，算怎么回事。”

    “再说了，即便你的落魄山或是宝箓山，运气很好，得到朝廷敕封的山神落户，建立山神庙，竖立起泥塑金身，有资格享受香火。但是这里的一方土地，未经钦天监严密审查，如何也做不成落魄山的山神，只有留在棋墩山，说不定还有几分希望，毕竟这几百年来，他没有功劳也有苦劳，更没有闯下什么祸事，说不定大骊皇帝会对他网开一面，在将棋墩山升格的同时，将他顺理成章地一并提拔为山神。所以就算你求他去，他也不会答应的，香火神位一事，对于这些山水神灵而言，就像是凡夫俗子的性命攸关，甚至更重要，因为这条道，只要走出一步，就没有回头路了。”

    陈平安蹲在阿良身边，试探性问道：“是要我拉拢那两条蛇蟒？”

    阿良丢着石子，笑道：“是有些难以抉择，那两条畜生虽然出身不差，但是这些年来作孽不少，传出去名声也不好听……”

    陈平安问道：“如果我准许它们去落魄山或是宝箓山，它们能够保证不吃人吗？”

    阿良愣了愣，揉了揉下巴说道：“吃人？一般情况下，有那么充沛的灵气，修行还来不及，不过蛇蟒终究属于蛟龙之属，生性冷血，偶尔吃饱了撑着吃人尝尝鲜，也说不定。比如什么山野樵夫之类的，运气不好的话，遇上出洞觅食的它们，就难说了。”

    陈平安又问，“那能不能一开始就跟它们说好，在我的山头修行，可以，但是不准吃人，阿良，这样行不行？”

    斗笠汉子反问道：“你就不怕它们嘴上答应，回头进了山，见着了人，一口就是一条人命？反正你近期又不在山上。”

    陈平安神采奕奕，缓缓说道：“阿良你不是说红烛镇有驿站嘛，驿站可以传递书信，我可以写一封信给阮师傅，将宝箓山在内三座山头，多租借给他五十年，如果万一阮师傅嫌少，我可以再加五十年，然后让阮师傅帮我盯着那两头畜生，只要敢伤人，就一拳打死算了，省得留在这棋墩山害人，当然这是最坏的情况。”

    “到时候我让那条有望成为墨蛟的黑蛇，去落魄山待着，年复一年帮我积攒家底，阿良你说过，如果一条蛇蟒，成功走江化龙，那么它最早走江的发源地，冥冥之中也会得到很大的福运，对吧？我甚至还可以厚着脸皮，恳求阮师傅答应我，让它借住在宝箓山，你想想看，万一连白蟒也能走江的话，那我可不就是赚大了，正好我愁着买了山头之后，一直心里没底，如果有了黑蛇白蟒入驻山头的话，估计就会觉得这些山峰没白买，每天都像是有大把铜钱落进自己的口袋，哗啦啦的……”

    阿良一脸呆滞看着滔滔不绝的少年，有些哭笑不得，心情复杂地问道：“陈平安，你就这么喜欢赚钱啊？”

    陈平安满脸震惊，反问道：“天底下难道有不喜欢挣钱的人？”

    阿良扶了扶斗笠，不想说话，省得对牛弹琴。

    这个男人叹了口气，笑道：“本来还以为你小子会义正言辞拒绝的。”

    陈平安一头雾水，“为什么会这么觉得？”

    阿良掬水洗了把脸，转头笑道：“比如会说那两头孽畜杀都来不及，我陈平安虽然穷，但是我老陈家的家风很正，怎么可能愿意让他们进自己家门，噼里啪啦，一大通，我原本已经做好挨训的打算了。”

    陈平安神色安静下来，捡起一颗石子，轻轻抛入水潭，沉默片刻，突然转头拍了拍阿良肩膀，“阿良，你还是太年轻啊。”

    斗笠汉子挑了挑眉头，“呦，看来心情真是不错，都会开玩笑了。”

    陈平安也学汉子挑了挑眉头，竟然给人感觉也挺贱兮兮的。

    阿良哈哈大笑，站起身。

    陈平安跟着起身，突然想起一事，忧心问道：“阿良，关键是那两条蛇蟒真的愿意挪窝吗？”

    阿良笑呵呵，就是不说话。

    陈平安看到斗笠汉子，手心抵住了刀柄。

    阿良拍了拍刀柄，玩笑道：“所以你也赶紧习武练拳，以后再学剑，因为你愿意讲道理，别人不讲道理的时候，就用得着这个了。”

    陈平安不置可否。

    两人一起走回原地，阿良好奇问道：“之前为什么不多砍几棵竹子？这样的好东西，过了这村儿就没这店儿，以后你有钱也买不着。”

    陈平安随口答道：“以前有人说过，人要知足，见好就收。”

    阿良哭笑不得，“就这么句屁话，你还真听进去了？”

    陈平安双手抱住后脑勺，难得这么懒散闲适，脑袋摇摇晃晃，如山林修竹随清风微晃，少年轻声道：“因为我从小到大，就没听过什么大道理啊，所以好不容易听到一两句，想忘记都难。”

    远处朱河突然喊道：“陈平安，咱们找个空地搭搭手？”

    少年撒腿飞奔而去，“好嘞！”
------------

next：第一百零二章 白虹平地起

    竹子一旦抱团成势，只要不经受太多的天灾人祸，很容易成为竹海。

    可棋墩山这片不为人知的小竹林，千百年来始终长势缓慢，哪怕一代代山君和土地小心呵护，始终无法迎来丰年景象。

    此时棋墩山年轻貌美的土地爷，将那根绿竹杖插入脚边的地面，蹲在那两棵被砍断的绿竹旁边，欲哭无泪，悲哀颤声道：“没这么欺负人的，再大的客人，那也是客人啊，哪有这么欺负主人家的，一刀破开阵法，露出这方风水宝地，这跟你们登门做客，眼见那主人家的小闺女，长得亭亭玉立，容颜秀美，便剥去主人家闺女的衣裳，有何两样？有何两样啊？”

    由仙人抓取棋墩山土精、云根所生的黑蛇白蟒，盘踞在竹林外围，两双阴森眼眸之中，浮现出一些通人性的幸灾乐祸。

    一个嗓音在不远处响起，调侃道：“那你家的闺女也太多了点，以后嫁妆都要赔死你。”

    年轻土地悚然起身，哪里还有半点悲苦愤恨神色，跟那斗笠汉子作揖赔罪道：“让大仙见笑了，小的是在这一亩三分地穷苦惯了的，眼窝子浅，比不得大仙游历天下，饱览山河，以大仙的眼力，一定看得出这片竹林对小人而言，实在是压箱底的可怜家当了，所以哪怕只是少了两根青竹，仍是情难自禁，悲从中来，想来也是人之常情，还望大仙恕罪，原谅小人的无心冒犯。”

    去而复还的阿良斜靠一根翠绿修竹，抬头看了眼茂盛竹叶，收回视线，问道：“这片竹子最早的那棵老祖宗，是不是从那座竹海洞天移植而来？然后被你做成了这棵绿竹杖？因此惹恼了某位仙人，一气之下，摘掉了你原本身为棋墩山土地的金身神位？”

    年轻土地这次是当真被震撼到了，脸上的谄媚讨好之意，不浓反淡，悄悄站直腰杆，堂堂正正作揖行礼道：“棋墩山土地魏檗，被前朝神水国末代皇帝敕封为山神，负责棋墩山周围千里地界，后来该换王朝，大骊宋氏崛起，吞并了神水国，在下因为某事惹恼了宋氏开国皇帝，我从山神之位被降格贬为一山土地，统辖之地减少到三百余里，如今仍算是戴罪之身。”

    他提了提手中灵气盎然的绿色竹杖，苦笑道：“福无双至祸不单行，那桩风波之中，我被迫砍伐出自竹海洞天的绿竹，做了这根山杖后，不曾想没过多久，又惹恼了种竹之人的仙家朋友，谈笑之间，就把我这位从土里来的小小土地，重新打回土里去。”

    阿良斜靠绿竹，换了个自认为更潇洒的姿势，啧啧道：“听上去有点惨。”

    年轻土地悻悻然。

    先不理会这位身世悲惨的土地爷，阿良转头望向竹林外边，视野当中，随他一起回来的陈平安站在山坡上，蛇蟒识趣地远远避开，尤其是那头心有余悸的白蟒，眼神极为警惕，阿良笑道：“我这个朋友要跟你们谈笔买卖，你们自己商量价格，谈妥了以后就是朋友，谈不妥也没关系，买卖不成仁义在……”

    说到这里，阿良笑着扶住腰间竹刀。

    阿良从两条庞然大物的身躯上收回视线，有些好奇：“那两条畜生终究不是真正的蛟龙之属，尤其是黑蛇，怎么就成就了墨蛟雏形，生出四趾龙爪？它们是不是有奇遇？”

    自称魏檗的年轻土地小心翼翼回答道：“确有奇遇无误，只是具体为何，小的并不清楚，只猜测与那座骊珠洞天有些关系，它们定是无意间吞食了什么古怪东西，而这种东西对蛇蟒鲤鱼之流，肯定大有裨益，棋墩山边境临近的红烛镇，是水路接通三江汇流之地，其中有条大江叫冲澹江，如今有一条鲤鱼，生出了两缕货真价实的金色龙须，让人艳羡不已，而这条锦鲤在百年之前，曾经顺着河流、溪涧和山泉一路逆流而上，来到棋墩山，我亲眼见过它，照理来说，便是再给它四五百年光阴，也绝无可能生出如此品相惊人的龙须。”

    阿良点点头，恍然道：“这么说的话，那我有点苗头了。”

    年轻土地瞥了眼斗笠汉子的腰刀，试探性问道：““大仙是如何晓得这根青竹杖的根脚？”

    阿良脸色古怪，打了个哈哈，顾左右而言他，“我年轻的时候，游览过一趟竹海洞天，与那竹夫人有些许交情，交情不深，一般，很一般……”

    听到竹夫人这个称呼，魏檗露出满脸神往之色，需知这位夫人是竹海洞天的唯一一位山地神灵，极少露面，外界传言她体态修长，犹胜男子，诸子百家当中小说家的祖师爷，曾经立志要走遍四座天下，记录全天下的风土人情，其中专门就点名写到了这位竹夫人，“美姿容，喜赤足，鬓发绝青。”

    虽说同样是作为山神地灵这一脉的神祇，可魏檗与之相比，无论身份还是修为，相差太远，让魏檗连自惭形秽的心思都生不出来，内心深处唯有敬仰，竹夫人的诸多事迹颇有流传，以至于连东宝瓶洲也不陌生。

    十大洞天之下，有三十六座小洞天，之前悬浮在大骊王朝上空的骊珠洞天，便是其中之一，千里山河的辽阔版图，却只是所有小洞天最小的一座。

    小洞天往往被练气士俗称为秘境，用以区分大洞天，秘境内往往灵气充沛，但是相比十大洞天，其辖境地界残缺不全，前身可能是由旧址废墟，或是龙宫古战场等地构成，来历驳杂，甚至还有名为岛屿洞天的秘境，拥有许多在历史上神秘消失的上古仙岛，竟是在一条远古巨兽吞岛鲸的腹内。

    而竹海洞天，在三十六小洞天当中，名列前茅，盛产各种妙不可言的竹子，为历朝历代的仙家修士所器重，以此制成的种种法器，风靡天下。

    洞天之内，只存在一个地位超然的仙家势力，便是历史悠久的青神山，相传开山老祖曾经向儒家那位至圣先师请教学问，便携带有一棵年幼的功德竹，作为赠礼。之后它在儒家圣地“道德林”茁壮生长，反而是竹海洞天日渐消亡。相传此竹能够记载君子的功德、过失，是市井俗语“功德簿”的来源之一。

    在阿良和年轻土地闲聊的时候，陈平安坐在一块山石上，手里拿着那把半截柴刀，不远处是两颗惊悚恐怖的巨大头颅，对少年对视的头颅之后，蛇蟒身躯如两条山路弯曲蔓延出去，最终消失在山野树林之中，时不时传来树木被尾巴扫中崩裂的声响。

    陈平安一路行来，除了跟李宝瓶读书认字，再就是跟她学大骊官话，进展不错，咬字发音当然还带着浓重的小镇乡音，可寻常的交流，大致意思还是能够说个五六分明白，陈平安就把自己在大骊龙泉县拥有五座山头的情形，跟原本如临大敌的蛇蟒说了一遍，希望它们能够搬家去往落魄山，当然没有忘记把圣人阮师傅跟自己借山三座一事，也跟它们交代清楚。

    很明显，蛇蟒对骊珠洞天坐镇圣人这个身份的轻重，远比陈平安更有概念，就连始终眼神漠然的黑蛇在那一刻，也变了变眼神。一开始白蟒仅是听闻大骊龙泉县这个县名后，就微微有所意动，之后听说大骊朝廷已经派遣了钦天监青乌先生和礼部官员，共同勘察六十余座山头，大骊皇帝准备敕封不止一位的正统山神，白蟒双眼流露出无法掩饰的兴奋激动，忍不住蛇信狂吐，呲呲作响，结果被黑蛇用头颅狠狠撞了一下才安静下去。

    陈平安看蛇蟒并未当场拒绝提议，松了口气，继续说道：“我虽然对于修行一事，了解很少，但是无比确定棋墩山比起我家的那些山头，灵气肯定远远不如，你们在我家地盘上修炼一百年，说不定比得上这里的好几百年，而且阿良在来的路上，跟我说了些蛟鱼蛇蟒走江化龙的内幕，这条水路会走得很艰险，许多山神江神会故意刁难拦阻你们，所以我相信如果你们能够早早跟阮师傅、还有大骊当官的人，打好关系，以后那条路说不定能顺畅许多。”

    这些言语，前半段是陈平安自己琢磨出来的，后半段则是阿良自诩为泄露天机的锦囊妙计。

    陈平安沉声道：“有个教我烧瓷的老人曾经说过，山精鬼魅，山河妖怪，未必就能比人更坏。我看到你们之后，觉得这句话好像没什么道理，但你们是阿良降伏的，跟我关系不大，那么阿良愿意放过你们，我不好说什么。如果我有阿良那本事，你们敢惹上我，敢当着我面胡乱吃人……”

    陈平安提了提手中半截柴刀，死死盯住那条白蟒，“那你就不是只少了一半飞翅，昨天晚上我们的宵夜就是一大罐子炖蛇肉。”

    白蟒失去了飞翅，修为折损严重，本就心疼至极，此时被少年伤口上撒盐，本性冷血的畜生，此刻如人被当面揭开伤疤，勃然大怒，高高抬起头颅，骤然间身躯紧绷，就要向前扑杀这个碍眼可恨的少年。

    陈平安无动于衷。

    黑蛇随之而动，不是帮着白蛇对付草鞋少年，而是对着白蟒张开大嘴，迅猛咬住对方的脖颈，往后一甩，将那条身躯只有一半的“纤细”白蛇，狠狠摔了个七荤八素。

    年轻土地吓了一大跳，正要出手，让白蟒黑蛇安静下来，以免少年被误伤，自己也被两头畜生殃及池鱼，却听那斗笠汉子摇头轻声道：“别插手。”

    年轻土地有些疑惑，忍不住看了眼汉子，只见他依然斜靠着绿竹，一只脚尖点地，站姿慵懒，双手环胸，神色平静。

    本是同类的蛇蟒展开凶狠对峙。

    陈平安站起身，只是没有离开石块，紧握柴刀。

    不知是相互交流了什么，白蟒终于逐渐安静下来，但是它望向少年的视线，依然凶悍异常。

    陈平安就这么跟白蟒直直对视，“如今有成千上万的人在山里开山修路，你们进入山头修行后，不可为了饱腹而杀人，当然如果是出于自保，比如有修行之人进山捕杀你们，另当别论。如果你们得了好处，却坏了规矩，那么阮师傅就会出手。你们之前做了什么，跟我无关，但是如果答应进山，那么你们之后做了什么，就跟我有关。”

    陈平安一本正经道：“所以我先把丑话说在前头。”

    黑蛇保持原状，寂静不动。

    白蟒仿佛气愤难消，虽然放弃了撕破脸皮的冲动，但哪怕大道之诱就在眼前，白蟒仍是以腹部缓缓摩擦着地面，浑身散发出急躁暴戾的气息。

    远处竹林内，阿良不知何时坐在了一根竹子上，韧性极好的一棵绿竹，硬生生被他压塌成了拱桥模样。

    恨不得用双手托起绿竹的年轻土地，瞥了眼少年与蛇蟒暗流涌动的悬殊对峙，解释道：“黑蛇虽然生性更加残忍凶狠，但是开窍更多，甚至已经学会懂得看形势，知道进退，那白蟒平时看起来伤人的念头不重，但是交流起来反而比较麻烦，因为更顺从本心。这跟它们当时在棋盘上的位置形势有关，白蟒只是一颗闲子，黑蛇却是屠大龙的关键所在，所以它们在棋墩山占山为王这么多年，白蟒喜好四处逛荡游走，许多风波，多是它的出行动静惹起，倒是黑蛇更专注于修行，每天勤恳吸纳日精月华，因为志向远大，野心勃勃。”

    阿良嗯了一声。

    年轻土地犹豫了一下，说道：“这少年的言语是不错的，都是实实在在的道理，只不过仍是不够了解那对蛇蟒的习性，对于踏上修行之路的它们而言，本心本性是大道之基石，除此之外，开窍的蛇蟒大抵上，知道颜面一事了，在棋墩山作威作福惯了，会觉得去了那少年的山头，就是寄人篱下，尤其是少年搬出一位圣人来，扬言敢吃人就打杀了它们，更会让蛇蟒觉得少年气势凌人，不好相与，难免愤懑，毕竟一旦点头答应，就是动辄数百年的‘街坊邻居’了，会担心自己遇人不淑……”

    阿良打断他的絮絮叨叨，“你不用变着法子帮你邻居求情，既然说过我不会插手，你怕什么？归根结底，蛇蟒不愿早早低头，还是觉得那武道二境的少年，根本没资格跟它们平起平坐罢了，所以哪怕少年提出的要求，都很合情理，它们也会难以容忍，如果换成我，你觉得蛇蟒会怎样？”

    年轻土地讪笑道：“大仙看人看事，洞若烛火。”

    阿良淡然道：“回答我的问题。”

    年轻土地一瞬间噤若寒蝉，一番酝酿措辞后，认认真真回答道：“它们会二话不说，直接搬家！连心怀怨恨也不敢！”

    阿良脸色如常望向那边，点了点头，“很好，你保住了半片竹林。”

    两人四周的竹林，传出一阵阵噼啪作响。

    竟是约莫半数绿竹，好像被人一刀拦腰斩断，悉数摔落在地面。

    年轻土地跪拜在地上，战战兢兢颤声道：“大仙息怒。”

    阿良根本懒得理睬这个家伙，脸色冷漠，缓缓道：“看吧，哪怕出过手吓过人了，就只是因为太好说话，脾气太好，就会被一个小小土地当做傻子糊弄，所以说啊，当个好人，很难的。”

    年轻土地大气也不敢喘。

    阿良突然笑呵呵说道：“起来说话，跪着不像话。我跟你打个赌，赌那财迷少年，愿不愿意做一笔亏到姥姥家的买卖，你赌他愿意，我赌他不愿意。你赌赢了的话，就可以保住剩下一半的竹林，赌输了的话，你不是刚刚恢复土地之身吗？我把你打回原形好了。”

    刚刚站起身的年轻土地，此刻想死的心都有了，喃喃问道：“敢问大仙，小人的赢面有多少？”

    阿良伸出一根手指。

    年轻土地面无人色，十分之一的胜算。

    那斗笠汉子咧嘴笑道：“是百分之一。”

    然后阿良望向少年，大声喊道：“陈平安，只管狮子大开口，条件怎么过分怎么开，有我阿良盯着呢，别怕惹火了那两头畜生，如果真发生了冲突，刚好拿那双蛇蟒练练手，放心，我会帮你看着局势的，适当的时侯，肯定会出手。先前你不是跟五境高手朱河切磋过吗，交手之后，你小子分明是有所领悟了，干脆趁热打铁，说不定就能百尺竿头更进一步了。”

    年轻土地呆若木鸡。

    阿良笑道：“不好意思，你现在连那一点胜算也没了。”

    年轻土地心死如灰，反而生出了一些额外的胆识气魄，转头苦笑道：“阿良前辈，你的赌品，真的不太好。”

    斗笠汉子说了一句古怪言语，“折腾来折腾去，就为了一个必赢的局面？你觉得我阿良有这么无聊吗？”

    年轻土地细细咀嚼这句话，再次看向名叫陈平安的少年，既有羡慕，也有怜悯。

    片刻之后。

    一道足以撼动山岳的剑气白虹冲天而起。

    年轻土地吓得一屁股摔坐在地上。

    斗笠汉子的身影，瞬间从拱桥形状的绿竹竿上消失，来到棋墩山高空，腰间绿鞘竹刀迅猛拔出，将白虹一刀劈断，不让其继续升空而去。

    又片刻之后，阿良坐回来那棵尚未绷直的竹竿上，随手丢掉那柄普通材质的破烂竹刀，虽未折断，整把刀的刀身却已破烂不堪。

    黑蛇往棋墩山密林深处疯狂逃窜。

    少年身前不远处，那条毫无征兆向前扑杀向他的白蟒，此时此刻已经失去了整颗头颅，露出血肉模糊的残断脖颈，触目惊心，惨绝人寰。

    陈平安脸色平静，咧咧嘴。

    眼神如当初小巷击杀云霞山蔡金简，如出一辙。

    阿良忍住笑意，摘下腰间小葫芦，狠狠灌了口酒，低声笑道：“有点意思了。”
------------

next：第一百零三章 竹楼

    那棵绿竹猛然绷直，原来是阿良跳落地面，伸手将那位棋墩山土地爷拉起身，啧啧笑道：“我的赌品不好，可是你的赌运很好。”

    年轻土地脸色雪白，愁眉不展，虽说劫后余生，总算保住了仅剩的半片竹林，可当他看到远处那条头颅被崩掉的白蟒，年轻土地不由得百感交集，数百年来毗邻为居，虽是恶邻，摩擦不断，但大体上还算相安无事，最少从未有过生死搏杀，今天蛇蟒本该即将踏上修行的阳关大道，偏偏在这种的时候，被人以凌厉剑气炸碎头颅，带给他的震撼力之大，可想而知。

    年轻土地叹息一声，颓然作揖，轻声道：“就如前辈所认为的，我这般市侩小人，是三天不打上房揭瓦的低贱性子，不过如今委实是一顿揍就饱了，还望阿良前辈可怜可怜小人，实在是吓破胆子了，再无半点心气，接下来阿良前辈只管发话，小人一定照办。”

    阿良没有故弄玄虚，低头看了眼空落落的绿竹刀鞘，点头道：“你拣选一根好点的老竹，我要换一把竹刀，就当是你的朋友赠礼了。再就是这么多莫名其妙掉在地上的竹子，老大一堆，浪费了总归不好。”

    土地爷魏檗嘴角抽搐，只敢在心中腹诽，阿良前辈你这叫丧尽天良啊，阿良你大爷的良。

    阿良揉了揉下巴，“我那朋友做了笔亏本买卖，间接帮你赢下半座竹林，做人要厚道，有恩就报恩，你意下如何？”

    魏檗苦笑道：“理当如此，天经地义。”

    陈平安拿着半截柴刀跑去白蟒尸体那边，砍下了剩下一只飞翅，晶莹剔透，与人手臂等长，摸在手里，冰凉如雪，日光照耀下，不断闪现出一阵阵流光溢彩。阿良之前闲聊说过，这头白蟒身上最值钱的物件，除了蛇胆便是飞翅，价值连城，且有价无市，其余蟒皮筋骨等物，虽然也稀罕值钱，但比起前两者的珍贵程度，天壤之别。

    陈平安将柴刀系挂在腰间，一路小跑向竹林，结果看到年轻土地正在弯腰半蹲，双手将一棵绿竹倒拔而出，地底下碧青色的竹鞭盘根交错，牵一发而动全身，随着绿竹被拔出泥地，附近土壤纷纷被竹鞭牵带着溅射而起。

    看到“杀人越货金腰带”的草鞋少年后，满头大汗的年轻土地，下意识咽了咽口水，然后他将怀抱绿竹轻轻放回土中，低头四处张望，最后选中了一段粗如稚童手臂的幽绿竹鞭，叹了口气，抬起头望向陈平安，笑容牵强问道：“能不能把柴刀借我一用？”

    陈平安走近，将半截柴刀递给年轻土地，后者手握柴刀，深呼吸一口气，砍下那截竹鞭后，递给阿良，阿良摇头笑道：“你照我之前竹刀的样式做一把，回头离开棋墩山边界的时候，连同那头白驴，一起给我就是了。”

    魏檗自然不敢不答应，之后把柴刀还给陈平安的时候，由衷感慨道：“好锋利的刀刃。”

    陈平安接过柴刀，想了想，说道：“你想要的话，我可以送你，反正这半截柴刀不适合开山带路，我拿着也没什么大用处。”

    魏檗干笑道：“君子不夺人所好。”

    阿良笑呵呵道：“想要又不好意思白要，那可以买嘛，童叟无欺，公平买卖，对不对？”

    魏檗一脸“恍然大悟”，站起身后搓掉手上泥土，对陈平安笑着说道：“若是经常进山的山民樵夫，就会知道如果一座竹林过于茂密，反而不利于竹子的生长，疏密得当，竹林才能壮大，所以必须砍掉一些，而且这片竹林真正值钱的部分，在地下与山根相连的竹鞭，而不在地上的竹竿，方才便趁此机会，跟阿良前辈借了竹刀一用，砍下一些多余竹竿，原本想着是搭建一座小竹楼，作为闲暇时分的休憩赏景之用。”

    年轻土地越说越顺畅，“现在阿良前辈的竹刀被我砍坏了，说来惭愧，我从第一眼看到起，就垂涎你手中半截柴刀，要不然我竹刀也做，竹楼依旧搭建，回头竹刀可以早早交给阿良，只是小竹楼，恐怕会晚一些才能落成，到时候黑蛇前往龙泉县落魄山的时候，我会一并随行，既是避免它一路北去，惹出什么麻烦，同时可以让它驮着这些竹子，我到了落魄山后，便找一处山清水秀、风景宜人的地方，为你搭建竹楼。”陈平安望向阿良，斗笠汉子笑着解释道：“竹海洞天有十棵最重要的仙竹，竹有十德，仙竹与之对应，这片竹子的老祖宗是其中‘奋勇竹’的子嗣，此处竹林里的这些徒子徒孙，也沾了光，若是搭建成一栋竹楼，常年身处其中，修行打坐，对于纯粹武夫或是兵家修士，都大有益处。”

    魏檗连忙附和道：“对，此处竹林皆是那棵奋勇仙竹的子嗣，史书记载‘兵威已振，譬如破竹，数节之后，迎刃而解’，暗合此意。故而在竹楼之内修行，必然极其滋养魂魄。”

    陈平安正要说话，阿良快步上前，搂住少年肩膀就往竹林外走去，“盛情难却，客随主便，走了走了。”

    陈平安小声道：“柴刀还没给人家。”

    阿良大大咧咧道：“回头连背篓里的那半截刀刃一并给他。”

    之后这位斗笠汉子不忘回头提醒道：“那颗尚未成形的白蟒之胆，就不要了，鲜血淋漓的，太吓人，连同蟒肉一并交给黑蛇吞食便是，如此一来，哪怕没了一对飞翅，依然能够让它增长两三百年修为，就当是我们的诚意了，记得要它到了落魄山落脚后，老老实实修行。”

    最后阿良伸手凌空虚点，指了指失魂落魄的年轻土地，“好自为之。”

    年轻土地站在竹林边缘，望着两人的背影，林间山风，穿过一棵棵绿树一丛丛红花，带着沁人心脾的花木清香，貌美如尤物的年轻男子，手持象征身份的山君绿竹杖，白衣飘飘，大袖飘摇，先前的震惊、畏惧、焦躁和仿徨，随着清风一扫而空，取而代之是与一地神灵身份相符的庄重肃穆。

    他环顾四周，轻声感慨道：“福祸相依，不过如此了。感谢阿良前辈的无心提点，帮我解开心结，破去魔障。”

    年轻土地闭上眼睛，嘴角含着温煦笑意，呢喃道：“自古名山待圣人，圣人不来又何妨，我自可潜心成圣。”

    等到睁眼之时，俊美男子耳畔多出了一枚淡金色耳环，精致圆环随着山风微微摇晃，衬托得年轻土地恍如山岳正神。

    两人原路返回水潭，不同于来时的飞快奔走，此时两人默契地选择散步闲聊。

    “阿良，黑蛇真的会吃掉白蟒残余尸体？它们不是相依为命几百年的伙伴吗？”

    “那志在成蛟化龙的黑蛇，当然下得了嘴，不光是蛟龙之属，其实一切山精鬼怪魑魅魍魉，皆以食为天，只不过栖息在山林大泽的蛟龙蛇蟒，尤为同类相残，这跟一山不容二虎是差不多的道理，黑蛇之所以留着白蟒，是开了窍，灵智增长，未尝没有等它结丹再饱餐一顿的想法。对了，你要是想看黑蛇吞吃白蟒的景象，咱们可以回头。”

    “这就算了吧。”

    “话说回来，别怪我替你擅作主张，答应那黑蛇吃掉那颗蟒胆，既然它接下来去落魄山帮你坐镇气运，那么一颗蟒胆由你卖掉，价格卖得再高，也不如黑蛇早点成为墨蛟来得划算。”

    “我其实很好奇你为何要杀掉白蟒，为何不等我出手阻拦？驯服了白蟒，随便让它去宝箓山或是彩云峰都是不错的买卖。难道你是怕我阿良见死不救？”

    “怎么可能，阿良，我信得过你。”

    “那你？”

    “阿良，回答你的问题之前，我也想知道，你是不是在我和朱河切磋的时候，就看出我当时找到了……那三座窍穴？以及窍穴之内的真相？”

    “说实话，我一开始就知道那三座窍穴内有古怪，大有玄机，但说出来比较丢人，就连我也看不真切，只能猜出是蕴藉有三种道意的丝缕剑气，具体为哪三种，则不敢确定，当然，我如果想要强行观看气府里边的景象，不惜伤害你的体魄气机，丝毫不难，只是那么一来，就很下作了，我阿良身为绝世高手，自有高手的风范气度。”

    “明白了。阿良，你知不知道我们小镇有座牌坊，上边有四块匾额？”

    “知道有这回事，齐静春当年跟我提起过，但是我没记住内容，早忘了。”

    “其中有一块匾额，写着四个字，莫向外求。我隔壁有个同龄人，读书很多，他说这是佛家的禅机，意思是说告诫所有人，要专修佛法，不要去跟那些佛法之外的旁门外道去求什么。我一开始觉得很有道理，但是后来我在山上烧炭，没事的时候，反正就是一个人无聊了瞎琢磨，觉得对我来说，烧香拜佛也好，礼敬菩萨也好，都要自己先做到力所能及的事情，如果仍是达成不了心愿，实在没办法了，再去求，菩萨才会点头答应，要不然人家菩萨凭啥帮你啊，对吧，阿良？”

    “求佛先求己。”

    “对对对，我就是这么个意思！”

    “嗯，这么解释的话，勉强说得通。但是我得跟你说明白一件事，我阿良从指甲缝里抠出一点来，也比你的家底厚实。所以你觉得很麻烦我，便宁愿损失一道剑气？事实上对我阿良来说，就是一次随随便便拔刀出鞘的小事情。这个账，你得这么算。”

    “不能这么算！”

    “嗯？”

    “教我烧瓷的姚老头，很少愿意跟我说话，但是有两次把话说得特别重，我记得很清楚。第一次是我当窑工学徒，他说跟我学烧瓷，可以，但你只要敢偷一次懒，就给我滚出龙窑。第二次是我跟他头回进山，他说跟我进山找土，可以，但不管是摔断腿了还是怎么，你只要敢当着我的面哭一次，以后就别再进山。”

    “这是哪跟哪啊，陈平安你啥意思？”

    “那我换个说法，阿良，你喜不喜欢睡懒觉？”

    “废话，你不喜欢？”

    “我也喜欢啊，但是说出来你可能不信，我在当窑工学徒的第一天起，直到今天，我没有睡过一次懒觉，该什么时候起床，我睁眼就起床，所以一次懒觉也没有。”

    “绕这么大圈子，你到底想说啥？欺负我阿良不是读书人？”

    “我的意思，就是任何自己觉得不好的事情，就干脆不要有第一次，一次也不要做，一小步也不能走出去，要不然回头来看，吃亏吃苦的还是自己。就像我，如果偷懒一次，肯定就做不成窑工学徒，更进不了大山，那么哪里能有今天的光景？说不定我现在跟那几千小镇青壮差不多，进山开路，伐木搭桥，每天领一些铜钱，就这样了。怎么可能有五座山头？五座山头，有多少值钱，阿良你知道吗？阿良，以后有机会你一定要去我山头看看……”

    “打住打住！陈平安，你跟我兜这么大圈子，就为了显摆自己阔绰有钱啊？”

    “阿良，你果然没读过书。”

    “……”

    “阿良，以后我的落魄山，如果真的多出一栋竹楼，你给帮忙取个名字吧？”

    “‘阿良很猛楼’，如何？气势够不够？怎么，嫌弃喧宾夺主，压过你这位山大王的风头？行吧，那我换一个含蓄些的，就叫‘猛字楼’，我阿良牺牲很大的，还不满意？”

    “阿良，我突然觉得竹楼没有名字也挺好的。”

    斗笠汉子翻了个白眼。

    陈平安哈哈大笑，“放心，就叫猛字楼好了。”

    阿良突然转头问道：“你想不想学剑？”

    陈平安摇头道：“暂时不想。”

    阿良会心笑道：“是怕分心？耽误了练拳？”

    陈平安叹了口气，点点头。

    阿良知道少年为何叹息，当初在棋墩山山巅，少年为了阻拦白蟒扑杀李家婢女朱鹿，将原本一路走桩练拳辛苦积攒下来的本钱，全部挥霍一空了，如果说原本像是手头有点余钱的小门小户了，结果一下被打回原形，再度家徒四壁，从屋门到窗户都是破败漏风的惨淡光景。

    所幸走桩是健壮身躯体魄，是迫在眉睫的活命之举，而立桩剑炉，则能够滋养魂魄，在那石坪一役当中有所突破，为之后跟朱河切磋武学的时候，少年能够顺势精准找到三座剑气所藏的窍穴，做了铺垫。

    阿良打趣道：“少了一缕这么厉害的保命剑气，心疼不心疼？”

    陈平安毫不犹豫道：“不心疼，我之前积攒在心里头的一口气，总算出了。现在痛快得很。”

    阿良笑道：“说说看。”

    陈平安望向前方，“我愿意跟人讲道理，又能够让别人听我讲道理，这感觉，很好！以前我练武是为了强身健体，或者说就是为了活命，但现在觉得目标可以再远一点，再高一点！”
------------

next：第一百零四章 坐地分赃

    在棋墩山土生土长的灵物山龟，自然熟悉捷径山道，加上翻山越岭的脚力远胜驴骡，驮着一行人，很快就来到棋墩山边界地带，再往南走上二十数里下山的驿路，就能够进入红烛镇，虽说如今这条北上的驿路，因为骊珠洞天的突然下坠而阻塞断绝，但是陈平安一伙人仍是选择小心起见，不希望三只巨大山龟惊扰到樵夫猎户或是行脚商贾。

    陈平安他们在小山之巅小坐休憩，李槐翘首以盼，他对那年轻土地厌恶至极，但是阿良说那横宝阁里藏着宝贝，人手一份，李槐对此很是期待，心想着以后见到姐姐李柳，一定要眼馋死她。

    那位棋墩山土地爷很快如约而至，这次没有用缩地成寸的神通，大步上山，白衣飘摇，大袖像两朵白云漂游而上，便是婢女朱鹿看到这一幕，也不得不承认若是只看皮囊，年轻土地当得起书籍上“丰神俊朗”的形容。

    俊美男子身后还跟着阿良的白驴和李家马匹，也不知道这位土地爷使了什么法术，不但跟上了大队伍，驴子马匹竟然看不出半点疲惫。

    不知活了几百年的魏檗横抱长条木匣，先向斗笠汉子作揖行礼，后者点头还礼。

    城府深沉的一地神灵，玩世不恭的奇怪剑客，在这一刻给人的感觉，竟然如出一辙。

    大道同行。

    魏檗将不知什么材质的鲜红木匣递交给阿良，李槐赶紧过去摸了一下，手心满是暖意，触摸上去，像是骑龙巷一家布店作为镇店之宝的上好绸缎，去年年关他跟随娘亲姐姐一起去买布料，裁剪新衣，他只不过是偷偷摸了一下那块绣有花鸟的漂亮锦缎，就被气急败坏的店家轰了出去。

    李槐抬头问道：“阿良，跟你商量个事，分过了盒子里的宝贝，最后这盒子能不能送给我？”

    阿良反问道：“你算哪根葱？”

    李槐认真道：“你娶了我姐，我是你姐夫啊。”

    阿良一巴掌摔过去，“那叫小舅子！”

    孩子突然说道：“我不要做小舅子，我喜欢当姐夫，天底下最坏的人就是小舅子。”

    阿良望向魏檗，问道：“盒子值钱吗？”

    魏檗讪讪笑道：“还好，是娇黄阴沉木打造的物件，在土里埋了有些年头，不腐反香，色泽也由黄变红，东西不算值钱，就是不常见而已。”

    阿良低头看着满脸希冀神色的孩子，“既然东西不值钱，就送你了。”

    李槐火急火燎就要拿走木匣，又被阿良一巴掌打得晕头转向，“想独吞？”

    阿良环顾四周，伸手招了招，然后蹲在地上，打开名为“娇黄”的长条木匣，高声喊道：“陈平安，小宝瓶，林守一，朱河，朱鹿，都过来都过来，坐地分赃，坐地分赃了！先到者先得，过时不候，没其它规矩，就一条，每人只能从百宝阁拿走一件，拿到哪样是哪样，不许反悔。”

    陈平安望向年轻土地，后者察觉到少年的视线，有些疑惑，温声问道：“你不去争夺机缘吗？”

    陈平安笑道：“让他们先拿就是了。”

    陈平安正好有事情要跟年轻土地商量，关于黑蛇在落魄山的定居事宜，以及魏檗离开此处地界前往龙泉县辖境的情况，回来的路上，阿良大致说过关于山水正神的讲究，不可轻易离开朝廷在山河谱牒上敕封的版图，这有点类似许多王朝订立下来的“藩王之间不可相见”，一旦有谁犯了忌讳，那些神灵轻则被朝廷申饬，减少香火供奉，重则被降低神位，在多少年间彻底断绝民间香火，历史上还有许多逾越规矩的山水神祇，下场更加凄凉，金身神像被朝廷拉出神龛，拽下神台，衙役以威武棒棒打，以儆效尤，或是地方官员亲自鞭打，甚至是直接派遣民夫抡捶打烂，各国历史上都有发生。

    所以魏檗说要亲自带着黑蛇去往落魄山，还会以那些奋勇竹在山上搭建出一栋竹楼，陈平安当然不会拒绝好意，但也不希望魏檗因此而遭受重罚。其实少年对于神道香火、山川风水和王朝气运一事，之前始终无法深刻理解，这跟阿良没读过书也有关系，这家伙踩着西瓜皮说到哪里是哪里，说得十分云遮雾绕，有些故意为了显摆还喜欢卖关子，本来没什么古怪玄机的粗浅事情，也能被他说得玄之又玄。

    后来是李宝瓶举了个例子，陈平安的念头才豁然开朗，小姑娘说那些香火气数什么的，就像是小镇外的龙须溪，水源就这么一条，百姓为了各自庄稼地的收成，就会争水，几乎每年都会出现大规模斗殴。

    李宝瓶跑到陈平安身边，着急道：“小师叔，你怎么不去拿宝贝？你看连林守一那种性子的人都跑得飞快，李槐更是恨不得把脑袋塞进百宝阁里去了。”

    陈平安随口说道：“没事，我最后一个选好了。”

    李宝瓶转身就跑，“没关系，小师叔我帮你选一件。”

    陈平安正要说话，红棉袄小姑娘已经杀到阿良身边，一手按住李槐脑袋向外一推，一手推开林守一肩膀。

    李槐委屈道：“李宝瓶，你欺负人！”

    李宝瓶转头理直气壮道：“我给小师叔挑东西！”

    李槐想着尚未到手的小竹箱，叹了口气道：“那你挑吧。”

    林守一被推开也不恼，伸手指了指百宝阁内一本卷起的泛黄古籍，它被一根金黄色丝线捆绑，刚好露出云篆写就的书名，“我挑中了这本道家书籍，叫云上琅琅书，我只要它，不跟你们抢其它的东西。”

    李槐身体前倾伸长脖子，微微绕过李宝瓶，问道：“守一，你怎么不挑那把刀，多漂亮，要是我就选它。”

    林守一费了很大的劲，眼神才好不容易从占据百宝阁最大地盘的一把狭刀上挪开，轻声道：“我又不是习武的料，自己也不喜欢练刀学剑。”

    李槐见林守一不愿意更改初衷，就开始劝说李宝瓶，“这把刀，一看就是天下无双的神兵利器，吹毛断发算什么，我估计它连咱们小镇铁锁井的铁链也能一刀砍断，李宝瓶，这么好的东西，你真不要？再说了，你的小师叔如今不是趁手的兵器吗，我看这刀给他用挺好，退一步说，拿它来进山开路，多威风，总比拿着一把破柴刀更好吧？”

    那把狭刀，哪怕如大家闺秀藏身绣楼，它安安静静躺在白色刀鞘内，弧度漂亮到惊艳的地步。

    阿良笑着弯腰抽出狭刀。

    锋芒毕露，刀身就像一抹滞留人间的白虹。

    刀身并无铭文，却有一缕缕天然纹路，如道家仙人用心篆刻的祥云符箓。

    阿良微微讶异，屈指一弹，并非浑浊的嗡嗡作响，反而颤音清越悠扬，阿良侧耳聆听片刻，点头道：“不错，应当是那把垫底的‘祥符’。”

    阿良收刀入鞘，把它递给小姑娘，笑道：“收下吧，这把刀适合你，以后再寻一只养剑葫芦，与这祥符刀，一左一右悬挂腰间，找一匹高头大马，穿一袭红衣，独自策马行走江湖，纵马饮酒，谁见到谁喜欢。”

    阿良开怀大笑，“谁会不喜欢这样的姑娘呢？”

    李宝瓶怔怔拿着入手沉重的狭刀。

    朱河也蹲在附近，朱鹿原本不想过来，还撂下一句赌气话，说她不稀罕这份嗟来之食，但是被父亲一个严厉眼神瞪住，之后便被他强行拉来，这是少女第一次见到她爹生气，她有些害怕，可她始终不愿朱河一样蹲下身，倔强地站在那里，脸色清冷。

    李槐趁着李宝瓶不注意，一把抓起一只手掌长短的彩绘木偶，做工精美绝伦，栩栩如生。

    这才是他一见钟情的物件。

    林守一轻轻拿起那本卷起的道家古籍，握在手心后，性情内敛的少年，破天荒流露出满是欢喜的神色。

    朱河挑中一本书和一颗泥封丹药，然后满脸震撼地抬头望向斗笠汉子，后者笑呵呵道：“怎么，刚好是你和你家闺女用得着的东西？别谢我，要谢就是魏檗和那蛇蟒，千百年来，辛苦积攒下来的家底够雄厚，拿得出一部出自仙家府邸的武学秘籍，和一颗出自真武山的独门丹药。”

    朱河掌心托着那粒丹药，颤声道：“阿良前辈，真是传说中的‘英雄胆’？”

    阿良不再理会欣喜若狂的朱河，抬头望去，陈平安和魏檗并肩走来，后者看到百宝阁内仅剩的一粒淡金色种子，以及李宝瓶手中的狭刀，年轻土地神色平静，然后当他看到其余人手中的书籍丹药，愣了愣，不由得望向斗笠汉子，后者视而不见，对陈平安笑道：“就剩下这么一粒玩意儿了，不过估计你小子早到晚到都一样，只会拿到这么颗莲子。”

    看到那颗孤零零的淡金色莲子，陈平安蹲下身，笑着拿起来收入袖中口袋。

    李宝瓶轻声道：“小师叔，我跟你换。阿良说这把刀可好了……”

    说到这里，小姑娘赶紧闭上嘴巴，满脸后悔，显而易见，她后半句话不该说的，果不其然，陈平安摸了摸她的脑袋，“好就收下啊，小师叔又不练刀，进山开路用柴刀就很足够了。”

    阿良打趣道：“对嘛，陈平安是一名剑客，佩刀不合适。”

    陈平安没好气道：“那你还用竹刀？”

    阿良耍无赖：“你管我？”

    李槐轻声道：“阿良，这匣子归我了，对吧？”

    阿良问道：“你要这盒子干啥？你有那么多宝贝家当放吗？”

    李槐还以颜色，“你管我？”

    一行人各有所得，就连年轻土地魏檗和黑蛇亦是如此，除了那条头颅被炸身躯被吃的白蟒，可谓皆大欢喜。

    陈平安是一粒略显干瘪的淡金色莲子，拇指大小。李宝瓶得到了那把名叫祥符的狭刀，却有些闷闷不乐，有些嫌弃地将它斜靠在小书箱内，不过按照小师叔的建议，用了一块棉布从头到尾包裹住狭刀，严严实实，并不外露。

    李槐拿到了彩绘木偶和娇黄木匣，前者暂时“借住”在李宝瓶的书箱内，放入箱子之前，孩子很是恋恋不舍，对那个木偶口口声声拍胸脯保证，等到自己也有了书箱，就让它搬家，保证宽敞。林守一贴身收藏了那本云上琅琅书，名字奇怪，古意十足。

    朱鹿虽然不情不愿，仍是收下了那本仙家秘籍，紫气书。

    朱河则如久旱逢甘霖的幸运儿，一个十分稳重的汉子，笑得怎么也合不拢嘴，并非朱河，而是他太过幸运，现在给他一座金山银山，也不如一颗有钱也买不到的真武山英雄胆，此药能够帮助服药之人凝聚四散于窍穴气府的魂魄，最后结出一颗方便阴神栖息的“宅子”英雄胆，朱河不是练气士，更不是兵家修士，但是英雄胆的昂贵珍稀，恰恰在于它同样适用于纯粹武人，尤其是第五境巅峰停滞不前的武夫，取得一颗英雄胆，简直等于多出半条命。

    阿良轻声问道：“跟土地爷聊得如何？”

    陈平安笑道：“挺好，那袋子东西也送出去了。”

    阿良啧啧道：“你倒是不含糊，说送就送。我之前不过是随口一说，再者如果在商言商的话，你其实应该当一笔生意来做的，相信以那黑蛇白蟒的家底，它再吝啬小气，都会心甘情愿送你一件真正的好东西。”

    陈平安道：“肥水不流外人田，以及春种秋收的道理，我还是懂的。”

    阿良点了点头，扶了扶斗笠，“很快就要到红烛镇了。”

    然后这个男人抹了抹口水，“新酿杏花春，胭脂小画舫，我阿良又回来啦！”

    对于阿良惺惺念念的红烛镇，陈平安突然有种不祥的预感。

    魏檗望着那一行人的下山背影，叹了口气，脚尖一点，掠向一只山龟的背甲顶部，盘腿而坐，行出数十里后，腹部鼓鼓的黑蛇与它遥遥结伴而行，虽然体态臃肿不堪，可是气势暴涨，凶悍异常。

    魏檗忽然一笑，朝它丢出一只袋子，凑巧落在它行进路线上，黑蛇小心翼翼垂下头颅，嗅了嗅，并无异样，它转过头颅望向山龟上的那位神仙中人。

    神采宛如谪仙人的俊美土地笑道：“算是那少年送你的乔迁之礼。”

    腹部生出四爪四趾的黑蛇，略作犹豫，最终用牙齿扯破袋子，滚出十数颗少年从龙须溪中拾取的蛇胆石，在小溪之中的色泽皆已褪去，乍一看，与普通溪涧河水当中的鹅卵石，没什么两样，但是黑蛇近距离凝视一番后，眼神灼热，同时充满了忐忑，生怕自己下一刻就要迎来失望，它缓缓吐出蛇信，试探性卷起一颗石子入嘴。

    年轻土地看到这一幕后，驾驭着山龟继续前行，自言自语道：“一桩善缘善始，就是不知道能否善终。”

    身后黑蛇片刻之后，四爪抓地，仰头望天，传出一声嘶吼，响彻山峰，惊起无数振翅远去的飞鸟。

    哪怕是年轻土地都有些羡慕，“听说如今除了骊珠洞天，此物在东宝瓶洲几乎已经绝迹，蛟龙之属，食之可生出真龙之筋骨须鳞。”

    临近红烛镇，白色毛驴在青石板驿路上，踩踏出滴滴答答的清脆声响，阿良没有牵着驴子的缰绳，它自己就会跟随其后，阿良依稀听到那声吼叫后，笑道：“看来还真有用。”

    陈平安小声道：“我留下了最值钱的一颗蛇胆石，没舍得送出去。”

    阿良哈哈大笑，“倒是鸡贼。”

    队伍最后边，与李槐林守一拉开距离后，朱河一边牵马，一边与女儿低声说道：“千万千万要收好那本紫气书，如果顺利的话，这本书能够让你一路走到第五境！到时候再配合那颗英雄胆，你就稳稳跻身第六境了！”

    少女愕然，“爹，丹药给了我，那你怎么办？”

    朱河轻声笑道：“爹还年轻，如今心气回来了，说不定就能够自己破境，向前走出一大步，便是第七境的高处风光，如今爹也敢想一想了。”

    原本一直心情郁郁的少女，笑逐颜开，道：“还年轻？那爹你要不要在那红烛镇，找个小媳妇美娇娘啊？爹，你放心，我可不拦着。”

    朱河脸色尴尬，瞪了闺女一道：“胡说八道！”

    少女想了想，“爹，那颗丹药你还是留着吧，我如今才二境巅峰，距离第五境都还还早呢。”

    朱河爽朗笑道：“留着也行，就当是你将来的压箱底嫁妆了。”

    清秀少女似乎想起了某人，满脸涨红，朱河心情大好，豪气纵横道：“以后到了咱们大骊京城，看看哪位有福气的世家俊彦，能够娶到我女儿。”

    少女跺脚娇羞道：“爹！”

    朱河赶紧摆手道：“不说了，爹不说了。”

    黄昏里的驿路上，阿良踮起脚跟，不断搓着手，望着那座红烛镇的柔和轮廓，在斗笠汉子眼中，就像一位醉卧酒肆的美妇。

    他急匆匆道：“陈平安，事先说好了，你要借我一颗金锭的。”

    陈平安点了点头，不过有些疑惑，“阿良你会缺钱？”

    阿良咧嘴笑道：“你不懂了吧，行走江湖，借钱的是孙子，还钱的是祖宗，我这一路，被李槐朱鹿这些小屁孩给寒碜得太惨了，一定要过过祖宗的瘾，补偿补偿自己。”

    陈平安无奈道：“那我送你一颗金锭，我不借，只送。”

    阿良一巴掌拍在少年肩头，大笑道：“就这么说好了！金锭白送我。”

    阿良目视前方，抬臂握了握拳，“能够从你这财迷手里白白拿到一颗金锭，我阿良果然猛啊！”

    陈平安对此没有反悔，只是安静望向那座越来越近的红烛镇，熟悉的市井气息扑面而来，再也不是那河水滔滔、深山老林了。

    陈平安转头对身边的红棉袄小姑娘笑道：“到了镇上，等到购置完路上一切吃用，我们就去找找看有没有糖葫芦卖。”

    李宝瓶高兴地蹦蹦跳跳前行，小姑娘轻轻颠着背后那只碧绿小书箱，“小师叔！咱们买两串小糖葫芦就行！小的好吃！”

    （本章完）
------------

next：第一百零五章 无根浮萍

    红烛镇围有高墙，陈平安一行人需要从北门进入小镇，结果很快就发生了意外，墙门有披甲持锐的戍守士卒，需要他们递交户牒关文，才可进入，这让陈平安呆滞当场，他连户牒关文到底什么都不晓得。

    早早拿到手一颗金锭的阿良，笑嘻嘻从怀里掏出一张皱巴巴的公文，结果通过勘验后，这家伙连毛驴也不要了，大摇大摆独自入城，到了墙门洞那边，还不忘跟面面相觑的众人挥手告别，惹来李槐的破口大骂，扬言要将白驴宰了，阿良大笑而去。

    朱河同样束手无策，离开小镇之前，老祖宗并没有专门交代此事，其实除了岁数，朱河对于外边的天地，一概不知，丝毫不比陈平安好多少，至于跋山涉水风餐露宿一事，更是远远不如窑工出身的贫寒少年。朱河灵机一动，想着有钱能使鬼推磨，肯定是放之四海而皆准的道理，就要给一名戍守士卒偷偷塞银子，竟然被那青壮士卒直接拿矛头抵住胸口，厉声训斥，饶是好脾气的朱河也有些火气，五境武夫，若是投军入伍，说不得连手握数千精锐的中层武将也做了，不过朱河正要跟那人理论的时候，朱鹿轻轻拉住他的胳膊，轻声提醒道：“爹，咱们大骊军法赏罚分明，而且有个特点，要么极轻，要么极重，所以不要跟这些当兵的家伙起冲突，咱们老百姓占不到便宜的。”

    朱河皱了皱眉头，冷哼一声，终究还是选择-民不与官斗。

    朱鹿小声安慰道：“爹，以后让老祖宗帮你寻个官家身份，有了护身符后，再加上你的身手，相信很快就可以崭露头角，哪里还需要受这气。”

    朱河大步离开，点点头，回头瞥了眼那守门士卒，嗤笑道：“真是应了那句老话，阎王好见，小鬼难缠。”

    所有人下意识望向陈平安。

    陈平安想了想，缓缓道：“实在没办法，只能绕过红烛镇了，今夜在外边露宿，我们可以雇人帮我们购置一切所需物品，真正的大麻烦，是我们去不了小镇内的水运码头，既定的行程就要修改，原先两百多里水路，沿着绣花江乘船南下，会比我们步行要轻松很多，还不用绕路。”

    就在此时，一位身穿青色官服的中年男子快步走出城门，仔细打量着陈平安一行人，最后望向朱河，抱拳问道：“在下程昇，如今忝为红烛镇枕头驿的驿丞，敢问可是来自龙泉县城的朱河朱先生？”

    朱河默不作声，神色戒备。

    自称驿丞的男人爽朗笑道：“你们家主曾经一封书信，直接寄到了咱们县令大人手上，大略说过了你们的行程安排，让咱们县令大人尽地主之谊，除此之外，你们各有书信家书，已经到了我们枕头驿，我在一旬前便为各位专程腾出了屋子，只能说还算干净素洁，绝不敢说有多好，还望各位贵客包涵，莫要在县令大人那边告状，要不然县尊大人一个不高兴，我恐怕明天就要丢了饭碗喽。”

    这位枕头驿一把交椅猛然记起一事，“若是朱先生不信，我可以马上去驿馆喊来一人，此人就来自龙泉县城的福禄街，说他还是督造官衙署的老衙役，其中有一封来自大骊京城的家书，正是他亲自帮衙署上司带来，说是要亲手交给一位叫林守一的公子。”

    林守一向前走出数步，脸上充满世家子弟的自负倨傲，问道：“我便是龙泉县林守一，敢问程驿丞，那人名叫什么？”

    婢女朱鹿有些发愣，此时的林守一，与印象中那个沉默寡言的冷峻少年，不太一样。

    李宝瓶和李槐视线交汇了一下，各自轻轻点头。

    驿丞程昇言语没有丝毫凝滞，“如果我没有记错的话，应该名叫唐树头，四十来岁，咱们大骊官话说得不是很顺畅，嗯，此人尤其喜欢喝酒，就是酒品……”

    林守一点了点头，随口问道：“驿丞这些日子就一直候在这北门等我们？”

    那男人笑道：“虽然很想点头，但委实是没这脸皮，事实上枕头驿在红烛镇北边，离这不远，二来小镇附近的山头高处，建有烽燧，我与燧长关系不错，便让他帮着盯着北边的下山驿路，只要一看到林公子朱先生的身影，就让他手底下的烽子入城通知我。”

    林守一恍然，不再说话，转头望向陈平安，后者点点头。

    朱河笑着感谢道：“程大人费心了。”

    那驿丞连忙摆手道：“可当不起大人的称呼，不过就是个驴前马后的小人，整天做着伺候贵人的活计，实在难登大雅之堂。先不聊，我去跟戍守士卒知会一声，相信很快就可以进入咱们小镇。”

    驿丞隶属于大骊朝廷，只不过称不上朝廷命官，这类胥吏不入流，不属于品官，清流浊吏之分，是一条巨大鸿沟。

    很快这位驿丞就带领他们走向城墙门道，守城士卒虽然放行，但脸色依然不太好看。

    驿丞率先走过格外荫凉的城墙门洞，转头跟朱河压低嗓音解释道：“都是边境战场上退下来的老兵痞，本事不大，脾气倒是死犟，有些时候连咱们县尊大人都拿他们没辙，朱先生不要跟他们一般见识。”

    朱河再没有江湖经验，可交浅言深的道理还是懂的，就没有答话。

    他们路过一间寒气森森的铺子，不断有青壮男子出入，铺子内时不时亮起一抹白光。

    李槐看得挪不开脚步，朱河忍不住多看了两眼，很快就失去兴趣。

    驿丞说道：“那是一间刀剑铺子，其余兵器也偶有兜售。”

    林守一好奇问道：“官府不管吗？就不怕市井百姓持械斗殴？”

    驿丞笑道：“官府不太管这些，但只要出了事情，会管得很严，若是县衙人手不够，县尊大人能够调动辖境内所有江湖门派，帮着解决纠纷。”

    大骊尚武成风，有很多仗剑佩刀游历四方的游侠儿，既有眼高手低的市井无赖，也有为气任侠的世家子弟，大骊朝廷虽然禁制一切兵器售卖，但是对于铸造工艺平平的寻常刀剑，大多睁一只眼闭一只眼，主要看地方官的态度，若是纯正读书种子出身，多半要严令禁止，如果是沙场武人出身，十之八九会网开一面，当然强弓硬弩、精良甲胄等国之重器，肯定任何地方都不许贩卖。

    烽燧，驿站，集市，酒肆，青楼勾栏，等等，红烛镇应有尽有，热闹非凡，大街上行人如织，比起陈平安他们家乡小镇，要繁华喧嚣太多，街道两边各色铺子，眼花缭乱，吆喝声此起彼伏。

    一路闲聊，一炷香后就来到枕头驿，很快就有驿馆杂役牵走白驴和马匹，驿丞程昇果然给他们安排了驿舍，甲乙两等皆有，他没有擅作主张，而是把五间驿舍丢给朱河，让他们自己安排。

    在陈平安的安排下，李宝瓶和朱鹿住一间甲等驿舍，朱河住一间甲等，他和李槐林守一各住一间乙等驿舍，如果阿良回来，可以随便选一间驿舍合住，当然以阿良的脾气，肯定会问能不能选朱鹿那间，估计到时候少不了朱鹿一顿白眼剐。

    暮色里，所有人各自放好行囊包裹后，聚集在朱河那间宽敞的甲等驿舍，驿丞程昇很快送来一叠书信家书，送完之后便笑着告辞，说有事只要喊一声就可以，还说红烛镇的夜市，在大骊南边小有名气，有机会一定要见识见识。

    林守一有一封，李宝瓶最多，有三封，就连陈平安也有一封，李槐两手空空，最后找到差不多光景的朱鹿，孩子笑道：“还好咱俩同病相怜。”

    朱鹿置若罔闻，走到窗口附近，小小枕头驿馆，曲径幽深，竟然营造出几分庭院深深的世家园林意味，从这边望去，是一座给人感觉不过巴掌大小的小湖，养着一条条臃肿肥胖的红黄锦鲤。

    林守一的家书只有一张信纸，没有几个字，少年深呼吸一口气，将所谓的家书放回信封后，脸色阴沉地离开驿舍，五指死死攥紧那信封，除了三十余个字迹潦草敷衍的行书，信封内还有一张三百两银子的大骊最大钱庄银票。

    少年大踏步走回驿舍，轻轻关上门，将信封放在桌上，脸色铁青，胸膛起伏不定。

    陈平安挑了个僻静位置坐下，李宝瓶跑过来，欲言又止的模样，他笑道：“我如果有不认识的字，会问你的。”

    李宝瓶这才返回桌子那边，开始拆信，三封家书，分别来自父亲、大哥和二哥。

    李宝瓶一封封拆过去，父亲李虹那边在信上说着嘘寒问暖的言语，一如既往，毫无严父的架子，都是叮嘱一些鸡毛蒜皮的小事，比如天冷多穿衣，出门在外别怕花钱，再就是每次经过驿站，一定要给爹娘寄家书，絮絮叨叨，五六张信纸就这么翻没了。李宝瓶叹息一声，望向坐在桌对面喝茶的朱河，忧愁道：“爹娘什么时候，才能不把我当小孩子啊。”

    朱河忍俊不禁，喝茶喝茶。

    李宝瓶浏览第二封信，是他们李家的嫡长孙，她的大哥写的信，如今正在家里研读经籍，准备明年参加科举。信上内容简明扼要，端端正正的楷体字，仿佛充满了先生夫子正襟危坐的韵味，每个笔画都透露出浓重的谨小慎微，满篇说的都是圣贤大道理，要她不可怠慢了朱河朱鹿这对父女，不可以家生子视之，要她多听泥瓶巷陈平安的言语，要能吃苦耐劳，少给别人添麻烦，只是在信的最后，自幼恪守礼仪规矩的大哥，告诉她，她那只小时候从溪里抓回家的螃蟹，如今他已经养出了心得，要她只管放心。

    李宝瓶扬起手中的信纸，跟朱河告状道：“大哥最不心疼我。”

    朱河忍住笑意，心想小姐你就得了吧，谁不知道李家上上下下，就属大公子最心疼你。那么一个说起道理来连老祖宗都头疼的书呆子，第一次喝酒，竟然是茶水被妹妹偷偷换成了自家酿的桃花春烧，把大公子给气得差点崩溃，爹娘见到之后都犯怵，根本不敢劝说什么，只敢跟在跑去找妹妹兴师问罪的儿子身后，生怕这个略显迂腐的儿子一气之下，会动手教训小宝瓶。

    不曾想当他见着了那个丫头，站在院门外，双手叉腰，视死如归，他又给自己的不舍得骂她一声，给结结实实气到了，气得转头就走，生了好几天的闷气。后来他的院子里，那年便埋下了一坛桃花春烧，等到妹妹问起，就说要把她嫁出去，吓得小女孩偷偷离家出走，一个人在龙须溪那边逛荡了一整天，她还差点躲山里头去了。

    李家等到察觉到李宝瓶不见了，老祖宗勃然大怒，出动所有人找寻这个傻丫头，最后还是这位大公子，将功补过，在溪对岸的一座小庙，找到了睡在长木凳上的可怜孩子，背着她回到了家。

    红棉袄小姑娘突然笑道：“不过我还是最喜欢大哥。”

    最后一封信，厚厚一大摞，是李家二公子寄给妹妹的，讲述了他去往大骊京城的经历，都是亲眼所见或是道听途说的奇闻轶事，措辞优美如散文，极富功底，宛如文采天授的诗词大家。这位二公子在福禄街李家，远比大哥更受欢迎，英俊儒雅，却言谈风趣，喜读兵书，自幼就喜欢让府上丫鬟仆役，结阵“厮杀”，相比古板沉闷的长公子，府上下人更喜欢与性情开朗的二公子打交道，逢年过节，二公子见人就会随手丢出一只小绣袋的赏钱，沉甸甸的，若是谁的吉利话说得好，他就会多给一绣袋。

    李宝瓶翻得飞快，看到倒数第二张信纸的时候，抬头望向朱鹿：“我二哥说到你了，说之前跟你说过的大骊烽燧的太平火，他有次在夜宿山巅，亲眼见到了这种边境向京城报平安的烽燧信号，极目远眺，像是一条火焰长龙，很壮观。”

    朱鹿快步走回桌旁坐下，问道：“小姐，还说了什么？”

    李宝瓶干脆就将这摞信纸全部递给朱鹿，反而二哥都是在讲风土人情、山鬼志怪，没什么不可告人的事情。

    朱鹿接过了信，问道：“可以拿回去慢慢看吗？”

    李宝瓶点头道：“别丢了就行。”

    朱鹿满脸喜悦，笑着离去。

    驿丞程昇敲门而入，端来一盆新鲜瓜果。

    身后跟着一位斗笠汉子。

    李槐火冒三丈，跑过去，就要把这个没良心的王八蛋推出屋子。

    阿良一边跟李槐较劲，一屁股坐在桌边凳子上，一脸坏笑问道：“朱鹿咋回事，满脸春风的娇俏模样，好像比平时还要漂亮几分。”

    朱河黑着脸不说话。

    林守一重新返回，坐在陈平安附近，阿良将银色小葫芦抛给林守一，少年拔出酒塞，喝了一口酒。

    阿良转头对驿丞问道：“红烛镇是不是有个敷水湾？离着水运码头不算太远？”

    驿丞脸色古怪，点头道：“有的。”

    阿良啧啧道：“销金窟，销金窟啊。”

    红烛镇有一座月牙状河湾，漂着一种红烛镇独有的精致画舫，长不过两三丈，四周垂挂名贵紫竹或是寻常绿竹，里边装饰的豪奢程度，以画舫主人的财力而定，每艘画舫一般有两到三名女子，多美艳妇人、妙龄少女，琴棋书画茶酒，至少会精通一两种，除了观景雅座，还有一座卧室，其功用不言而喻。

    那些船家女，是世世代代的大骊贱户，相传曾是前朝神水国的亡国遗民，大骊皇帝下过一道圣旨，他们永世不得上岸，要他们生生世世子子孙孙做那无根浮萍。

    红烛镇的百姓则代代相传，不远处的那位棋墩山土地爷，忠义无双，对这些姓氏的先祖的逃亡路途，偷偷庇护，因此惹来大骊皇帝龙颜大怒，从山神贬为土地，下令那几个姓氏的后裔，亲手打碎金身，沉入江底。

    驿丞小心酝酿措辞，挑选了一些无伤大雅的小镇典故，说给这些贵客听。

    红烛镇谈不上大骊的南北枢纽，却也是舟船如梭的一座繁忙水运码头，各地物产汇集。它是三条江水汇合之地，分别是冲澹江，绣花江和玉液江，但是只有两位江神，河畔皆建有江神祠，泥塑金身神像，都是战死于那场水战的大骊功勋水军统领。

    唯独冲澹江不立江神不设祠庙，之后出现过一座香火鼎盛的娘娘庙，供奉一位为证清白、投江自尽的小镇烈女，结果很快就被大骊朝廷定为淫祠，如今只剩下一堆废墟，残砖碎瓦，唯有蛇鼠乱窜。

    当听到棋墩山土地爷的事迹，李槐小声唏嘘道：“没有想到那么一个大坏蛋，在红烛镇的口碑这么好。”

    林守一脸色淡漠，“家家有本难念的经。”

    陈平安收起那封阮秀寄来的书信。

    信上说他买下的落魄山，成功获封一位大骊新晋山神，帮助坐镇山头聚拢灵气，仅次于不参与售卖的披云山，和她爹手握的点灯山。
